import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import { IMethodsProps } from "@type/interface.ts";
import TableRow from "@mui/material/TableRow";
import TableCell from "@mui/material/TableCell";

export default function ScssTitleUA({ searchTerm }: IMethodsProps) {
  const scssTitleData = [
    {
      title: "Вивчення SCSS",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Sass дозволяє використовувати функції, недоступні в самому CSS,
                наприклад, змінні, вкладеності, міксини, успадкування та інші
                приємні речі, що повертають зручність написання CSS.
              </p>
            }
          />
        </>
      ),
    },
  ];

  const filteredScssTitleData = scssTitleData.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredScssTitleData.length > 0 && (
        <Table id="scss_title">
          <TableBody>
            <TableRow>
              <TableCell style={{ border: "none", padding: "5px" }}>
                <h1>Вивчення SCSS.</h1>
              </TableCell>
            </TableRow>
            {filteredScssTitleData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
