import React, { useState } from "react";
import Button from "@mui/material/IconButton";
import "./buttonExample.scss";
import { IButtonExampleWithBtnProps } from "@type/interface";

export default function ButtonExampleWithBtn({
  titleButtonExample,
  title,
  text,
  onClick,
}: IButtonExampleWithBtnProps) {
  const [isExampleOpen, setIsExampleOpen] = useState(false);

  const handleMenuInfoOpen = () => {
    setIsExampleOpen(!isExampleOpen);
  };

  const handleMenuInfoClose = () => {
    setIsExampleOpen(false);
  };

  const tableRowStyle = {
    width: "100%",
    display: "flex",
  };
  return (
    <div id="menu-example">
      <Button className="menu-example-btn" onClick={handleMenuInfoOpen}>
        {titleButtonExample}
      </Button>
      {isExampleOpen && (
        <div style={tableRowStyle} className="table-example">
          <div id={"td"} style={{ border: "none" }} className="colOne">
            <Button onClick={onClick} className="example-btn">
              Нажми
            </Button>
            {title}
          </div>
          <div id={"td"} style={{ border: "none" }} className="colTwo">
            {text}
          </div>
        </div>
      )}
    </div>
  );
}
