import React from "react";
import ButtonPage from "./ButtonPage";
import { ICardPageProps, IButtonPageProps } from "@type/interface";
import "./card.scss";

export default function Card({
  src,
  alt,
  ...buttonProps
}: ICardPageProps & IButtonPageProps) {
  return (
    <div id="card">
      <img className="logoImg" src={src} alt={alt} />
      <ButtonPage {...buttonProps} />
    </div>
  );
}
