import React from "react";
import "@components/Menu/menu.scss";
import { IMenuInfoProps } from "@type/interface";

function MenuBom({
  sectionFirst,
  sectionSecond,
  sectionThird,
  onClose,
}: IMenuInfoProps) {
  return (
    <div className="menu-container">
      <a className="dropdown-item" href="#bom_properties" onClick={onClose}>
        {sectionFirst}
      </a>
      <a className="dropdown-item" href="#bom_console" onClick={onClose}>
        {sectionSecond}
      </a>
      <a className="dropdown-item" href="#bom_method" onClick={onClose}>
        {sectionThird}
      </a>
    </div>
  );
}

export default MenuBom;
