import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import { IMethodsProps } from "@type/interface.ts";
import { buildRU, compilationRU, declarativeRU } from "./JsxConstPre.ts";

export default function JsxRU({ searchTerm }: IMethodsProps) {
  const reactJsx = [
    {
      title: "JSX",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                JSX – это синтаксическое расширение для JavaScript, которое
                позволяет писать код, похожий на HTML, внутри JavaScript-файлов.
                Он используется в таких библиотеках, как React, для описания
                структуры интерфейса пользователя. JSX упрощает создание и
                управление элементами DOM, делая код более читаемым и
                декларативным. Ключевые особенности:
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "Декларативный синтаксис",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Декларативный синтаксис</h3>}
            text={
              <div>
                <p>
                  JSX позволяет описывать, как должен выглядеть интерфейс
                  пользователя, а не как его создавать шаг за шагом.
                </p>
                <pre>
                  <code>{declarativeRU}</code>
                </pre>
              </div>
            }
          />
        </>
      ),
    },
    {
      title: "Встроенный JavaScript",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Встроенный JavaScript</h3>}
            text={
              <div>
                <p>
                  Внутри JSX можно использовать выражения JavaScript, заключив
                  их в фигурные скобки {}. Это позволяет динамически вставлять
                  переменные, функции и другие выражения.
                </p>
                <pre>
                  <code>{buildRU}</code>
                </pre>
              </div>
            }
          />
        </>
      ),
    },
    {
      title: "Компиляция JSX",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Компиляция JSX</h3>}
            text={
              <div>
                <p>
                  Браузеры не понимают JSX непосредственно. Он компилируется в
                  обычный JavaScript с помощью инструментов, таких как Babel,
                  перед тем, как быть выполненным.
                </p>
                <pre>
                  <code>{compilationRU}</code>
                </pre>
              </div>
            }
          />
        </>
      ),
    },
  ];

  const filteredReactJsx = reactJsx.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredReactJsx.length > 0 && (
        <Table id="react_jsx">
          <TableBody>
            <TableOneCol text={<h3>JSX.</h3>} />
            {filteredReactJsx.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
