import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import { IMethodsProps } from "@type/interface.ts";
import TableRow from "@mui/material/TableRow";
import TableCell from "@mui/material/TableCell";

export default function HtmlTitleUA({ searchTerm }: IMethodsProps) {
  const tableTitle = [
    {
      title: "Робота з HTML",
      category: "HTML",
      textForSearch: "Робота з HTML, основні елементи HTML.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Основні елементи є основою будь-якого HTML документа. Ви
                побачите ці елементи у вихідному коді для всіх веб-сторінок
                після встановлення типу документа на першому рядку на сторінці.{" "}
                <b>DOCTYPE</b> визначає, яку версію (X) HTML ця сторінка
                використовує. Елементи сторінки знаходяться між відкриваючим та
                закриваючим тегом &lt;html&gt; &lt;/html&gt;. Елемент
                &lt;html&gt; називається кореневим елементом.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "<html>",
      category: "HTML",
      textForSearch: "<html>, кореневий елемент HTML.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;html&gt; &lt;/html&gt;</h3>}
          text={
            <p>
              Являє собою корінь (елемент верхнього рівня) HTML-документа, тому
              його також називають <b>кореневим елементом</b>. Усі інші елементи
              мають бути нащадками цього елемента (мають знаходитися всередині
              нього).
            </p>
          }
        />
      ),
    },
  ];

  const filteredTitle = tableTitle.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredTitle.length > 0 && (
        <Table id="html-title">
          <TableBody>
            <TableRow>
              <TableCell style={{ border: "none", padding: "5px" }}>
                <h1>Робота з HTML.</h1>
              </TableCell>
            </TableRow>
            <TableOneCol text={<h2>Основні елементи</h2>} />
            {filteredTitle.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
