import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Arrow from "@core/Arrow";
import MenuHttp from "./MenuHttp.tsx";
import "./http.scss";
import AppBar from "@components/AppBar/AppBar.tsx";
import DescriptionUA from "./DescriptionUA.tsx";
import MethodsUA from "./MethodsUA.tsx";
import HttpCodesUA from "./HttpCodesUA.tsx";
import HttpRequestUA from "./HttpRequestUA.tsx";
import HttpFetchUA from "./HttpFetchUA.tsx";

export default function HttpUA() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term: React.SetStateAction<string>) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages active"}
        toUA={"/http/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages"}
        toRU={"/http/ru"}
        titleLangRU={"RU"}
        toHome={"/"}
        toHtml={"/html/ua"}
        toCss={"/css/ua"}
        toScss={"/scss/ua"}
        toJS={"/js/ua"}
        toDom={"/dom/ua"}
        toBom={"/bom/ua"}
        toHttp={"/http/ua"}
        toReact={"/react/ua"}
        toRedux={"/redux/ua"}
        toTS={"/ts/ua"}
        toNext={"/next/ua"}
        nameHome={"Головна сторінка"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
        page={"HTTP"}
        onClick={handleMenuInfoOpen}
        buttonRef={buttonRef}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        {isMenuInfoOpen && ( // тут
          <div ref={menuRef}>
            <MenuHttp
              sectionFirst={"Опис HTTP"}
              sectionSecond={"Методи HTTP запиту"}
              sectionThird={"Інформаційні"}
              sectionFourth={"Успішні"}
              sectionFifth={"Перенаправлення"}
              sectionSixth={"Клієнтські помилки"}
              sectionSeventh={"Серверні помилки"}
              sectionEighth={"Синхронний запит"}
              sectionNinth={"Асинхронний запит"}
              sectionTenth={"HTTP-заголовки"}
              sectionEleventh={"POST"}
              sectionTwelfth={"Прогрес відправлення"}
              sectionThirteenth={"Опис Fetch"}
              sectionFourteenth={"Response"}
              sectionFifteenth={"POST-запити"}
              sectionSixteenth={"FormData"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}

        <TableContainer>
          <DescriptionUA searchTerm={searchTerm} />
          <MethodsUA searchTerm={searchTerm} />
          <HttpCodesUA searchTerm={searchTerm} />
          <HttpRequestUA searchTerm={searchTerm} />
          <HttpFetchUA searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a
            target="_blank"
            href="https://developer.mozilla.org/en-US/docs/Web/HTTP"
          >
            Документація HTTP
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
