import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Arrow from "@core/Arrow";
import MenuHttp from "./MenuHttp.tsx";
import "./http.scss";
import AppBar from "@components/AppBar/AppBar.tsx";
import DescriptionRU from "./DescriptionRU.tsx";
import MethodsRU from "./MethodsRU.tsx";
import HttpCodesRU from "./HttpCodesRU.tsx";
import HttpRequestRU from "./HttpRequestRU.tsx";
import HttpFetchRU from "./HttpFetchRU.tsx";

export default function HttpRU() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term: React.SetStateAction<string>) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages"}
        toUA={"/http/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages active"}
        toRU={"/http/ru"}
        titleLangRU={"RU"}
        toHome={"/home/ru"}
        toHtml={"/html/ru"}
        toCss={"/css/ru"}
        toScss={"/scss/ru"}
        toJS={"/js/ru"}
        toDom={"/dom/ru"}
        toBom={"/bom/ru"}
        toHttp={"/http/ru"}
        toReact={"/react/ru"}
        toRedux={"/redux/ru"}
        toTS={"/ts/ru"}
        toNext={"/next/ru"}
        nameHome={"Главная страница"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
        page={"HTTP"}
        onClick={handleMenuInfoOpen}
        buttonRef={buttonRef}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuHttp
              sectionFirst={"Описание HTTP"}
              sectionSecond={"Методы HTTP запроса"}
              sectionThird={"Информационные"}
              sectionFourth={"Успешные"}
              sectionFifth={"Перенаправления"}
              sectionSixth={"Клиентские ошибки"}
              sectionSeventh={"Серверные ошибки"}
              sectionEighth={"Синхронный запрос"}
              sectionNinth={"Асинхронный запрос"}
              sectionTenth={"HTTP-заголовки"}
              sectionEleventh={"POST"}
              sectionTwelfth={"Прогресс отправки"}
              sectionThirteenth={"Описание Fetch"}
              sectionFourteenth={"Response"}
              sectionFifteenth={"POST-запросы"}
              sectionSixteenth={"FormData"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}

        <TableContainer>
          <DescriptionRU searchTerm={searchTerm} />
          <MethodsRU searchTerm={searchTerm} />
          <HttpCodesRU searchTerm={searchTerm} />
          <HttpRequestRU searchTerm={searchTerm} />
          <HttpFetchRU searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a
            target="_blank"
            href="https://developer.mozilla.org/ru/docs/Web/HTTP"
          >
            Документация HTTP
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
