export const buildRU: string = `
const items = ['Молоко', 'Хлеб', 'Сыр'];

const shoppingList = (
  <div>
    <h1>Список покупок</h1>
    <ul>
      {items.map(item => <li>{item}</li>)}
    </ul>
  </div>
);
`;

