import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import ButtonExampleWithBtn from "@core/ButtonExampleWithBtn.tsx";
import {
  objectProtoConst,
  objectCreateConst,
  objectSetConst,
  objectGetConst,
} from "./ProtoConstPre.ts";
import { objectProto, objectCreate, objectSet, objectGet } from "./proto.js";
import { IMethodsProps } from "@type/interface.ts";

export default function ProtoRU({ searchTerm }: IMethodsProps) {
  const tableProto = [
    {
      title: "Прототип объекта",
      textForSearch:
        "Объекты в JavaScript можно организовать в цепочки так, чтобы свойство, не найденное в одном объекте, автоматически искалось бы в другом.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Объекты в JavaScript можно организовать в цепочки так, чтобы
                свойство, не найденное в одном объекте, автоматически искалось
                бы в другом.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "__proto__",
      textForSearch:
        "Если у объекта присутствует ссылка __proto__ ведущая на другой объект, то когда будет вызвано какое-то свойство у данного объекта и оно не будет найдено, тогда поиск перейдёт по цепочке к связанному объекту через __proto__. На данный момент __proto__ считается устаревшим, и по стандарту оно должно поддерживаться только браузерами.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>__proto__</h3>}
            text={
              <p>
                Если у объекта присутствует ссылка __proto__ ведущая на другой
                объект, то когда будет вызвано какое-то свойство у данного
                объекта и оно не будет найдено, тогда поиск перейдёт по цепочке
                к связанному объекту через __proto__ . <br />
                На данный момент __proto__ считается устаревшим, и по стандарту
                оно должно поддерживаться только браузерами.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "Пример proto",
      textForSearch:
        "Рассмотрим пример: есть два объекта people и masha. Когда мы будем вызвать masha.eats - то мы его не найдём и перейдём по цепочке в people.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExampleWithBtn
              titleButtonExample={"Пример proto"}
              title={
                <p id="formated-text">
                  <span>
                    Рассмотрим пример: есть два объекта people и masha. Когда мы
                    будем вызвать masha.eats - то мы его не найдём и перейдём по
                    цепочке в people.
                  </span>
                  <br />
                  <br />
                  <span id="jsProto"></span>
                </p>
              }
              text={
                <pre>
                  <code>{objectProtoConst}</code>
                </pre>
              }
              onClick={objectProto}
            />
          }
        />
      ),
    },
    {
      title: "Object.create (proto, descriptors)",
      textForSearch:
        "Создаёт новый объект с указанным прототипом и свойствами.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Object.create (proto, descriptors)</h3>}
            text={
              <p>Создаёт новый объект с указанным прототипом и свойствами.</p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример create"}
                title={
                  <p id="formated-text">
                    <span>
                      Рассмотрим пример: создаём новый объект masha с прототипом
                      people.
                    </span>
                    <br />
                    <br />
                    <span id="jsObjectCreate"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{objectCreateConst}</code>
                  </pre>
                }
                onClick={objectCreate}
              />
            }
          />
        </>
      ),
    },
    {
      title: "Object.setPrototypeOf (object, proto)",
      textForSearch:
        "Способен установить прототип указанного объекта в другой объект.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Object.setPrototypeOf (object, proto)</h3>}
            text={
              <p>
                Способен установить прототип указанного объекта в другой объект.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример setPrototypeOf"}
                title={
                  <p id="formated-text">
                    <span>
                      Рассмотрим пример: передаём в объект masha свойство sport
                      и прототип объекта people.
                    </span>
                    <br />
                    <br />
                    <span id="jsObjectSet"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{objectSetConst}</code>
                  </pre>
                }
                onClick={objectSet}
              />
            }
          />
        </>
      ),
    },
    {
      title: "Object.getPrototypeOf (object)",
      textForSearch: "Способен вернуть прототип свойств указанного объекта.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Object.getPrototypeOf (object)</h3>}
            text={<p>Способен вернуть прототип свойств указанного объекта.</p>}
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример getPrototypeOf"}
                title={
                  <p id="formated-text">
                    <span>
                      Рассмотрим пример: передаём в объект masha свойство sport
                      и прототип объекта people.
                    </span>
                    <br />
                    <br />
                    <span id="jsObjectGet"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{objectGetConst}</code>
                  </pre>
                }
                onClick={objectGet}
              />
            }
          />
        </>
      ),
    },
  ];

  const filteredProto = tableProto.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredProto.length > 0 && (
        <Table id="js_proto">
          <TableBody>
            <TableOneCol text={<h2>Прототип объекта.</h2>} />
            {filteredProto.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
