import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { IMethodsProps } from "@type/interface.ts";
import { useForwardRef } from "./RefForwardConstPre";
import MyComponent from "./MyComponent";

export default function RefForwardRU({ searchTerm }: IMethodsProps) {
  const forwardRef = [
    {
      title: "forwardRef",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                forwardRef — это функция React, которая позволяет передавать
                ссылки (ref) из родительского компонента в его дочерний
                компонент. Она используется, когда вы хотите, чтобы родительский
                компонент имел прямой доступ к DOM-элементу, который находится
                внутри дочернего компонента. <br />
                Обычно вы не можете передать ref как обычный пропс. forwardRef
                решает эту проблему, предоставляя компоненту, который его
                принимает, доступ к ref, который можно привязать к внутреннему
                DOM-элементу.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "forwardRef",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример forwardRef"}
              title={
                <div>
                  <MyComponent />
                  <p>
                    forwardRef позволяет MyInput получать ссылку (ref) как
                    второй аргумент. Мы передаем эту ссылку (ref) к нативному
                    элементу input, что позволяет родительскому компоненту
                    получить к нему доступ.
                    <br />
                    MyComponent создает ссылку с помощью useRef. Эта ссылка
                    передается в MyInput через пропс ref. Благодаря forwardRef,
                    React знает, что нужно "переправить" эту ссылку к
                    внутреннему input.
                  </p>
                </div>
              }
              text={
                <pre>
                  <code>{useForwardRef}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredForwardRef = forwardRef.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredForwardRef.length > 0 && (
        <Table id="react_forwardRef">
          <TableBody>
            <TableOneCol text={<h3>forwardRef.</h3>} />
            {filteredForwardRef.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
