import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { IMethodsProps } from "@type/interface.ts";
import { useForwardRef } from "./RefForwardConstPre";
import MyComponent from "./MyComponent";

export default function RefForwardUA({ searchTerm }: IMethodsProps) {
  const forwardRef = [
    {
      title: "forwardRef",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                forwardRef — це функція React, яка дозволяє передавати посилання
                (ref) з батьківського компонента до його дочірнього компонента.
                Вона використовується, коли ви хочете, щоб батьківський
                компонент мав прямий доступ до DOM-елемента, що знаходиться
                всередині дочірнього компонента. <br />
                Зазвичай, ви не можете передати ref як звичайний пропс.
                forwardRef вирішує цю проблему, надаючи компоненті, що його
                приймає, доступ до ref, який можна прив'язати до внутрішнього
                DOM-елемента.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "forwardRef",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Приклад forwardRef"}
              title={
                <div>
                  <MyComponent />
                  <p>
                    forwardRef дозволяє MyInput отримувати посилання (ref) як
                    другий аргумент. Ми передаємо це посилання (ref) до
                    нативного input елемента, що дозволяє батьківському
                    компоненту отримати до нього доступ.
                    <br />
                    MyComponent створює посилання за допомогою useRef. Це
                    посилання передається до MyInput через пропс ref. Завдяки
                    forwardRef, React знає, що потрібно "переправити" це
                    посилання до внутрішнього input.
                  </p>
                </div>
              }
              text={
                <pre>
                  <code>{useForwardRef}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredForwardRef = forwardRef.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredForwardRef.length > 0 && (
        <Table id="react_forwardRef">
          <TableBody>
            <TableOneCol text={<h3>forwardRef.</h3>} />
            {filteredForwardRef.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
