export const assertionOne = `let code: any = 123; 
let employeeCode = <number> code;  
console.log(typeof employeeCode); // number
`;

export const assertionTwo = `let code: any = 123; 
let employeeCode = code as number;
console.log(typeof employeeCode); // number
`;

export const assertionThree = `type Person = {
    name: string;
    age: number;
};

const bill = {
    name: "Bill",
    age: 35,
};

function printPerson(person: Person) {
    console.log(\`Name: \${person.name}\`);
    console.log(\`Age: \${person.age}\`);
}

bill.name = "Belly";
printPerson(bill); // Name: Belly Age: 35
`;

export const assertionFour = `type Person = {
    name: string;
    age: number;
};

const john = {
    name: "John",
    age: 30,
} as const;  

function printPerson(person: Person) {
    console.log(\`Name: \${person.name}\`);
    console.log(\`Age: \${person.age}\`);
}

john.name = "Johny";
printPerson(john); // Error
`;
