import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function HooksTitleRU({ searchTerm }: IMethodsProps) {
  const reactHooks = [
    {
      title: "Хуки",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Хуки (Hooks) — это специальные функции в React, которые
                позволяют использовать состояние и другие возможности React в
                функциональных компонентах. До появления хуков эти возможности
                были доступны только в классовых компонентах. Хуки позволили
                писать компоненты проще, избегая сложности классов,
                конструкторов, привязки this и методов жизненного цикла.
              </p>
            }
          />
        </>
      ),
    },
  ];

  const filteredReactHooks = reactHooks.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredReactHooks.length > 0 && (
        <Table id="react_hooks">
          <TableBody>
            <TableOneCol text={<h2>Хуки.</h2>} />
            {filteredReactHooks.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
