export const formControlled: string = `
import React, { useState } from 'react';

function FormControlled() {
  const [value, setValue] = useState("");

  const handleChange = (event) => {
    setValue(event.target.value);
  };

  const handleSubmit = (event) => {
    alert("You sended name: " + value);
    event.preventDefault();
  };

  return (
    <form onSubmit={handleSubmit}>
      <label>
        Name:
        <input type="text" value={value} onChange={handleChange} />
      </label>
      <button type="submit">Send</button>
    </form>
  );
}
export default FormControlled;
`;
export const formUncontrolled: string = `
import React, { useRef } from 'react';

function FormUncontrolled() {
  const inputRef = useRef(null);

  const handleSubmit = (event) => {
    alert("You sended name: " + inputRef.current.value);
    event.preventDefault();
  };

  return (
    <form onSubmit={handleSubmit}>
      <label>
        Name:
        <input type="text" ref={inputRef} />
      </label>
      <button type="submit">Send</button>
    </form>
  );
}
export default FormUncontrolled;
`;

export const formExamples: string = `
import React, { Component } from "react";

const POSITIONS = [
  {
    id: "fd",
    value: "Front-end Developer",
    title: "Front-end Developer",
  },
  {
    id: "bd",
    value: "Back-end Developer",
    title: "Back-end Developer",
  },
];

export default function FormModern() {
  const [formData, setFormData] = useState({
    name: "",
    text: "",
    position: "Front-end Developer",
  });
  const [showData, setShowData] = useState({
    name: "",
    text: "",
    position: "",
  });

  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  const handleShow = (e) => {
    e.preventDefault();
    setShowData(formData);
    setFormData({
      name: "",
      text: "",
      position: "Front-end Developer",
    });
  };

  return (
    <div>
      <form className="basic-form">
        <label>
          Name:
          <input
            type="text"
            name="name"
            value={formData.name}
            onChange={handleInputChange}
          />
        </label>
        <label>
          Text:
          <textarea
            name="text"
            value={formData.text}
            onChange={handleInputChange}
          />
        </label>
        <select
          name="position"
          value={formData.position}
          onChange={handleInputChange}
        >
          {POSITIONS.map(({ id, value, title }) => (
            <option key={id} value={value}>
              {title}
            </option>
          ))}
        </select>
        <button onClick={handleShow}>Show</button>
      </form>
      <h2>{showData.name}</h2>
      <h3>{showData.text}</h3>
      <h3>{showData.position}</h3>
    </div>
  );
}

`;
