import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import {
  utilityRecord,
  utilityReadonly,
  utilityPartial,
  utilityRequired,
  utilityPick,
  utilityOmit,
  utilityExclude,
  utilityExtract,
  utilityNonNullable,
  utilityParameters,
  utilityReturnType,
} from "./UtilityTypesConstPre.ts";
import { getFormatedText } from "@core/getFormatedText.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function UtilityTypesRU({ searchTerm }: IMethodsProps) {
  const tsUtilityTypes = [
    {
      title: "Utility Types",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b>Utility Types</b> – это типы данных, которые предоставляют
              утилиты для работы с другими типами данных. Они могут быть
              использованы для упрощения кода, повышения типобезопасности и
              улучшения читабельности.
            </p>
          }
        />
      ),
    },
    {
      title: "Utility Types, Record",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b> Record</b> - создает новый тип данных, который содержит
              свойства с указанными именами и типами. <br />
              {getFormatedText(
                `type Record<K extends string | number | symbol, T> = { [P in K]: T; }`
              )}
            </p>
          }
        />
      ),
    },
    {
      title: "Utility Types, Record",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример Record"}
              title={<></>}
              text={
                <pre>
                  <code>{utilityRecord}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
    {
      title: "Utility Types, Readonly",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b> Readonly</b> используется для создания типа данных, который
              содержит только свойства исходного типа, но только для чтения. Это
              означает, что свойства исходного типа могут быть прочитаны, но не
              могут быть изменены. <br />
              {getFormatedText(
                `type Readonly<T> = { readonly [P in keyof T]: T[P]; }`
              )}
            </p>
          }
        />
      ),
    },
    {
      title: "Utility Types, Readonly",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример Readonly"}
              title={
                <p>
                  Например, если у нас есть тип данных Person со свойствами name
                  и age, мы можем создать новый тип данных PersonReadonly,
                  который содержит все свойства Person, но только для чтения:
                </p>
              }
              text={
                <pre>
                  <code>{utilityReadonly}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
    {
      title: "Utility Types, Partial",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b> Partial</b> - создает новый тип данных, который содержит все
              свойства исходного типа, но с указанными свойствами, которые могут
              быть опущены. <br />
              {getFormatedText(
                `type Partial<T> = { [P in keyof T]?: T[P] | undefined; }`
              )}
            </p>
          }
        />
      ),
    },
    {
      title: "Utility Types, Partial",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример Partial"}
              title={
                <p>
                  Например, если у нас есть тип данных Person со свойствами name
                  и age, мы можем создать новый тип данных PersonPartial,
                  который содержит все свойства Person, но может быть опущено
                  свойство age:
                </p>
              }
              text={
                <pre>
                  <code>{utilityPartial}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
    {
      title: "Utility Types, Required",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b> Required </b>- создает новый тип данных, который содержит все
              свойства исходного типа, но с указанными свойствами, которые
              должны быть предоставлены. <br />
              {getFormatedText(
                `type Required<T> = { [P in keyof T]-?: T[P]; }`
              )}
            </p>
          }
        />
      ),
    },
    {
      title: "Utility Types, Required",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример Required"}
              title={
                <p>
                  Например, если у нас есть тип данных Person со свойствами name
                  и age, мы можем создать новый тип данных PersonRequired,
                  который содержит все свойства Person, но должно быть
                  предоставлено свойство name:
                </p>
              }
              text={
                <pre>
                  <code>{utilityRequired}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
    {
      title: "Utility Types, Pick",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b> Pick </b> – создает новый тип данных, который содержит только
              указанные свойства исходного типа. <br />
              {getFormatedText(
                `type Pick<T, K extends keyof T> = { [P in K]: T[P]; }`
              )}
            </p>
          }
        />
      ),
    },
    {
      title: "Utility Types, Pick",
      jsx: (
        <ButtonExample
          titleButtonExample={"Пример Pick"}
          title={
            <p id="formated-text">
              Например, если у нас есть тип данных Person со свойствами name,
              age и address, мы можем создать новый тип данных PersonPick,
              который содержит только свойства name и age:
            </p>
          }
          text={
            <pre>
              <code>{utilityPick}</code>
            </pre>
          }
        />
      ),
    },
    {
      title: "Utility Types, Omit",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b> Omit </b>- создает новый тип данных, который содержит
              указанные свойства исходного типа. <br />
              {getFormatedText(
                `type Omit<T, K extends string | number | symbol> = { [P in Exclude<keyof T, K>]: T[P]; }`
              )}
            </p>
          }
        />
      ),
    },
    {
      title: "Utility Types, Omit",
      jsx: (
        <ButtonExample
          titleButtonExample={"Пример Omit"}
          title={
            <p>
              Например, если у нас есть тип данных Person со свойствами name,
              age и address, мы можем создать новый тип данных PersonOmit,
              который не содержит свойство address:
            </p>
          }
          text={
            <pre>
              <code>{utilityOmit}</code>
            </pre>
          }
        />
      ),
    },
    {
      title: "Utility Types, Exclude",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b>Exclude</b> - создает новый тип данных, который содержит
              указанный тип данных. <br />
              {getFormatedText(`type Exclude<T, U> = T extends U ? never : T`)}
            </p>
          }
        />
      ),
    },
    {
      title: "Utility Types, Exclude",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример Exclude"}
              title={
                <>
                  <p id="formated-text"></p>
                  <pre>
                    <code>{utilityExclude}</code>
                  </pre>
                </>
              }
              text={
                <pre>
                  <code>{}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
    {
      title: "Utility Types, Extract",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b>Extract</b> – создает новый тип данных, который содержит только
              указанные типы данных. <br />
              {getFormatedText(`type Extract<T, U> = T extends U ? T : never`)}
            </p>
          }
        />
      ),
    },
    {
      title: "Utility Types, Extract",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример Extract"}
              title={
                <p>
                  Например, если у нас есть тип данных Person или Employee, мы
                  можем создать новый тип данных PersonExtract, который содержит
                  только свойства name и age:
                </p>
              }
              text={
                <pre>
                  <code>{utilityExtract}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
    {
      title: "Utility Types, NonNullable",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b> NonNullable </b>- создает новый тип данных, который содержит
              значения null или undefined. <br />
              {getFormatedText(`type NonNullable<T> = T & {}`)}
            </p>
          }
        />
      ),
    },
    {
      title: "Utility Types, NonNullable",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример NonNullable"}
              title={
                <p>
                  Например, если у нас есть тип данных Person, который может
                  содержать свойство address, мы можем создать новый тип данных
                  PersonNonNullable, который не содержит свойство address с
                  типом данных string | null | undefined:
                </p>
              }
              text={
                <pre>
                  <code>{utilityNonNullable}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
    {
      title: "Utility Types, Parameters",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b> Parameters</b> – создает новый тип данных, который содержит
              типы данных параметров функции. <br />
              {getFormatedText(
                `type Parameters<T extends (...args: any) => any> = T extends (...args: infer P) => any ? P : never`
              )}
            </p>
          }
        />
      ),
    },
    {
      title: "Utility Types, Parameters",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример Parameters"}
              title={
                <p>
                  Например, мы можем создать новый тип данных
                  ParametersFunction, который содержит типы данных параметров
                  функции add:
                </p>
              }
              text={
                <pre>
                  <code>{utilityParameters}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
    {
      title: "Utility Types, ReturnType",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b> ReturnType </b>- создает новый тип данных, который содержит
              тип возвращаемого значения функции. <br />
              {getFormatedText(
                `type ReturnType<T extends (...args: any) => any> = T extends (...args: any) => infer R ? R : any`
              )}
            </p>
          }
        />
      ),
    },
    {
      title: "Utility Types, ReturnType",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример ReturnType"}
              title={
                <p>
                  Например, мы можем создать новый тип данных
                  ReturnTypeFunction, который содержит тип возвращаемого
                  значения функции add:
                </p>
              }
              text={
                <pre>
                  <code>{utilityReturnType}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filtered = tsUtilityTypes.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filtered.length > 0 && (
        <Table id="ts_utilityTypes">
          <TableBody>
            <TableOneCol text={<h3>Utility Types.</h3>} />
            {filtered.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
