import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { listener, target } from "./DomConstPre.tsx";
import { listenerFn, listenerFn2 } from "./DomFunc.js";
import { IMethodsProps } from "@type/interface.ts";

export default function ListenerRU({ searchTerm }: IMethodsProps) {
  const tableListener = [
    {
      title: ".addEventListener()",
      category: "DOM",
      textForSearch: "Добавление обработчика события, прослушивание событий.",
      jsx: (
        <TableTwoCol
          title={<h3>.addEventListener()</h3>}
          text={
            <p>
              Это функция, которая первым параметром принимает название события
              (<b>event</b>), а вторым параметром функцию, которая выполнится,
              когда мы кликнем.
              <br />
              <code>element.addEventListener(event, handler)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".removeEventListener()",
      category: "DOM",
      textForSearch: "Удаление обработчика события.",
      jsx: (
        <TableTwoCol
          title={<h3>.removeEventListener()</h3>}
          text={
            <p>
              Используется для удаления обработчика события.
              <br />
              <code>element.removeEventListener(event, handler)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".dispatchEvent()",
      category: "DOM",
      textForSearch: "Генерация события программно.",
      jsx: (
        <TableTwoCol
          title={<h3>.dispatchEvent()</h3>}
          text={
            <p>
              Генерирует событие на объекте.
              <br />
              <code>element.dispatchEvent(event)</code>
            </p>
          }
        />
      ),
    },
    {
      title: "Пример listener",
      category: "DOM",
      textForSearch: "Пример addEventListener, событие mouseenter.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример listener"}
              title={
                <p id="formated-text">
                  <span>
                    При наведении на первый элемент, появляется второй.
                  </span>
                  <div onMouseEnter={listenerFn} className="firstElement">
                    <p>First element</p>
                  </div>
                  <div style={{ display: "none" }} className="secondElement">
                    <p>Second element</p>
                  </div>
                </p>
              }
              text={
                <pre>
                  <code>{listener}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const tableDelegation = [
    {
      title: "event.target",
      category: "DOM",
      textForSearch: "Инициатор события, ссылка на элемент.",
      jsx: (
        <TableTwoCol
          title={<h3>event.target</h3>}
          text={
            <p>Является ссылкой на объект, который был инициатором события.</p>
          }
        />
      ),
    },
    {
      title: "event.stopPropagation()",
      category: "DOM",
      textForSearch: "Остановка всплытия событий.",
      jsx: (
        <TableTwoCol
          title={<h3>event.stopPropagation()</h3>}
          text={<p>Для остановки всплытия нужно вызвать этот метод.</p>}
        />
      ),
    },
    {
      title: "Пример всплытия",
      category: "DOM",
      textForSearch: "Пример всплытия событий.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример всплытия"}
              title={
                <section
                  className="first_form"
                  onClick={() => alert("section")}
                >
                  section
                  <form onClick={() => alert("form")}>
                    form
                    <div onClick={() => alert("div")}>div</div>
                  </form>
                </section>
              }
              text={
                <p id="formated-text">
                  Если в примере выше кликнуть на <b>div</b>, то последовательно
                  выведутся alert: div → form → section. Этот процесс называется
                  <b>всплытием</b>, потому что события «всплывают» от
                  внутреннего элемента вверх через родителей, подобно тому, как
                  всплывает пузырёк воздуха в воде.
                </p>
              }
            />
          }
        />
      ),
    },
    {
      title: "Пример event.target",
      category: "DOM",
      textForSearch: "Пример event.target, this.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример event.target"}
              title={
                <p id="formated-text">
                  <b>event.target</b> – это исходный элемент, на котором
                  произошло событие, в процессе всплытия он неизменен. <br />
                  <b>this</b> – это текущий элемент, до которого дошло всплытие,
                  на нём сейчас выполняется обработчик.
                  <section onMouseEnter={listenerFn2} className="second_form">
                    section
                    <form>
                      form
                      <div>div</div>
                    </form>
                  </section>
                </p>
              }
              text={
                <pre>
                  <code>{target}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredListener = tableListener.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredDelegation = tableDelegation.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredListener.length > 0 && (
        <Table id="dom_listener">
          <TableBody>
            <TableOneCol text={<h3>Обработчик.</h3>} />,
            {filteredListener.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredDelegation.length > 0 && (
        <Table id="dom_delegation">
          <TableBody>
            <TableOneCol text={<h3>Делегирование событий.</h3>} />
            {filteredDelegation.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
