import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function TableUA({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "Зміст таблиць",
      category: "HTML",
      textForSearch:
        "Зміст таблиць, <table>, <caption>, <col>, <colgroup>, <td>, <th>, <tr>, <thead>, <tbody>, <tfoot>.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Ці елементи використовуються для створення та обробки табличних
                даних.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "<caption>",
      category: "HTML",
      textForSearch: "<caption>, заголовок таблиці, table.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;caption&gt; &lt;/caption&gt;</h3>}
          text={
            <p>
              Елемент заголовка таблиці. Якщо цей елемент використовується, він
              завжди повинен бути першим вкладеним елементом тега &lt;table&gt;.
            </p>
          }
        />
      ),
    },
    {
      title: "<col>",
      category: "HTML",
      textForSearch: "<col>, стовпець, колонка, colgroup.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;col /&gt;</h3>}
          text={
            <p>
              Визначає стовпець у таблиці та використовується для визначення
              загальної семантики на всіх осередках. Зазвичай він знаходиться в
              елементі &lt;colgroup&gt;.
            </p>
          }
        />
      ),
    },
    {
      title: "<colgroup>",
      category: "HTML",
      textForSearch: "<colgroup>, група стовпців, table.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;colgroup&gt; &lt;/colgroup&gt;</h3>}
          text={<p>Визначає групу стовпців у таблиці.</p>}
        />
      ),
    },
    {
      title: "<table>",
      category: "HTML",
      textForSearch: "<table>, двовимірна таблиця, рядки, стовпці.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;table&gt; &lt;/table&gt;</h3>}
          text={
            <p>
              Інформація представлена у двовимірній таблиці, що складається з
              рядків і стовпців осередків, що містять дані.
            </p>
          }
        />
      ),
    },
    {
      title: "<td>",
      category: "HTML",
      textForSearch: "<td>, комірка таблиці, осередок з даними, table.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;td&gt; &lt;/td&gt;</h3>}
          text={<p>Визначає осередок таблиці, який містить дані.</p>}
        />
      ),
    },
    {
      title: "<th>",
      category: "HTML",
      textForSearch: "<th>, заголовок осередку, заголовок групи осередків.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;th&gt; &lt;/th&gt;</h3>}
          text={<p>Визначає осередок як заголовок групи осередків таблиці.</p>}
        />
      ),
    },
    {
      title: "<tr>",
      category: "HTML",
      textForSearch: "<tr>, рядок, ряд осередків, table.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;tr&gt; &lt;/tr&gt;</h3>}
          text={<p>Визначає ряд осередків у таблиці.</p>}
        />
      ),
    },
    {
      title: "<thead>",
      category: "HTML",
      textForSearch: "<thead>, заголовок таблиці, header.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;thead&gt; &lt;/thead&gt;</h3>}
          text={<p>Набір рядків, що визначають заголовок стовпців таблиці.</p>}
        />
      ),
    },
    {
      title: "<tbody>",
      category: "HTML",
      textForSearch: "<tbody>, тіло таблиці, body.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;tbody&gt; &lt;/tbody&gt;</h3>}
          text={<p>Набір рядків таблиці, що становлять тіло таблиці.</p>}
        />
      ),
    },
    {
      title: "<tfoot>",
      category: "HTML",
      textForSearch: "<tfoot>, підвал таблиці, footer.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;tfoot&gt; &lt;/tfoot&gt;</h3>}
          text={
            <p>
              Елемент підвалу таблиці визначальний набір рядків, що підсумовують
              стовпці таблиці.
            </p>
          }
        />
      ),
    },
  ];

  const filteredTableData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredTableData.length > 0 && (
        <Table id="html_table">
          <TableBody>
            <TableOneCol text={<h2>Зміст таблиць.</h2>} />
            {filteredTableData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
