import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { IMethodsProps } from "@type/interface.ts";
import FriendsList from "./FriendsList";
import { friendsList } from "./UseDebugValueConstPre";

export default function UseDebugValueUA({ searchTerm }: IMethodsProps) {
  const useDebugValue = [
    {
      title: "useDebugValue",
      jsx: (
        <TableOneCol
          text={
            <>
              <p>
                useDebugValue — це спеціальний хук, призначений для використання
                всередині ваших власних (custom) хуків. Його єдина мета —
                відображати значення у DevTools React. Це допомагає вам
                налагоджувати власні хуки, дозволяючи бачити, яке значення вони
                повертають, без необхідності додавати console.log.
                <ul>
                  useDebugValue приймає два аргументи:
                  <li>
                    value - значення, яке ви хочете відобразити в DevTools.
                  </li>
                  <li>
                    format (необов'язковий) - функція форматування, яка приймає
                    value і повертає відформатований рядок.
                  </li>
                </ul>
              </p>
            </>
          }
        />
      ),
    },
    {
      title: "useDebugValue",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Приклад useDebugValue"}
              title={
                <>
                  <FriendsList />
                  <ul>
                    useFriendStatus:
                    <li>
                      isOnline ініціалізується як null, що означає, що статус ще
                      не відомий.
                    </li>
                    <li>
                      useEffect - імітує запит до мережі за допомогою
                      setTimeout. Через секунду він оновлює стан, встановлюючи
                      isOnline в true для друзів з парним ID та в false для
                      непарних.
                    </li>
                    <li>
                      useDebugValue - цей хук є головним тут. Він дозволяє вам
                      переглядати значення isOnline безпосередньо в DevTools
                      React. Якщо друг онлайн, в DevTools ви побачите мітку
                      Online, а якщо офлайн — Offline.
                    </li>
                  </ul>
                  <ul>
                    FriendListItem
                    <li>Він приймає friendID як пропс.</li>
                    <li>
                      Викликає useFriendStatus(friendID), щоб отримати статус
                      друга.
                    </li>
                    <li>
                      Залежно від значення isOnline, змінює колір тексту на
                      зелений (Online) або червоний (Offline) і відображає
                      відповідний текст.
                    </li>
                  </ul>
                  <p>
                    FriendListItem рендерить простий список &lt;ul&gt; з двома
                    елементами &lt;li&gt;, використовуючи FriendListItem для
                    кожного друга з ID 1 та 2.
                  </p>
                </>
              }
              text={
                <pre>
                  <code>{friendsList}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredUseDebugValue = useDebugValue.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredUseDebugValue.length > 0 && (
        <Table id="react_useDebugValue">
          <TableBody>
            <TableOneCol text={<h3>useDebugValue.</h3>} />
            {filteredUseDebugValue.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
