import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import { IMethodsProps } from "@type/interface.ts";
import ButtonExample from "@core/ButtonExample.tsx";
import TemperatureCalculator from "./Temperature.tsx";
import { temperature } from "./TemperatureConstPre.ts";

export default function StateUpUA({ searchTerm }: IMethodsProps) {
  const reactStateUp = [
    {
      title: "Підйом стану, Lifting State Up",
      jsx: (
        <>
          <TableOneCol
            text={
              <div>
                <p>
                  Підйом стану — це патерн у React, який використовується для
                  синхронізації стану між кількома дочірніми компонентами. Він
                  полягає в тому, щоб перенести стан із дочірніх компонентів у
                  їхнього найближчого спільного предка. Це робить стан
                  "спільним", і батьківський компонент може керувати ним,
                  передаючи дані дочірнім компонентам через пропси.
                </p>
                <ul>
                  Цей патерн необхідний, коли:
                  <li>
                    Кілька компонентів потребують одного і того ж стану.
                    Наприклад, два компоненти, що відображають температуру,
                    повинні показувати однакове значення.
                  </li>
                  <li>
                    Дочірній компонент має впливати на інший дочірній компонент.
                    Дочірній компонент A повинен якось змінити компонент B.
                  </li>
                </ul>

                <ul>
                  Переваги "Підйому стану"
                  <li>
                    Синхронізація. Дозволяє легко підтримувати синхронізацію
                    стану між компонентами.
                  </li>
                  <li>
                    Централізація. Стан знаходиться в одному місці, що полегшує
                    його відстеження, розуміння та відлагодження.
                  </li>
                  <li>
                    Простота. Дочірні компоненти стають простішими, оскільки їм
                    не потрібно керувати своїм власним станом.
                  </li>
                </ul>
              </div>
            }
          />
        </>
      ),
    },
    {
      title: "Підйом стану, Lifting State Up",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Приклад"}
              title={
                <>
                  <TemperatureCalculator />
                  <p>
                    toCelsius(fahrenheit) та toFahrenheit(celsius). Ці функції
                    виконують основну математичну логіку перетворення
                    температур. Вони знаходяться поза компонентом, що робить код
                    чистішим.
                    <br />
                    tryConvert(temperature, convert). Ця функція перевіряє, чи є
                    вхідні дані числом. Якщо ні, повертає порожній рядок. <br />
                    TemperatureInput відображає одне поле введення. Він отримує
                    свої дані (temperature і scale) і функцію для обробки змін
                    (onTemperatureChange) через пропси. <br />
                    handleChange викликає функцію, передану з батьківського
                    компонента (onTemperatureChange), відправляючи вгору нове
                    значення з поля введення.
                    <br />
                    const [state, setState] зберігає стан. handleCelsiusChange і
                    handleFahrenheitChange — це функції, які оновлюють стан
                    state. Коли вони викликаються, вони зберігають нове значення
                    температури і її шкалу. <br />
                    celsius і fahrenheit обчислюються на основі поточного стану
                    temperature і scale. Це гарантує, що значення в обох полях
                    завжди будуть синхронізовані. <br />
                  </p>
                </>
              }
              text={
                <pre>
                  <code>{temperature}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredStateUp = reactStateUp.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredStateUp.length > 0 && (
        <Table id="react_stateUp">
          <TableBody>
            <TableOneCol text={<h3>Підйом стану.</h3>} />
            {filteredStateUp.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
