import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { funcComponent, classComponent } from "./ComponentsConstPre.ts";
import { IMethodsProps } from "@type/interface.ts";

export default function ComponentsRU({ searchTerm }: IMethodsProps) {
  const tsComponents = [
    {
      title: "Компоненты",
      jsx: (
        <TableOneCol
          text={
            <p>
              В TypeScript, когда вы создаете компоненты React, вы добавляете
              типы к их пропсам, состоянию и другим переменным. Это позволяет
              компилятору TypeScript проверять ваш код на ошибки, связанные с
              типами, еще до его выполнения. Лучший способ типизировать
              компонент — это создать интерфейс или тип для его пропсов. Это
              делает ваш код самодокументированным и предотвращает передачу
              неверных данных.
            </p>
          }
        />
      ),
    },
    {
      title: "Components",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример"}
              title={
                <>
                  <h3>Function component</h3>
                  <pre>
                    <code>{funcComponent}</code>
                  </pre>
                </>
              }
              text={
                <>
                  <h3> Class component</h3>
                  <pre>
                    <code>{classComponent}</code>
                  </pre>
                </>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredComponents = tsComponents.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredComponents.length > 0 && (
        <Table id="ts_components">
          <TableBody>
            <TableOneCol text={<h2>Components - Компоненты.</h2>} />
            {filteredComponents.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
