import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { IMethodsProps } from "@type/interface.ts";
import { formField } from "./UseIdConstPre";
import FormField from "./FormField";

export default function UseIdRU({ searchTerm }: IMethodsProps) {
  const useId = [
    {
      title: "useId",
      jsx: (
        <TableOneCol
          text={
            <>
              <p>
                useId — это хук React, который генерирует уникальный ID,
                стабильный как на сервере, так и на клиенте. Он предназначен для
                использования в случаях, когда компоненту нужен уникальный
                идентификатор для связи между элементами DOM, например, для
                атрибутов доступности.
              </p>
              <ul>
                useId идеально подходит для генерации ID, которые используются в
                таких атрибутах HTML:
                <li>aria-labelledby</li>
                <li>aria-describedby</li>
                <li>htmlFor (для &lt;label&gt;)</li>
              </ul>
            </>
          }
        />
      ),
    },
    {
      title: "useId",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример useId"}
              title={
                <>
                  <FormField />
                  <p>
                    const inputId = useId(); Эта строка создает уникальный и
                    стабильный идентификатор для этого экземпляра компонента.
                    Например, он может сгенерировать ID наподобие _r1:. <br />
                    htmlFor - атрибут htmlFor в &lt;label&gt; указывает, с каким
                    элементом формы связана эта метка. Мы передаем ему
                    сгенерированный ID. <br />
                    id - атрибут id в &lt;input&gt; получает тот же уникальный
                    ID.
                  </p>
                </>
              }
              text={
                <pre>
                  <code>{formField}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredUseId = useId.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredUseId.length > 0 && (
        <Table id="react_useId">
          <TableBody>
            <TableOneCol text={<h3>useId.</h3>} />
            {filteredUseId.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
