import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { IMethodsProps } from "@type/interface.ts";
import { firstProps, firstPropsUA, secondProps } from "./PropsConstPre.ts";
import FirstProps from "./FirstProps.jsx";

export default function PropsUA({ searchTerm }: IMethodsProps) {
  const reactProps = [
    {
      title: "Props",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Пропси (Props) — це скорочення від "властивості" (properties).
                Це спосіб передачі даних від батьківського компонента до
                дочірнього. Пропси передаються як атрибути HTML-тегу. <br />
                Пропси є незмінними (read-only). Дочірній компонент не може
                змінити отримані пропси. Це гарантує, що компоненти залишаються
                передбачуваними.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "Приклад Props",
      jsx: (
        <>
          <TableOneCol
            text={
              <pre>
                <code>{secondProps}</code>
              </pre>
            }
          />
        </>
      ),
    },
    {
      title: "Приклад Props",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                У цьому компоненті ви використовуєте хук useState для керування
                станом name, яке спочатку встановлено в порожню рядок.
                <br />
                У компоненті у вас є пропс names, який ви використовуєте для
                відображення привітання з переданим ім'ям.
                <br />
                Метод handleName викликається при натисканні на кнопку та
                відображає спливаюче вікно prompt , в якому користувач може
                ввести своє ім'я. Потім введене ім'я встановлюється стан name за
                допомогою функції setName.
                <br />У методі render компонента ви відображаєте два блоки з
                привітаннями. Перший блок використовує пропс names для
                відображення привітання з переданим ім'ям. Другий блок
                відображає привітання з ім'ям, отриманим з prompt , після
                натискання кнопки.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "Приклад Props",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Приклад Props"}
              title={
                <>
                  <pre>
                    <code>{firstPropsUA}</code>
                  </pre>

                  <FirstProps
                    enterName="Введіть ваше ім'я"
                    names="Олександр"
                    titleOne="Виведення імені шляхом передачі через props"
                    hello="Привіт"
                    titleTwo="Виведення імені отриманого з prompt"
                    btn="Натисни"
                  />
                </>
              }
              text={
                <pre>
                  <code>{firstProps}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredReactProps = reactProps.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredReactProps.length > 0 && (
        <Table id="react_props">
          <TableBody>
            <TableOneCol text={<h3>Props.</h3>} />
            {filteredReactProps.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
