import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import ButtonExampleWithBtn from "@core/ButtonExampleWithBtn.tsx";
import {
  asyncConst,
  AwaitConst,
  errorConst,
  promiseConst,
  asyncTwoConst,
} from "./AwaitConstPre.ts";
import { async, Await, error } from "./await.js";
import { IMethodsProps } from "@type/interface.ts";

export default function AwaitRU({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "Async",
      textForSearch:
        "Пишется перед функцией и обозначает то, что данная функция вернёт промис.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Async</h3>}
            text={
              <p>
                Пишется перед функцией и обозначает то, что данная функция
                вернёт промис.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример Async"}
                title={
                  <p id="formated-text">
                    <span id="jsasync"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{asyncConst}</code>
                  </pre>
                }
                onClick={async}
              />
            }
          />
        </>
      ),
    },
    {
      title: "Await",
      textForSearch:
        "Выполняется внутри async функции. Await ждёт пока выполнится промис и потом возвращает его результат.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Await</h3>}
            text={
              <p>
                Выполняется внутри async функции. Await ждёт пока выполнится
                промис и потом возвращает его результат.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример Await"}
                title={
                  <p id="formated-text">
                    <span id="jsawait"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{AwaitConst}</code>
                  </pre>
                }
                onClick={Await}
              />
            }
          />
        </>
      ),
    },
    {
      title: "Error",
      textForSearch:
        "Для того чтобы отловить ошибку в async/await используется try...catch.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Error</h3>}
            text={
              <p>
                Для того чтобы отловить ошибку в async/await используется
                try...catch.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример Error"}
                title={
                  <p id="formated-text">
                    <span id="jserror"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{errorConst}</code>
                  </pre>
                }
                onClick={error}
              />
            }
          />
        </>
      ),
    },
    {
      title: "Сравнение",
      textForSearch: "Сравнение Async/await с Promise.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример сравнение"}
              title={
                <p id="formated-text">
                  Promise
                  <pre>
                    <code>{promiseConst}</code>
                  </pre>
                </p>
              }
              text={
                <p id="formated-text">
                  Async/await
                  <pre>
                    <code>{asyncTwoConst}</code>
                  </pre>
                </p>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredData = tableData.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="js_await">
          <TableBody>
            <TableOneCol text={<h3>Async/await.</h3>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
