import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import ButtonExampleWithBtn from "@core/ButtonExampleWithBtn.tsx";
import {
  forPlusCode,
  forMinusCode,
  forEvenCode,
  forOddCode,
  forDoubleCode,
  forWhileCode,
  forDoWhileCode,
  forContinueCode,
  forBreakCode,
  forInCode,
  forOffCode,
} from "./CyclesConstPre.ts";
import {
  forPlus,
  forMinus,
  forEven,
  forOdd,
  forDouble,
  forWhile,
  forDoWhile,
  forContinue,
  forBreak,
  forIn,
  forOff,
} from "./cycles.js";
import { IMethodsProps } from "@type/interface.ts";

export default function CyclesRU({ searchTerm }: IMethodsProps) {
  const cyclesCycles = [
    {
      title: "for",
      textForSearch:
        "Цикл for состоит из трех частей: объявления цикла, условия, при котором будет выполняться цикл, и счетчика. Пример: for (let i = 0; i < 5; i++)",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>for</h3>}
            text={
              <p>
                Цикл for состоит из трех частей:
                <br />
                1. Объявления цикла - let i = 0 - создает и инициализирует
                счетчик.
                <br />
                2. Условие, при котором будет выполняться цикл: i &lt; 5. <br />
                3. Сам счетчик.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример for i++"}
                title={
                  <p id="formated-text">
                    <span id="jsForPlus"></span>
                  </p>
                }
                text={
                  <p id="formated-text">
                    i++ или i+= 1 <br />
                    <pre>
                      <code>{forPlusCode}</code>
                    </pre>
                  </p>
                }
                onClick={forPlus}
              />
            }
          />

          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример for i--"}
                title={
                  <p id="formated-text">
                    <span id="jsForMinus"></span>
                  </p>
                }
                text={
                  <p id="formated-text">
                    i-- или i-= 1 <br />
                    <pre>
                      <code>{forMinusCode}</code>
                    </pre>
                  </p>
                }
                onClick={forMinus}
              />
            }
          />

          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример for четные числа"}
                title={
                  <p id="formated-text">
                    <span id="jsForEven"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{forEvenCode}</code>
                  </pre>
                }
                onClick={forEven}
              />
            }
          />

          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример for нечетные числа"}
                title={
                  <p id="formated-text">
                    <span id="jsForOdd"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{forOddCode}</code>
                  </pre>
                }
                onClick={forOdd}
              />
            }
          />

          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример for вложенные циклы"}
                title={
                  <p id="formated-text">
                    <span id="jsForDouble"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{forDoubleCode}</code>
                  </pre>
                }
                onClick={forDouble}
              />
            }
          />
        </>
      ),
    },
    {
      title: "while",
      textForSearch:
        "Цикл while выполняется до тех пор, пока некоторое условие истинно.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>while</h3>}
            text={
              <p>
                Цикл while выполняется до тех пор, пока некоторое условие
                истинно.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример while"}
                title={
                  <p id="formated-text">
                    <span id="jsWhile"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{forWhileCode}</code>
                  </pre>
                }
                onClick={forWhile}
              />
            }
          />
        </>
      ),
    },
    {
      title: "do while",
      textForSearch:
        "В цикле do сначала выполняется код цикла, а потом происходит проверка условия в инструкции while. И пока это условие истинно, цикл повторяется.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>do while</h3>}
            text={
              <p>
                В цикле do сначала выполняется код цикла, а потом происходит
                проверка условия в инструкции while. И пока это условие истинно,
                цикл повторяется.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример do while"}
                title={
                  <p id="formated-text">
                    <span id="jsDoWhile"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{forDoWhileCode}</code>
                  </pre>
                }
                onClick={forDoWhile}
              />
            }
          />
        </>
      ),
    },
    {
      title: "Операторы continue",
      textForSearch:
        "Позволяет продолжить цикл до определенного момента, пропуская текущую итерацию.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Операторы continue</h3>}
            text={<p>Позволяет продолжить цикл до определённого момента.</p>}
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример continue"}
                title={
                  <p id="formated-text">
                    Когда значение переменной i станет равным 6, то в цикле
                    конструкция if(i===6) continue завершит текущую итерацию,
                    далее идущие инструкции цикла не будут выполняться, и
                    произойдет переход к следующей итерации.
                    <span id="jsContinue"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{forContinueCode}</code>
                  </pre>
                }
                onClick={forContinue}
              />
            }
          />
        </>
      ),
    },
    {
      title: "Операторы break",
      textForSearch: "Позволяет прервать цикл.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Операторы break</h3>}
            text={<p>Позволяет прервать цикл.</p>}
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример break"}
                title={
                  <p id="formated-text">
                    Данный цикл увеличивает переменную i c 1 до 10. Однако
                    поскольку в блоке цикла происходит поверка if(i===6) break;,
                    то, когда значение переменной i достигнет 6, то данное
                    условие прервет выполнение цикла с помощью оператора break.
                    <span id="jsBreak"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{forBreakCode}</code>
                  </pre>
                }
                onClick={forBreak}
              />
            }
          />
        </>
      ),
    },
    {
      title: "for in",
      textForSearch:
        "Предназначен главным образом для перебора объектов. Этот цикл перебирает все свойства объекта.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>for in</h3>}
            text={
              <p>
                Предназначен главным образом для перебора объектов. Этот цикл
                перебирает все свойства объекта.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример for in"}
                title={
                  <p id="formated-text">
                    <span id="jsIn"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{forInCode}</code>
                  </pre>
                }
                onClick={forIn}
              />
            }
          />
        </>
      ),
    },
    {
      title: "for of",
      textForSearch:
        "Предназначен для перебора наборов данных. Например массивов.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>for of</h3>}
            text={
              <p>
                Предназначен для перебора наборов данных. Например массивов.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Пример for of"}
                title={
                  <p id="formated-text">
                    <span id="jsOf"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{forOffCode}</code>
                  </pre>
                }
                onClick={forOff}
              />
            }
          />
        </>
      ),
    },
  ];

  const filteredCyclesCycles = cyclesCycles.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredCyclesCycles.length > 0 && (
        <Table id="js_cycles">
          <TableBody>
            <TableOneCol text={<h2>Циклы.</h2>} />
            <TableOneCol
              text={
                <p>
                  Циклы позволяют в зависимости от определенных условий
                  выполнять некоторое действие множество раз.
                </p>
              }
            />
            {filteredCyclesCycles.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
