import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoEqualCol from "@core/TableTwoEqualCol.tsx";
import {
  assertionOne,
  assertionTwo,
  assertionThree,
  assertionFour,
} from "./TypeAssertionConstPre.ts";
import { IMethodsProps } from "@type/interface.ts";

export default function TypeAssertionRU({ searchTerm }: IMethodsProps) {
  const tsTypeAssertion = [
    {
      title: "Type Assertion",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b>Type Assertion</b> - это механизм, который позволяет
              привязывать переменную к типу, который не может быть определен
              обычно. Это заключается в том, что вы можете указать тип данных,
              который вы ожидаете, чтобы использовался в переменной, и
              TypeScript обеспечивает, что эти данные соответствуют указанному
              типу.
            </p>
          }
        />
      ),
    },
    {
      title: "Type Assertion",
      jsx: (
        <TableTwoEqualCol
          title={
            <div style={{ display: "flex", flexDirection: "column" }}>
              <p>Утверждение с помощью &lt; &gt;</p>
              <pre>
                <code>{assertionOne}</code>
              </pre>
            </div>
          }
          text={
            <>
              <p>Утверждение с помощью оператора as</p>
              <pre>
                <code>{assertionTwo}</code>
              </pre>
            </>
          }
        />
      ),
    },
    {
      title: "Const Assertion",
      jsx: <TableOneCol text={<h3>Приведение к константе</h3>} />,
    },
    {
      title: "Const Assertion",
      jsx: (
        <TableOneCol
          text={
            <p>
              <b>Const Assertion</b> - это функциональность TypeScript, которая
              позволяет ограничить тип значений переменной, чтобы она имела лишь
              разрешенные значения. Это позволяет уменьшить количество ошибок в
              разработке, так как возникает предупреждение, если код использует
              значения, которые не подходят для данной переменной.
            </p>
          }
        />
      ),
    },
    {
      title: "Const Assertion",
      jsx: (
        <TableTwoEqualCol
          title={
            <div style={{ display: "flex", flexDirection: "column" }}>
              <p>
                Определение типа Person, который представляет объект с двумя
                свойствами: name типа string и age типа number. Определение
                переменной bill, которая также является объектом типа Person и
                не имеет константного типа. Это означает, что свойства объекта
                bill могут быть изменены после определения.
              </p>
              <pre>
                <code>{assertionThree}</code>
              </pre>
            </div>
          }
          text={
            <>
              <p>
                Определение типа Person, который представляет объект с двумя
                свойствами: name типа string и age типа number. Определение
                переменной john, которая является объектом типа Person и имеет
                константный тип. Это означает, что свойства объекта john не
                могут быть изменены после определения.
              </p>
              <pre>
                <code>{assertionFour}</code>
              </pre>
            </>
          }
        />
      ),
    },
  ];

  const filtered = tsTypeAssertion.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filtered.length > 0 && (
        <Table id="ts_typeAssertion">
          <TableBody>
            <TableOneCol text={<h2>Type Assertion - Затвердження типів.</h2>} />
            {filtered.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
