import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Arrow from "@core/Arrow";
import MenuReact from "./MenuReact.tsx";
import "./react.scss";
import InstallRU from "./InstallRU.tsx";
import AppBar from "@components/AppBar/AppBar.tsx";
import ReactTitleRU from "./ReactTitleRU.tsx";
import JsxRU from "./JsxRU.tsx";
import RenderingRU from "./RenderingRU.tsx";
import ComponentRU from "./ComponentRU.tsx";
import PropsRU from "./PropsRU.tsx";
import StateRU from "./StateRU.tsx";
import LifecycleRU from "./LifecycleRU.tsx";
import ConditionalRenderingRU from "./ConditionalRenderingRU.tsx";
import ListRU from "./ListRU.tsx";
import FormRU from "./Form/FormRU.tsx";
import StateUpRU from "./StateUpRU.tsx";
import HooksTitleRU from "./HooksTitleRU.tsx";
import UseEffectRU from "./UseEffect/UseEffectUA.tsx";
import UseStateRU from "./UseState/UseStateRU.tsx";
import UseContextRU from "./UseContext/UseContextRU.tsx";
import UseReducerRU from "./UseReducer/UseReducerRU.tsx";
import UseCallbackRU from "./UseCallback/UseCallbackRU.tsx";
import UseMemoRU from "./UseMemo/UseMemoRU.tsx";
import UseRefRU from "./UseRef/UseRefRU.tsx";
import RefForwardRU from "./RefForward/RefForwardRU.tsx";
import UseImperativeHandleRU from "./UseImperativeHandle/UseImperativeHandleRU.tsx";
import UseDebugValueRU from "./UseDebugValue/UseDebugValueRU.tsx";
import UseLayoutEffectRU from "./UseLayoutEffect/UseLayoutEffectRU.tsx";
import UseTransitionRU from "./UseTransition/UseTransitionRU.tsx";
import UseDeferredValueRU from "./UseDeferredValue/UseDeferredValueRU.tsx";
import UseIdRU from "./UseId/UseIdRU.tsx";
import ReactRouterRU from "./ReactRouter/ReactRouterRU.tsx";

export default function ReactRU() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term: React.SetStateAction<string>) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages"}
        toUA={"/react/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages active"}
        toRU={"/react/ru"}
        titleLangRU={"RU"}
        toHome={"/home/ru"}
        toHtml={"/html/ru"}
        toCss={"/css/ru"}
        toScss={"/scss/ru"}
        toJS={"/js/ru"}
        toDom={"/dom/ru"}
        toBom={"/bom/ru"}
        toHttp={"/http/ru"}
        toReact={"/react/ru"}
        toRedux={"/redux/ru"}
        toTS={"/ts/ru"}
        toNext={"/next/ru"}
        nameHome={"Главная страница"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
        page={"React"}
        onClick={handleMenuInfoOpen}
        buttonRef={buttonRef}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuReact
              sectionFirst={"React"}
              sectionSecond={"Знакомство с JSX"}
              sectionThird={"Рендеринг"}
              sectionFourth={"Компоненты"}
              sectionFifth={"Экспорт компонентов"}
              sectionSixth={"Импорт компонентов"}
              sectionSeventh={"Props"}
              sectionEighth={"Состояние (State)"}
              sectionNinth={"Жизненный цикл (Lifecycle)"}
              sectionTenth={"Условный рендеринг"}
              sectionEleventh={"Отображение списков"}
              sectionTwelfth={"Ключи (Keys)"}
              sectionThirteenth={"Формы"}
              sectionFourteenth={"Подъем состояния"}
              sectionFifteenth={"Hooks"}
              sectionSixteenth={"useState"}
              sectionSeventeenth={"useEffect"}
              sectionEighteenth={"useContext"}
              sectionNineteenth={"useReducer"}
              sectionTwentieth={"useCallback"}
              sectionTwentyFirst={"useMemo"}
              sectionTwentySecond={"useRef"}
              sectionTwentyThird={"forwardRef"}
              sectionTwentyFourth={"useImperativeHandle"}
              sectionTwentyFifth={"useLayoutEffect"}
              sectionTwentySixth={"useDebugValue"}
              sectionTwentySeventh={"useTransition"}
              sectionTwentyEighth={"useDeferredValue"}
              sectionTwentyNinth={"useId"}
              sectionThirtieth={"React Router"}
              sectionThirtyFirst={"Install"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}
        <TableContainer>
          <ReactTitleRU searchTerm={searchTerm} />
          <JsxRU searchTerm={searchTerm} />
          <RenderingRU searchTerm={searchTerm} />
          <ComponentRU searchTerm={searchTerm} />
          <PropsRU searchTerm={searchTerm} />
          <StateRU searchTerm={searchTerm} />
          <LifecycleRU searchTerm={searchTerm} />
          <ConditionalRenderingRU searchTerm={searchTerm} />
          <ListRU searchTerm={searchTerm} />
          <FormRU searchTerm={searchTerm} />
          <StateUpRU searchTerm={searchTerm} />
          <HooksTitleRU searchTerm={searchTerm} />
          <UseStateRU searchTerm={searchTerm} />
          <UseEffectRU searchTerm={searchTerm} />
          <UseContextRU searchTerm={searchTerm} />
          <UseReducerRU searchTerm={searchTerm} />
          <UseCallbackRU searchTerm={searchTerm} />
          <UseMemoRU searchTerm={searchTerm} />
          <UseRefRU searchTerm={searchTerm} />
          <RefForwardRU searchTerm={searchTerm} />
          <UseImperativeHandleRU searchTerm={searchTerm} />
          <UseLayoutEffectRU searchTerm={searchTerm} />
          <UseDebugValueRU searchTerm={searchTerm} />
          <UseTransitionRU searchTerm={searchTerm} />
          <UseDeferredValueRU searchTerm={searchTerm} />
          <UseIdRU searchTerm={searchTerm} />
          <ReactRouterRU searchTerm={searchTerm} />
          <InstallRU searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a target="_blank" href="https://ru.legacy.reactjs.org/">
            Документация React
          </a>
          <a target="_blank" href="https://ru.react.dev/">
            Документация React
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
