import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { IMethodsProps } from "@type/interface.ts";
import Callback from "./Callback";
import { useCallback } from "./UseCallbackConstPre";

export default function UseCallbackUA({ searchTerm }: IMethodsProps) {
  const reactUseCallback = [
    {
      title: "useCallback",
      jsx: (
        <TableOneCol
          text={
            <p>
              useCallback — це хук React, який дозволяє вам кешувати
              (мемоізувати) функції. Його основна мета — запобігти повторному
              створенню функції при кожному рендерингу компонента, що може
              оптимізувати продуктивність, особливо коли ця функція передається
              як пропс дочірнім компонентам.
            </p>
          }
        />
      ),
    },
    {
      title: "useCallback",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Приклад useCallback"}
              title={
                <div>
                  <Callback />
                  <p>
                    Цей код є компонентом React з використанням хука useState і
                    useCallback. У компоненті визначено такі стани:
                    <br />
                    1. colored: зберігає логічне значення визначення кольору
                    тексту.
                    <br />
                    2. count: зберігає числове значення для відображення
                    кількості елементів.
                    <br />
                    3. style: об'єкт стилів для тексту в залежності від значення
                    colored.
                    <br />
                    Функція generateItems створює масив елементів на основі
                    поточного значення count. Ця функція використовує хук
                    useCallback, щоб мемоізувати результат та уникнути зайвих
                    перемальовок компонента за зміни інших станів.
                    <br />
                    Значення компонента, що повертається, містить елементи JSX,
                    які відображають поточне значення count, кнопки для
                    збільшення та зменшення значення count, кнопку зміни кольору
                    тексту, а також компонент ItemList, якому передається
                    функція Створювалисяв якості пропсу.
                    <br />
                    Компонент ItemList використовується для відображення списку
                    елементів, що генеруються функцією generateItems.
                    <br />
                    Цей компонент демонструє використання хука useCallback для
                    оптимізації продуктивності компонента, щоб уникнути зайвих
                    обчислень за зміни залежностей.
                  </p>
                </div>
              }
              text={
                <pre>
                  <code>{useCallback}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredUseCallback = reactUseCallback.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredUseCallback.length > 0 && (
        <Table id="react_useCallback">
          <TableBody>
            <TableOneCol text={<h3>useCallback.</h3>} />
            {filteredUseCallback.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
