import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Arrow from "@core/Arrow";
import MenuHtml from "./MenuHtml.tsx";
import MetaTagRU from "./MetaTagRU.tsx";
import SectioningRU from "./SectioningRU.tsx";
import TextRU from "./TextRU.tsx";
import TextSemanticsRU from "./TextSemanticsRU.tsx";
import MultimediaRU from "./MultimediaRU.tsx";
import EmbeddedContentRU from "./EmbeddedContentRU.tsx";
import ScriptingRU from "./ScriptingRU.tsx";
import EditsRU from "./EditsRU.tsx";
import TableRU from "./TableRU.tsx";
import FormRU from "./FormRU.tsx";
import InteractiveRU from "./InteractiveRU.tsx";
import "./html.scss";
import AppBar from "@components/AppBar/AppBar.tsx";
import HtmlTitleRU from "./HtmlTitleRU.tsx";

export default function HtmlRU() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term: React.SetStateAction<string>) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages"}
        toUA={"/html/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages active"}
        toRU={"/html/ru"}
        titleLangRU={"RU"}
        toHome={"/home/ru"}
        toHtml={"/html/ru"}
        toCss={"/css/ru"}
        toScss={"/scss/ru"}
        toJS={"/js/ru"}
        toDom={"/dom/ru"}
        toBom={"/bom/ru"}
        toHttp={"/http/ru"}
        toReact={"/react/ru"}
        toRedux={"/redux/ru"}
        toTS={"/ts/ru"}
        toNext={"/next/ru"}
        nameHome={"Главная страница"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
        page={"HTML5"}
        onClick={handleMenuInfoOpen}
        buttonRef={buttonRef}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuHtml
              sectionFirst={"Метаданные документа"}
              sectionSecond={"Секционирование содержания"}
              sectionThird={"Текстовое содержание"}
              sectionFourth={"Встроенные текстовые семантики"}
              sectionFifth={"Изображения и мультимедиа"}
              sectionSixth={"Встроенное содержание"}
              sectionSeventh={"Скриптинг"}
              sectionEighth={"Разграничительные правки"}
              sectionNinth={"Содержание таблиц"}
              sectionTenth={"Формы"}
              sectionEleventh={"Интерактивные элементы"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}
        <TableContainer>
          <HtmlTitleRU searchTerm={searchTerm} />
          <MetaTagRU searchTerm={searchTerm} />
          <SectioningRU searchTerm={searchTerm} />
          <TextRU searchTerm={searchTerm} />
          <TextSemanticsRU searchTerm={searchTerm} />
          <MultimediaRU searchTerm={searchTerm} />
          <EmbeddedContentRU searchTerm={searchTerm} />
          <ScriptingRU searchTerm={searchTerm} />
          <EditsRU searchTerm={searchTerm} />
          <TableRU searchTerm={searchTerm} />
          <FormRU searchTerm={searchTerm} />
          <InteractiveRU searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a
            target="_blank"
            href="https://developer.mozilla.org/ru/docs/Web/HTML"
          >
            Документация HTML5
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
