  proxyGet,
  proxySet,
  proxyHas,
  proxydelete,
  proxyApply,
  proxyConstruct,
  proxyDefineProperty,
  proxyGetOwn,
  proxyPrototypeOf,
  proxyIsExtensible,
  proxyOwnKeys,
