import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import ButtonExampleWithBtn from "@core/ButtonExampleWithBtn.tsx";
import { changeStyle, getComputedStyle } from "./DomConstPre.tsx";
import { changeStyleFn, getStyle } from "./DomFunc.js";
import { IMethodsProps } from "@type/interface.ts";

export default function ChangePropertiesRU({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: ".innerHTML",
      category: "DOM",
      textForSearch: "Изменение внутреннего HTML содержимого.",
      jsx: (
        <TableTwoCol
          title={<h3>.innerHTML</h3>}
          text={
            <p>
              Изменяет внутренний HTML элемент.
              <br />
              <code>element.innerHTML = "новое содержимое html"</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".outerHTML",
      category: "DOM",
      textForSearch: "Изменение элемента целиком вместе с содержимым.",
      jsx: (
        <TableTwoCol
          title={<h3>.outerHTML</h3>}
          text={
            <p>
              Отличие от innerHTML состоит в том что кроме содержимого мы
              получаем объект целиком.
              <br />
              <code>element.outerHTML = "новое содержимое html"</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".insertAdjacentHTML",
      category: "DOM",
      textForSearch: "Вставка произвольного HTML в любое место.",
      jsx: (
        <TableTwoCol
          title={<h3>.insertAdjacentHTML</h3>}
          text={
            <p>
              Позволяет вставлять произвольный HTML в любое место документа, в
              том числе и между узлами!
              <br />
              <b>html</b> - Строка HTML, которую нужно вставить. <br />
              <b>where</b> - Куда по отношению к <b>elem</b> вставлять строку.
              Всего четыре варианта: <br />
              <code>beforeBegin</code> - перед <b>elem</b>. <br />
              <code>afterBegin</code> – внутрь <b>elem</b>, в самое начало.{" "}
              <br />
              <code>beforeEnd</code> – внутрь <b>elem</b>, в конец. <br />
              <code>afterEnd</code> – после <b>elem</b>. <br />
              <code>element.insertAdjacentHTML(where, html);</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".insertAdjacentElement",
      category: "DOM",
      textForSearch: "Добавление элемента в DOM-дерево.",
      jsx: (
        <TableTwoCol
          title={<h3>.insertAdjacentElement</h3>}
          text={
            <p>
              Метод добавляет переданный элемент в DOM-дерево относительно
              элемента, вызвавшего метод.
              <br />
              <b>element</b> - Элемент, добавляемый в DOM-дерево. <br />
              <b>where</b> - Куда по отношению к <b>elem</b> вставлять строку.
              Всего четыре варианта:
              <br />
              <code>beforeBegin</code> - перед <b>elem</b>. <br />
              <code>afterBegin</code> – внутрь <b>elem</b>, в самое начало.{" "}
              <br />
              <code>beforeEnd</code> – внутрь <b>elem</b>, в конец. <br />
              <code>afterEnd</code> – после <b>elem</b>. <br />
              <code>element.insertAdjacentElement(where, element);</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".insertAdjacentText",
      category: "DOM",
      textForSearch: "Добавление текстового узла.",
      jsx: (
        <TableTwoCol
          title={<h3>.insertAdjacentText</h3>}
          text={
            <p>
              Метод помещает заданный текстовый узел в указанную позицию
              относительно элемента, который передан в вызове метода.
              <br />
              <b>element</b> - Текст, который будет помещён в заданную позицию.
              <br />
              <b>where</b> - Куда по отношению к <b>elem</b> вставлять строку.
              Всего четыре варианта: <br />
              <code>beforeBegin</code> - перед <b>elem</b>. <br />
              <code>afterBegin</code> – внутрь <b>elem</b>, в самое начало.{" "}
              <br />
              <code>beforeEnd</code> – внутрь <b>elem</b>, в конец. <br />
              <code>afterEnd</code> – после <b>elem</b>. <br />
              <code>element.insertAdjacentText(where, element);</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".textContent",
      category: "DOM",
      textForSearch: "Получение/изменение текстового содержимого.",
      jsx: (
        <TableTwoCol
          title={<h3>.textContent</h3>}
          text={
            <p>
              Позволяет получить непосредственно содержимое. При этом внесеные
              изменения передаются в виде строки полностью. <br />
              <code>element.textContent = "новое содержимое html"</code>
            </p>
          }
        />
      ),
    },
    {
      title: "Пример изменения стилей",
      category: "DOM",
      textForSearch: "Пример изменения стилей элемента в JavaScript.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExampleWithBtn
              titleButtonExample={"Пример style"}
              title={
                <p id="formated-text">
                  <span id="style-text">Начальный текст.</span>
                </p>
              }
              text={
                <pre>
                  <code>{changeStyle}</code>
                </pre>
              }
              onClick={changeStyleFn}
            />
          }
        />
      ),
    },
    {
      title: "getComputedStyle",
      category: "DOM",
      textForSearch: "Получение всех стилей элемента.",
      jsx: (
        <TableTwoCol
          title={<h3>getComputedStyle</h3>}
          text={
            <p>
              Позволяет получить все стили элемента. <br />
              <code>getComputedStyle(element)</code>
            </p>
          }
        />
      ),
    },
    {
      title: "Пример getComputedStyle",
      category: "DOM",
      textForSearch: "Пример получения вычисленных стилей элемента.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExampleWithBtn
              titleButtonExample={"Пример getComputedStyle"}
              title={
                <p id="formated-text">
                  <div
                    className="getStyle"
                    style={{ fontSize: "20px", color: "blue" }}
                  >
                    Text
                  </div>
                  <div className="getStyle1"></div>
                </p>
              }
              text={
                <pre>
                  <code>{getComputedStyle}</code>
                </pre>
              }
              onClick={getStyle}
            />
          }
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredData.length > 0 && (
        <Table id="dom_changeProperties">
          <TableBody>
            <TableOneCol text={<h3>Изменение свойств элементов HTML.</h3>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
