import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { IMethodsProps } from "@type/interface.ts";
import CounterReset from "./CounterReset";
import { imperativeHandl } from "./UseImperativeHandleConstPre";

export default function UseImperativeHandleRU({ searchTerm }: IMethodsProps) {
  const useImperativeHandle = [
    {
      title: "useImperativeHandle",
      jsx: (
        <>
          <TableOneCol
            text={
              <div>
                <p>
                  useImperativeHandle — это React-хук, который позволяет
                  родительскому компоненту получить доступ к некоторым методам
                  или значениям дочернего компонента, не предоставляя полный
                  доступ к его внутренней структуре. Этот хук используется
                  вместе с forwardRef и позволяет родительскому компоненту
                  вызывать методы или манипулировать состоянием дочернего
                  компонента императивно, а не через пропсы. Использование
                  useImperativeHandle является редким и, как правило, его
                  следует избегать, если есть другие, более декларативные
                  способы достичь желаемого результата.
                </p>
                <ul>
                  useImperativeHandle принимает три аргумента:
                  <li>
                    ref. Ссылка, которая получается от родительского компонента
                    через forwardRef.
                  </li>
                  <li>
                    createHandle. Функция, которая возвращает объект с методами,
                    которые вы хотите открыть для родительского компонента.
                  </li>
                  <li>
                    dependencies. Массив зависимостей, аналогичный useEffect и
                    useCallback. Хук будет повторно вызывать createHandle только
                    при изменении зависимостей.
                  </li>
                </ul>
              </div>
            }
          />
        </>
      ),
    },
    {
      title: "useImperativeHandle",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример useImperativeHandle"}
              title={
                <div>
                  <CounterReset />
                  <p>
                    Counter. Это дочерний компонент, который имеет свое
                    собственное состояние (count). <br />
                    useImperativeHandle. Этот хук предоставляет родительскому
                    компоненту доступ к объекту с методом resetCount. <br />
                    CounterReset. Родительский компонент создает ссылку
                    (counterRef) и передает ее в CounterReset. <br />
                    Императивное управление: Когда вы нажимаете кнопку "Сбросить
                    счетчик", родительский компонент вызывает
                    counterRef.current.resetCount(), что заставляет дочерний
                    компонент сбросить свое внутреннее состояние до нуля.
                  </p>
                </div>
              }
              text={
                <pre>
                  <code>{imperativeHandl}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredUseImperativeHandle = useImperativeHandle.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredUseImperativeHandle.length > 0 && (
        <Table id="react_useImperativeHandle">
          <TableBody>
            <TableOneCol text={<h3>useImperativeHandle.</h3>} />
            {filteredUseImperativeHandle.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
