import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import { IMethodsProps } from "@type/interface.ts";
import { postCode2 } from "./HttpConstPre.tsx";

export default function HttpFetchRU({ searchTerm }: IMethodsProps) {
  const tableFetch = [
    {
      title: "Fetch",
      textForSearch:
        "Fetch - это современный метод для выполнения HTTP-запросов. Он возвращает промис. Поддерживается современными браузерами, для старых нужны полифилы. let promise = fetch(url, [options])",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Этот метод является самым современным. Он не поддерживается
                старыми браузерами, но поддерживается всеми современными. Для
                поддержки старых браузеров можно использовать полифилы.
                <br /> `let promise = fetch(url, [options])`
                <br /> **url** – URL для отправки запроса.
                <br /> **options** – дополнительные параметры: метод, заголовки
                и т.д.
              </p>
            }
          />
        </>
      ),
    },
  ];

  const tableResponse = [
    {
      title: "Response",
      textForSearch:
        "Параметры получения ответов от сервера. response.status, response.ok, response.headers, response.text(), response.json(), response.formData(), response.blob(), response.arrayBuffer(), response.body().",
      jsx: (
        <>
          <TableOneCol
            text={<p>Это параметры получения ответов от сервера.</p>}
          />
        </>
      ),
    },
    {
      title: "response.status",
      textForSearch: "Выводит HTTP-код ответа.",
      jsx: (
        <TableTwoCol
          title={<h3>response.status</h3>}
          text={<p>Выводит HTTP-код ответа.</p>}
        />
      ),
    },
    {
      title: "response.ok",
      textForSearch:
        "Булевое значение, которое выводит true, если статус ответа в диапазоне 200-299.",
      jsx: (
        <TableTwoCol
          title={<h3>response.ok</h3>}
          text={
            <p>
              Булевое значение, которое выводит `true`, если статус ответа в
              диапазоне 200-299.
            </p>
          }
        />
      ),
    },
    {
      title: "response.headers",
      textForSearch: "Очень похож на объект Map с HTTP-заголовками.",
      jsx: (
        <TableTwoCol
          title={<h3>response.headers</h3>}
          text={<p>Очень похож на `Map` объект с HTTP-заголовками.</p>}
        />
      ),
    },
    {
      title: "response.text()",
      textForSearch: "Возвращает ответ как обычный текст.",
      jsx: (
        <TableTwoCol
          title={<h3>response.text()</h3>}
          text={<p>Возвращает ответ как обычный текст.</p>}
        />
      ),
    },
    {
      title: "response.json()",
      textForSearch: "Преобразует ответ в JSON-объект.",
      jsx: (
        <TableTwoCol
          title={<h3>response.json()</h3>}
          text={<p>Преобразует ответ в JSON-объект.</p>}
        />
      ),
    },
    {
      title: "response.formData()",
      textForSearch: "Возвращает ответ как объект FormData.",
      jsx: (
        <TableTwoCol
          title={<h3>response.formData()</h3>}
          text={<p>Возвращает ответ как объект `FormData`.</p>}
        />
      ),
    },
    {
      title: "response.blob()",
      textForSearch: "Возвращает объект как Blob.",
      jsx: (
        <TableTwoCol
          title={<h3>response.blob()</h3>}
          text={<p>Возвращает объект как `Blob`.</p>}
        />
      ),
    },
    {
      title: "response.arrayBuffer()",
      textForSearch: "Возвращает ответ как ArrayBuffer.",
      jsx: (
        <TableTwoCol
          title={<h3>response.arrayBuffer()</h3>}
          text={<p>Возвращает ответ как `ArrayBuffer`.</p>}
        />
      ),
    },
    {
      title: "response.body()",
      textForSearch:
        "Это объект ReadableStream, с помощью которого можно считывать тело запроса частями.",
      jsx: (
        <TableTwoCol
          title={<h3>response.body()</h3>}
          text={
            <p>
              Это объект `ReadableStream`, с помощью которого можно считывать
              тело запроса частями.
            </p>
          }
        />
      ),
    },
  ];

  const tablePostFeach = [
    {
      title: "POST-запросы",
      textForSearch:
        "Параметры для POST-запросов с помощью fetch: method, headers, body. Свойства тела запроса: JSON, FormData, Blob/BufferSource, URLSearchParams.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>method</h3>}
            text={<p>HTTP метод, в данном случае **POST**.</p>}
          />
          <TableTwoCol
            title={<h3>headers</h3>}
            text={<p>Для установки заголовка запроса.</p>}
          />
          <TableTwoCol
            title={<h3>body</h3>}
            text={
              <p>
                Тело запроса, одно из списка: <br /> **JSON**. <br /> Объект
                **FormData**. <br /> **Blob/BufferSource** для отправки бинарных
                данных. <br /> **URLSearchParams** для отправки данных в
                кодировке `x-www-form-urlencoded`, используется редко.
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                <pre>
                  <code>{postCode2}</code>
                </pre>
              </p>
            }
          />
        </>
      ),
    },
  ];

  const tableFormData = [
    {
      title: "FormData",
      textForSearch:
        "Используется для отправки различных форм. let formData = new FormData([form]);",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Используется для отправки различных форм, при этом его указывают
                в свойстве тела запроса. <br /> `let formData = new
                FormData([form]);`
              </p>
            }
          />
          <TableOneCol text={<h3>Методы FormData</h3>} />
        </>
      ),
    },
    {
      title: "formData.append(name, value)",
      textForSearch:
        "Добавляет (создает) новое значение к существующему ключу. name - Имя поля, value - Значение поля.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.append (name, value)</h3>}
          text={
            <p>
              `append()` добавляет (создает) новое значение к существующему
              ключу внутри объекта **FormData**. <br /> **name** - Имя поля.
              <br /> **value** - Значение поля.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.append(name, blob, fileName)",
      textForSearch:
        "Добавляет Blob или File с указанным именем файла. name - Имя поля. Blob, File, USVString, filename.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.append (name, blob, fileName)</h3>}
          text={
            <p>
              **name** - Имя поля. <br /> На выбор одно из четырех значений:
              <br /> **value** – значение поля. <br /> **Blob** - Неизменяемые
              необработанные двоичные данные.
              <br /> **File** - Объекты, которые возвращаются в результате
              выбора пользователем файлов.
              <br /> **USVString** - Набор последовательностей скалярных
              значений Unicode. <br /> **filename** - Имя файла, которое будет
              отправлено на сервер.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.set(name, value)",
      textForSearch:
        "Действует как append, но позволяет заменить поле name на новое.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.set (name, value)</h3>}
          text={
            <p>
              Действует как и метод `append`, только позволяет удалить поле
              `name` и написать новое поле.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.set(name, blob, fileName)",
      textForSearch:
        "Действует как append, но позволяет заменить поле name на новое (для Blob/File).",
      jsx: (
        <TableTwoCol
          title={<h3>formData.set (name, blob, fileName)</h3>}
          text={
            <p>
              Действует как и метод `append`, только позволяет удалить поле
              `name` и написать новое поле.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.delete(name)",
      textForSearch: "Удаляет поле с заданным именем name.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.delete(name)</h3>}
          text={<p>Удаляет поле с заданным именем `name`.</p>}
        />
      ),
    },
    {
      title: "formData.get(name)",
      textForSearch: "Получает значение поля с именем name.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.get(name)</h3>}
          text={<p>Получает значение поля с именем `name`.</p>}
        />
      ),
    },
    {
      title: "formData.getAll(name)",
      textForSearch: "Получает все значения полей с именем name.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.getAll(name)</h3>}
          text={<p>Получает все значения полей с именем `name`.</p>}
        />
      ),
    },
    {
      title: "formData.has(name)",
      textForSearch:
        "Проверяет наличие поля с именем name. Возвращает true или false.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.has(name)</h3>}
          text={
            <p>
              Если есть поле с именем `name`, то возвращает `true`, иначе
              `false`.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.entries()",
      textForSearch:
        "Возвращает итератор, позволяя пройтись по всем ключам/значениям. Ключ - USVString, значение - USVString или Blob.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.entries()</h3>}
          text={
            <p>
              Возвращает итератор, позволяя пройтись по всем ключам/значениям в
              этом объекте. Ключ каждой пары – это объект **USVString**,
              значение – это **USVString** или **Blob**.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.keys()",
      textForSearch:
        "Возвращает итератор, позволяя пройтись по всем ключам. Ключи являются USVString.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.keys()</h3>}
          text={
            <p>
              Возвращает итератор, позволяя пройтись по всем ключам, которые
              содержатся в этом объекте. Ключи являются **USVString** объектами.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.values()",
      textForSearch:
        "Возвращает итератор, позволяя пройтись по всем значениям. Значения - USVString или Blob.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.values()</h3>}
          text={
            <p>
              Возвращает итератор, позволяя пройтись по всем значениям в этом
              объекте. Значения - это **USVString** или **Blob** объекты.
            </p>
          }
        />
      ),
    },
  ];

  const filteredFetch = tableFetch.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredResponse = tableResponse.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredPostFeach = tablePostFeach.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredFormData = tableFormData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredFetch.length > 0 && (
        <Table id="http_fetch">
          <TableBody>
            <TableOneCol text={<h2>Fetch.</h2>} />
            {filteredFetch.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredResponse.length > 0 && (
        <Table id="http_response">
          <TableBody>
            <TableOneCol text={<h3>Response.</h3>} />
            {filteredResponse.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredPostFeach.length > 0 && (
        <Table id="http_postFeach">
          <TableBody>
            <TableOneCol text={<h3>POST-запросы</h3>} />
            {filteredPostFeach.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredFormData.length > 0 && (
        <Table id="http_formData">
          <TableBody>
            <TableOneCol text={<h2>FormData</h2>} />
            {filteredFormData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
