import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import { IMethodsProps } from "@type/interface.ts";
import { firstProps, firstPropsRU, secondPropsRU } from "./PropsConstPre.ts";
import FirstProps from "./FirstProps.jsx";
import ButtonExample from "@core/ButtonExample.tsx";

export default function PropsRU({ searchTerm }: IMethodsProps) {
  const reactProps = [
    {
      title: "Props",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Пропсы (Props) — это сокращение от "свойства" (properties). Это
                способ передачи данных от родительского компонента к дочернему.
                Пропсы передаются как атрибуты HTML-тега. <br />
                Пропсы являются неизменными (read-only). Дочерний компонент не
                может изменить полученные пропсы. Это гарантирует, что
                компоненты остаются предсказуемыми.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "Пример Props",
      jsx: (
        <>
          <TableOneCol
            text={
              <pre>
                <code>{secondPropsRU}</code>
              </pre>
            }
          />
        </>
      ),
    },
    {
      title: "Пример Props",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                В этом компоненте вы используете хук useState для управления
                состоянием name, которое изначально установлено в пустую строку.
                <br />
                В компоненте у вас есть пропс names, который вы используете для
                отображения приветствия с переданным именем.
                <br />
                Метод handleName вызывается при нажатии на кнопку и отображает
                всплывающее окно prompt, в котором пользователь может ввести
                свое имя. Затем введенное имя устанавливается в состояние name с
                помощью функции setName.
                <br />В методе render компонента вы отображаете два блока с
                приветствиями. Первый блок использует пропс names для
                отображения приветствия с переданным именем. Второй блок
                отображает приветствие с именем, полученным из prompt, после
                нажатия кнопки.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "Пример Props",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример Props"}
              title={
                <>
                  <pre>
                    <code>{firstPropsRU}</code>
                  </pre>

                  <FirstProps
                    enterName="Введите ваше имя"
                    names="Александр"
                    titleOne="Вывод имени путем передачи через props"
                    hello="Привет"
                    titleTwo="Вывод имени, полученного из prompt"
                    btn="Нажми"
                  />
                </>
              }
              text={
                <pre>
                  <code>{firstProps}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredReactProps = reactProps.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredReactProps.length > 0 && (
        <Table id="react_props">
          <TableBody>
            <TableOneCol text={<h3>Props.</h3>} />
            {filteredReactProps.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
