import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function EditsRU({ searchTerm }: IMethodsProps) {
  const editsData = [
    {
      title: "Разграничительные правки",
      category: "HTML",
      textForSearch: "Разграничительные правки, <del>, <ins>.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Эти элементы позволяют вам отметить определённые части текста.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "<del>",
      category: "HTML",
      textForSearch: "<del>, удаленный текст, del.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;del&gt; &lt;/del&gt;</h3>}
          text={
            <p>
              Представляет диапазон текста, который был удалён из документа.
            </p>
          }
        />
      ),
    },
    {
      title: "<ins>",
      category: "HTML",
      textForSearch: "<ins>, добавленный текст, ins.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;ins&gt; &lt;/ins&gt;</h3>}
          text={
            <p>
              Представляет собой диапазон текста, который был добавлен в
              документ.
            </p>
          }
        />
      ),
    },
  ];

  const filteredEditsData = editsData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredEditsData.length > 0 && (
        <Table id="html_edits">
          <TableBody>
            <TableOneCol text={<h2>Разграничительные правки.</h2>} />
            {filteredEditsData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
