import React from "react";
import "@components/Menu/menu.scss";
import { IMenuInfoProps } from "@type/interface";

function MenuHtml({
  sectionFirst,
  sectionSecond,
  sectionThird,
  sectionFourth,
  sectionFifth,
  sectionSixth,
  sectionSeventh,
  sectionEighth,
  sectionNinth,
  sectionTenth,
  sectionEleventh,
  onClose,
}: IMenuInfoProps) {
  return (
    <div className="menu-container">
      <a className="dropdown-item" href="#html_metaTag" onClick={onClose}>
        {sectionFirst}
      </a>
      <a className="dropdown-item" href="#html_sectioning" onClick={onClose}>
        {sectionSecond}
      </a>
      <a className="dropdown-item" href="#html_text" onClick={onClose}>
        {sectionThird}
      </a>
      <a className="dropdown-item" href="#html_textSemantics" onClick={onClose}>
        {sectionFourth}
      </a>
      <a className="dropdown-item" href="#html_multimedia" onClick={onClose}>
        {sectionFifth}
      </a>
      <a
        className="dropdown-item"
        href="#html_embeddedContent"
        onClick={onClose}
      >
        {sectionSixth}
      </a>
      <a className="dropdown-item" href="#html_scripting" onClick={onClose}>
        {sectionSeventh}
      </a>
      <a className="dropdown-item" href="#html_edits" onClick={onClose}>
        {sectionEighth}
      </a>
      <a className="dropdown-item" href="#html_table" onClick={onClose}>
        {sectionNinth}
      </a>
      <a className="dropdown-item" href="#html_form" onClick={onClose}>
        {sectionTenth}
      </a>
      <a className="dropdown-item" href="#html_interactive" onClick={onClose}>
        {sectionEleventh}
      </a>
    </div>
  );
}

export default MenuHtml;
