export const stateEdit: string = `
import React, { useState } from "react";

function StateEdit() {
  const initialState = {
    title: "Old data",
    data: new Date().toLocaleDateString(),
  };

  const [state, setState] = useState(initialState);

  function resetTitle() {
    setState(initialState);
  }

  function updateTitle() {
    setState((update) => {
      return {
        ...update,
        title: "New data",
      };
    });
  }

  return (
    <>
      <button
        onClick={resetTitle}
        style={{ backgroundColor: "#d0ccd1", color: "black" }}
      >
        Old
      </button>
      <button
        onClick={updateTitle}
        style={{ backgroundColor: "#0260daff", color: "black" }}
      >
        New
      </button>
      <pre>{JSON.stringify(state, null, 2)}</pre>
    </>
  );
}

export default StateEdit;
`;

export const counter: string = `
import React, { useState } from "react";

function Counter() {
  const [count, setCount] = useState(0);

  return (
    <>
      <div className="functionCounter">
        <h1>Score: {count}</h1>
        <div>
          <button
            style={{ backgroundColor: "#83D350" }}
            onClick={() => setCount((prevCount) => prevCount + 1)}
          >
            Add
          </button>
          <button
            style={{ backgroundColor: "#0025f6ff" }}
            onClick={() => setCount((prevCount) => prevCount - 1)}
          >
            Remove
          </button>
          <button
            style={{ backgroundColor: "#F60030" }}
            onClick={() => setCount(0)}
          >
            Reset
          </button>
        </div>
      </div>
    </>
  );
}

export default Counter;
`;

export const stateAddArray: string = `
import React, { useState } from "react";

export default function StateTwo() {
  const [numbers, setNumbers] = useState([1, 2, 3]);

  const addNumbers = () => {
    const newNumbers = Number(prompt("Enter new number"));
    setNumbers([...numbers, newNumbers]);    
  };

  return (
    <>
      <ul>
        {numbers.map((numb, index) => (
          <li key={index}>{numb}</li>
        ))}
      </ul>
      <button onClick={addNumbers} >
        Add
      </button>
    </>
  );
}
`;
