export const genericOne = `  function getArray<T>(items: T[]): T[] {
    return new Array<T>().concat(items);
  }
  
  let myNumArr = getArray<number>([100, 200, 300]);
  let myStrArr = getArray<string>(["Hello", "World"]);
  
  myNumArr.push(400); // OK
  myStrArr.push("Hello TypeScript"); // OK
  
  console.log(myNumArr); // [100, 200, 300, 400]
  console.log(myStrArr); // ["Hello", "World", "Hello TypeScript"]
`;

export const genericTwo = `  interface Person<T, U> {
    name: T;
    age: U;
    address: string;
  }
  
  const person: Person<string, number> = {
    name: "John",
    age: 30,
    address: "123 Main St",
  };
  
  console.log(person.name);
  console.log(person.age);
  console.log(person.address); 
`;

export const genericThree = `interface IUser<
T extends string,
U extends number,
V extends string,
W extends { street: string; city: string }
> {
    name: T;
    age: U;
    email: V;
    address: W;
}
                  
const user: IUser<string, number, string, { street: string; city: string }> = {
    name: "John",
    age: 30,
    email: "john@gmail.com",
    address: {
        street: "123 Collins St",
        city: "New York",
    },
};
`;

export const genericFour = `function reverse<T>(items: T[]): T[] {
    return items.reverse();
}
  
const numbers = [1, 2, 3, 4, 5];
const reversedNumbers = reverse(numbers);
console.log(reversedNumbers); // [5, 4, 3, 2, 1]
  
const strings = ['apple', 'banana', 'cherry'];
const reversedStrings = reverse(strings);
console.log(reversedStrings); // ['cherry', 'banana', 'apple']
`;

export const genericFive = `function mergeObjects<T extends object, R extends object>(a: T, b: R) {
    return Object.assign({}, a, b);
}
  
const merged = mergeObjects<{ model: string }, { year: number }>(
    { model: "Ford" },
    { year: 2010 }
);

console.log(merged);
console.log(merged.model);
console.log(merged.year);
`;
