import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function MetaTagRU({ searchTerm }: IMethodsProps) {
  const metaTagData = [
    {
      title: "Метаданные документа",
      category: "HTML",
      textForSearch:
        "Метаданные документа, <base>, <head>, <link>, <meta>, <style>, <title>.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Метаданные содержат информацию о странице. Они включают в себя
                информацию о стилях, скрипты и данные, чтобы помочь программному
                обеспечению (поисковые системы, браузеры и т.д.) использовать и
                отображать страницу. Метаданные для стилей и скрипты могут быть
                определены на странице или ссылке на другой файл, который имеет
                информацию.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "<base>",
      category: "HTML",
      textForSearch: "<base>, основной адрес (URL) для относительных адресов.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;base&gt; &lt;/base&gt;</h3>}
          text={
            <p>
              Определяет основной адрес (URL), используемый для всех
              относительных адресов (URLs) в документе. Может быть только один
              &lt;base&gt; элемент в одном документе.
            </p>
          }
        />
      ),
    },
    {
      title: "<head>",
      category: "HTML",
      textForSearch: "<head>, метаданные документа, заголовок, скрипты, стили.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;head&gt; &lt;/head&gt;</h3>}
          text={
            <p>
              Содержит машиночитаемую информацию (metadata) о документе,
              например его заголовок, скрипты и страницы стилей.
            </p>
          }
        />
      ),
    },
    {
      title: "<link>",
      category: "HTML",
      textForSearch: "<link>, связь с внешним ресурсом, CSS, favicon.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;link /&gt;</h3>}
          text={
            <p>
              Определяет отношения между текущим документом и внешним ресурсом.
              Этот элемент чаще всего используется для ссылки на CSS, а также
              для создания иконок сайта (как для иконок в стиле "favicon", так и
              для иконок домашних экранов и приложений мобильных устройств)
              среди прочего.
            </p>
          }
        />
      ),
    },
    {
      title: "<meta>",
      category: "HTML",
      textForSearch: "<meta>, метатеги, дополнительные метаданные.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;meta /&gt;</h3>}
          text={
            <p>
              Представляет такие Metadata, которые не могут быть представлены
              другими HTML-метатегами, такими как &lt;base&gt;, &lt;link&gt;,
              &lt;script&gt;, &lt;style&gt; или &lt;title&gt;
            </p>
          }
        />
      ),
    },
    {
      title: "<style>",
      category: "HTML",
      textForSearch: "<style>, стили для документа, CSS.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;style&gt; &lt;/style&gt;</h3>}
          text={
            <p>
              Содержит стилевую информацию для документа или его части. По
              умолчанию стилевые инструкции внутри этого элемента считаются
              написанными на CSS.
            </p>
          }
        />
      ),
    },
    {
      title: "<title>",
      category: "HTML",
      textForSearch: "<title>, заголовок документа, вкладка браузера.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;title&gt; &lt;/title&gt;</h3>}
          text={
            <p>
              Определяет заголовок документа, который отображается в заголовке
              окна Browser или на вкладке страницы. Он содержит только текст, а
              теги внутри элемента игнорируются.
            </p>
          }
        />
      ),
    },
  ];

  const filteredMetaTagData = metaTagData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredMetaTagData.length > 0 && (
        <Table id="html_metaTag">
          <TableBody>
            <TableOneCol text={<h2>Метаданные документа</h2>} />
            {filteredMetaTagData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
