export const formField: string = `
import React, { useId } from 'react';

function FormField() {
  const inputId = useId();

  return (
    <div>
      <label htmlFor={inputId}>
        Enter your name:
      </label>
      <input id={inputId} type="text" />
    </div>
  );
}

export default FormField;
`;
