import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { IMethodsProps } from "@type/interface.ts";
import CounterReset from "./CounterReset";
import { imperativeHandl } from "./UseImperativeHandleConstPre";

export default function UseImperativeHandleUA({ searchTerm }: IMethodsProps) {
  const useImperativeHandle = [
    {
      title: "useImperativeHandl",
      jsx: (
        <>
          <TableOneCol
            text={
              <div>
                <p>
                  useImperativeHandle — це React-хук, що дозволяє батьківському
                  компоненту отримати доступ до деяких методів або значень
                  дочірнього компонента, не надаючи повний доступ до його
                  внутрішньої структури. Цей хук використовується разом з
                  forwardRef і дозволяє батьківському компоненту викликати
                  методи або маніпулювати станом дочірнього компонента
                  імперативно, а не через пропси. Використання
                  useImperativeHandle є рідкісним і, як правило, його слід
                  уникати, якщо є інші, більш декларативні способи досягти
                  бажаного результату.
                </p>
                <ul>
                  useImperativeHandle приймає три аргументи:
                  <li>
                    ref. Посилання, яке отримується від батьківського компонента
                    через forwardRef.
                  </li>
                  <li>
                    createHandle. Функція, яка повертає об'єкт з методами, які
                    ви хочете відкрити для батьківського компонента.
                  </li>
                  <li>
                    dependencies. Масив залежностей, аналогічний useEffect та
                    useCallback. Хук буде повторно викликати createHandle лише
                    при зміні залежностей.
                  </li>
                </ul>
              </div>
            }
          />
        </>
      ),
    },
    {
      title: "useImperativeHandl",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Приклад useImperativeHandl"}
              title={
                <div>
                  <CounterReset />
                  <p>
                    Counter. Це дочірній компонент, який має свій власний стан
                    (count). <br />
                    useImperativeHandle. Цей хук надає батьківському компоненту
                    доступ до об'єкта з методом resetCount. <br />
                    CounterReset. Батьківський компонент створює посилання
                    (counterRef) і передає його до CounterReset. <br />
                    Імперативне керування: Коли ви натискаєте кнопку "Скинути
                    лічильник", батьківський компонент викликає
                    counterRef.current.resetCount(), що змушує дочірній
                    компонент скинути свій внутрішній стан до нуля.
                  </p>
                </div>
              }
              text={
                <pre>
                  <code>{imperativeHandl}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredUseImperativeHandle = useImperativeHandle.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredUseImperativeHandle.length > 0 && (
        <Table id="react_useImperativeHandle">
          <TableBody>
            <TableOneCol text={<h3>useImperativeHandle.</h3>} />
            {filteredUseImperativeHandle.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
