import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import ButtonExampleWithBtn from "@core/ButtonExampleWithBtn.tsx";
import { newSetConst } from "./SetConstPre.ts";
import { newSet } from "./set.js";
import { IMethodsProps } from "@type/interface.ts";

export default function SetUA({ searchTerm }: IMethodsProps) {
  const tableSet = [
    {
      title: "Set",
      textForSearch:
        "Це особливий вид колекції: «безліч» значень (без ключів), де кожне значення може з'являтися лише один раз.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Це особливий вид колекції: «безліч» значень (без ключів), де
                кожне значення може з'являтися лише один раз.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "new Set()",
      textForSearch: "Ініціалізація об'єкта.",
      jsx: (
        <TableTwoCol
          title={<h3>const set = new Set();</h3>}
          text={<p>Ініціалізація об'єкта.</p>}
        />
      ),
    },
    {
      title: "set.add(value)",
      textForSearch:
        "Додає значення (якщо воно вже є, то нічого не робить), повертає той самий об'єкт set.",
      jsx: (
        <TableTwoCol
          title={<h3>set.add(value)</h3>}
          text={
            <p>
              Додає значення (якщо воно вже є, то нічого не робить), повертає
              той самий об'єкт set.
            </p>
          }
        />
      ),
    },
    {
      title: "set.delete(value)",
      textForSearch:
        "Видаляє значення, повертає true, якщо value було в множині на момент виклику, інакше false.",
      jsx: (
        <TableTwoCol
          title={<h3>set.delete(value)</h3>}
          text={
            <p>
              Видаляє значення, повертає true, якщо value було в множині на
              момент виклику, інакше false.
            </p>
          }
        />
      ),
    },
    {
      title: "set.has(value)",
      textForSearch: "Повертає true, якщо значення є у множині, інакше false.",
      jsx: (
        <TableTwoCol
          title={<h3>set.has(value)</h3>}
          text={<p>Повертає true, якщо значення є у множині, інакше false.</p>}
        />
      ),
    },
    {
      title: "set.clear()",
      textForSearch: "Видаляє всі наявні значення.",
      jsx: (
        <TableTwoCol
          title={<h3>set.clear()</h3>}
          text={<p>Видаляє всі наявні значення.</p>}
        />
      ),
    },
    {
      title: "set.size()",
      textForSearch: "Повертає кількість елементів у безлічі.",
      jsx: (
        <TableTwoCol
          title={<h3>set.size()</h3>}
          text={<p>Повертає кількість елементів у безлічі.</p>}
        />
      ),
    },
    {
      title: "set.values()",
      textForSearch: "Повертає об'єкт, що перебирається для значень.",
      jsx: (
        <TableTwoCol
          title={<h3>set.values()</h3>}
          text={<p>Повертає об'єкт, що перебирається для значень.</p>}
        />
      ),
    },
    {
      title: "set.keys()",
      textForSearch: "Як і set.values(), є для зворотної сумісності з Map.",
      jsx: (
        <TableTwoCol
          title={<h3>set.keys()</h3>}
          text={<p>Як і set.values(), є для зворотної сумісності з Map.</p>}
        />
      ),
    },
    {
      title: "set.entries()",
      textForSearch:
        "Повертає об'єкт, що перебирається, для пар виду [значення, значення], є для зворотної сумісності з Map.",
      jsx: (
        <TableTwoCol
          title={<h3>set.entries()</h3>}
          text={
            <p>
              Повертає об'єкт, що перебирається, для пар виду [значення,
              значення], є для зворотної сумісності з Map.
            </p>
          }
        />
      ),
    },
    {
      title: "Приклад Set",
      textForSearch:
        "Завдання перебрати масив та вивести новий масив з унікальними фруктів.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExampleWithBtn
              titleButtonExample={"Приклад Set"}
              title={
                <p id="formated-text">
                  <span>
                    Завдання перебрати масив та вивести новий масив з
                    унікальними фруктів.
                  </span>
                  <br />
                  <br />
                  <span id="jsSet"></span>
                </p>
              }
              text={
                <pre>
                  <code>{newSetConst}</code>
                </pre>
              }
              onClick={newSet}
            />
          }
        />
      ),
    },
  ];

  const filteredSet = tableSet.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredSet.length > 0 && (
        <Table id="js_set">
          <TableBody>
            <TableOneCol text={<h2>Set.</h2>} />
            {filteredSet.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
