import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function InteractiveUA({ searchTerm }: IMethodsProps) {
  const interactiveData = [
    {
      title: "Інтерактивні елементи",
      category: "HTML",
      textForSearch: "Інтерактивні елементи, <details>, <dialog>, <summary>.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                HTML містить у собі елементи, які допомагають створювати
                інтерактивні об'єкти інтерфейсу користувача.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "<details>",
      category: "HTML",
      textForSearch: "<details>, прихована інформація, розкриття інформації.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;details&gt; &lt;/details&gt;</h3>}
          text={
            <p>
              Використовується для розкриття прихованої (додаткової) інформації.
            </p>
          }
        />
      ),
    },
    {
      title: "<dialog>",
      category: "HTML",
      textForSearch: "<dialog>, діалогове вікно, інтерактивний елемент.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;dialog&gt; &lt;/dialog&gt;</h3>}
          text={
            <p>
              Визначає діалогове вікно або інший інтерактивний елемент,
              наприклад, інспектор або вікно. Елементи &lt;form&gt; можуть
              інтегруватися з діалогом за допомогою вказівки атрибуту{" "}
              <b>method = "dialog"</b>. Коли відправляється така форма, діалог
              закривається з returnValue рівним value натиснутої кнопки submit.
            </p>
          }
        />
      ),
    },
    {
      title: "<summary>",
      category: "HTML",
      textForSearch: "<summary>, зведення, заголовок, легенда, details.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;summary&gt; &lt;/summary&gt;</h3>}
          text={
            <p>
              Визначає зведення, заголовок або легенду для &lt;details&gt; поля
              розкриття елемента. Клацання по &lt;summary&gt; елементу перемикає
              стан батьківського &lt;details&gt; елемента відкритим та закритим.
            </p>
          }
        />
      ),
    },
  ];

  const filteredInteractiveData = interactiveData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredInteractiveData.length > 0 && (
        <Table id="html_interactive">
          <TableBody>
            <TableOneCol text={<h2>Інтерактивні елементи.</h2>} />
            {filteredInteractiveData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
