import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { listener, target } from "./DomConstPre.tsx";
import { listenerFn, listenerFn2 } from "./DomFunc.js";
import { IMethodsProps } from "@type/interface.ts";

export default function ListenerUA({ searchTerm }: IMethodsProps) {
  const tableListener = [
    {
      title: ".addEventListener()",
      category: "DOM",
      textForSearch: "Додавання обробника події, прослуховування подій.",
      jsx: (
        <TableTwoCol
          title={<h3>.addEventListener()</h3>}
          text={
            <p>
              Це функція, яка першим параметром приймає назву події (
              <b>event</b>), а другим параметром функцію, яка виконається, коли
              ця подія відбудеться.
              <br />
              <code>element.addEventListener(event, handler)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".removeEventListener()",
      category: "DOM",
      textForSearch: "Видалення обробника події.",
      jsx: (
        <TableTwoCol
          title={<h3>.removeEventListener()</h3>}
          text={
            <p>
              Використовується для видалення обробника події.
              <br />
              <code>element.removeEventListener(event, handler)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".dispatchEvent()",
      category: "DOM",
      textForSearch: "Генерація події програмно.",
      jsx: (
        <TableTwoCol
          title={<h3>.dispatchEvent()</h3>}
          text={
            <p>
              Генерує подію на об'єкті.
              <br />
              <code>element.dispatchEvent(event)</code>
            </p>
          }
        />
      ),
    },
    {
      title: "Приклад listener",
      category: "DOM",
      textForSearch: "Приклад addEventListener, подія mouseenter.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Приклад listener"}
              title={
                <p id="formated-text">
                  <span>
                    При наведенні на перший елемент з'являється другий.
                  </span>
                  <div onMouseEnter={listenerFn} className="firstElement">
                    <p>First element</p>
                  </div>
                  <div style={{ display: "none" }} className="secondElement">
                    <p>Second element</p>
                  </div>
                </p>
              }
              text={
                <pre>
                  <code>{listener}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const tableDelegation = [
    {
      title: "event.target",
      category: "DOM",
      textForSearch: "Ініціатор події, посилання на елемент.",
      jsx: (
        <TableTwoCol
          title={<h3>event.target</h3>}
          text={<p>Це посилання на об'єкт, який був ініціатором події.</p>}
        />
      ),
    },
    {
      title: "event.stopPropagation()",
      category: "DOM",
      textForSearch: "Зупинка спливання подій.",
      jsx: (
        <TableTwoCol
          title={<h3>event.stopPropagation()</h3>}
          text={<p>Для зупинки спливання потрібно викликати цей метод.</p>}
        />
      ),
    },
    {
      title: "Приклад спливання",
      category: "DOM",
      textForSearch: "Приклад спливання подій.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Приклад спливання"}
              title={
                <section
                  className="first_form"
                  onClick={() => alert("section")}
                >
                  section
                  <form onClick={() => alert("form")}>
                    form
                    <div onClick={() => alert("div")}>div</div>
                  </form>
                </section>
              }
              text={
                <p id="formated-text">
                  Якщо в прикладі вище натиснути на <b>div</b>, то послідовно
                  виведуться alert: div → form → section. Цей процес називається
                  <b>спливанням</b>, тому що події «спливають» від внутрішнього
                  елемента вгору через батьків, подібно до того, як спливає
                  бульбашка повітря у воді.
                </p>
              }
            />
          }
        />
      ),
    },
    {
      title: "Приклад event.target",
      category: "DOM",
      textForSearch: "Приклад event.target, this.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Приклад event.target"}
              title={
                <p id="formated-text">
                  <b>event.target</b> - це вихідний елемент, на якому відбулася
                  подія, у процесі спливання він незмінний. <br />
                  <b>this</b> - це поточний елемент, до якого дійшло спливання,
                  на ньому зараз виконується обробник.
                  <section onMouseEnter={listenerFn2} className="second_form">
                    section
                    <form>
                      form
                      <div>div</div>
                    </form>
                  </section>
                </p>
              }
              text={
                <pre>
                  <code>{target}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredListener = tableListener.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredDelegation = tableDelegation.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredListener.length > 0 && (
        <Table id="dom_listener">
          <TableBody>
            <TableOneCol text={<h3>Обробник.</h3>} />
            {filteredListener.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredDelegation.length > 0 && (
        <Table id="dom_delegation">
          <TableBody>
            <TableOneCol text={<h3>Делегування подій.</h3>} />
            {filteredDelegation.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
