import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { IMethodsProps } from "@type/interface.ts";
import Callback from "./Callback";
import { useCallback } from "./UseCallbackConstPre";

export default function UseCallbackRU({ searchTerm }: IMethodsProps) {
  const reactUseCallback = [
    {
      title: "useCallback",
      jsx: (
        <TableOneCol
          text={
            <p>
              useCallback — это хук React, который позволяет вам кешировать
              (мемоизировать) функции. Его основная цель — предотвратить
              повторное создание функции при каждом рендеринге компонента, что
              может оптимизировать производительность, особенно когда эта
              функция передается как пропс дочерним компонентам.
            </p>
          }
        />
      ),
    },
    {
      title: "useCallback",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример useCallback"}
              title={
                <div>
                  <Callback />
                  <p>
                    Этот код является компонентом React с использованием хуков
                    useState и useCallback. В компоненте определены следующие
                    состояния:
                    <br />
                    1. colored: хранит логическое значение определения цвета
                    текста.
                    <br />
                    2. count: хранит числовое значение для отображения
                    количества элементов.
                    <br />
                    3. style: объект стилей для текста в зависимости от значения
                    colored.
                    <br />
                    Функция generateItems создает массив элементов на основе
                    текущего значения count. Эта функция использует хук
                    useCallback, чтобы мемоизировать результат и избежать лишних
                    перерисовок компонента при изменении других состояний.
                    <br />
                    Значение компонента, который возвращается, содержит элементы
                    JSX, которые отображают текущее значение count, кнопки для
                    увеличения и уменьшения значения count, кнопку изменения
                    цвета текста, а также компонент ItemList, которому
                    передается функция generateItems в качестве пропса.
                    <br />
                    Компонент ItemList используется для отображения списка
                    элементов, которые генерируются функцией generateItems.
                    <br />
                    Этот компонент демонстрирует использование хука useCallback
                    для оптимизации производительности компонента, чтобы
                    избежать лишних вычислений при изменении зависимостей.
                  </p>
                </div>
              }
              text={
                <pre>
                  <code>{useCallback}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredUseCallback = reactUseCallback.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredUseCallback.length > 0 && (
        <Table id="react_useCallback">
          <TableBody>
            <TableOneCol text={<h3>useCallback.</h3>} />
            {filteredUseCallback.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
