import React, { useState } from "react";
import Button from "@mui/material/IconButton";
import "./buttonExample.scss";
import { IButtonExampleProps } from "@type/interface";

export default function ButtonExample({
  titleButtonExample,
  title,
  text,
}: IButtonExampleProps) {
  const [isExampleOpen, setIsExampleOpen] = useState(false);

  const handleMenuInfoOpen = () => {
    setIsExampleOpen(!isExampleOpen);
  };

  const tableRowStyle = {
    width: "100%",
    display: "flex",
  };
  return (
    <div id="menu-example">
      <Button className="menu-example-btn" onClick={handleMenuInfoOpen}>
        {titleButtonExample}
      </Button>
      {isExampleOpen && (
        <div style={tableRowStyle} className="table-example">
          <div id={"td"} style={{ border: "none" }} className="colOne">
            {title}
          </div>
          <div id={"td"} style={{ border: "none" }} className="colTwo">
            {text}
          </div>
        </div>
      )}
    </div>
  );
}

