import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import ButtonExampleWithBtn from "@core/ButtonExampleWithBtn.tsx";
import {
  objectProtoConst,
  objectCreateConst,
  objectSetConst,
  objectGetConst,
} from "./ProtoConstPre.ts";
import { objectProto, objectCreate, objectSet, objectGet } from "./proto.js";
import { IMethodsProps } from "@type/interface.ts";

export default function ProtoUA({ searchTerm }: IMethodsProps) {
  const tableProto = [
    {
      title: "Прототип об'єкта",
      textForSearch:
        "Об'єкти JavaScript можна організувати в ланцюжка так, щоб властивість, не знайдена в одному об'єкті, автоматично шукалося б в іншому.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Об'єкти JavaScript можна організувати в ланцюжка так, щоб
                властивість, не знайдена в одному об'єкті, автоматично шукалося
                б в іншому.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "__proto__",
      textForSearch:
        "Якщо об'єкт має посилання __proto__, що веде на інший об'єкт, то коли буде викликана якась властивість у даного об'єкта і воно не буде знайдено, тоді пошук перейде по ланцюжку до пов'язаного об'єкту через __proto__. На даний момент __proto__ вважається застарілим, і за стандартом воно має підтримуватись тільки браузерами.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>__proto__</h3>}
            text={
              <p>
                Якщо об'єкт має посилання __proto__, що веде на інший об'єкт, то
                коли буде викликана якась властивість у даного об'єкта і воно не
                буде знайдено, тоді пошук перейде по ланцюжку до пов'язаного
                об'єкту через __proto__. <br />
                На даний момент __proto__ вважається застарілим, і за стандартом
                воно має підтримуватись тільки браузерами.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "Приклад proto",
      textForSearch:
        "Розглянемо приклад: є два об'єкти people і masha. Коли ми будемо викликати masha.eats - ми його не знайдемо і перейдемо по ланцюжок в людях.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExampleWithBtn
              titleButtonExample={"Приклад proto"}
              title={
                <p id="formated-text">
                  <span>
                    Розглянемо приклад: є два об'єкти people і masha. Коли ми
                    будемо викликати masha.eats - ми його не знайдемо і
                    перейдемо по ланцюжок в людях.
                  </span>
                  <br />
                  <br />
                  <span id="jsProto"></span>
                </p>
              }
              text={
                <pre>
                  <code>{objectProtoConst}</code>
                </pre>
              }
              onClick={objectProto}
            />
          }
        />
      ),
    },
    {
      title: "Object.create (proto, descriptors)",
      textForSearch:
        "Створює новий об'єкт із зазначеним прототипом та властивостями.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Object.create (proto, descriptors)</h3>}
            text={
              <p>
                Створює новий об'єкт із зазначеним прототипом та властивостями.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Приклад create"}
                title={
                  <p id="formated-text">
                    <span>
                      Розглянемо приклад: створюємо новий об'єкт masha із
                      прототипом людей.
                    </span>
                    <br />
                    <br />
                    <span id="jsObjectCreate"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{objectCreateConst}</code>
                  </pre>
                }
                onClick={objectCreate}
              />
            }
          />
        </>
      ),
    },
    {
      title: "Object.setPrototypeOf (object, proto)",
      textForSearch:
        "Здатний встановити прототип зазначеного об'єкта в інший об'єкт.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Object.setPrototypeOf (object, proto)</h3>}
            text={
              <p>
                Здатний встановити прототип зазначеного об'єкта в інший об'єкт.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Приклад setPrototypeOf"}
                title={
                  <p id="formated-text">
                    <span>
                      Розглянемо приклад: передаємо в об'єкт masha властивість
                      sport та прототип людей.
                    </span>
                    <br />
                    <br />
                    <span id="jsObjectSet"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{objectSetConst}</code>
                  </pre>
                }
                onClick={objectSet}
              />
            }
          />
        </>
      ),
    },
    {
      title: "Object.getPrototypeOf (object)",
      textForSearch:
        "Здатний повернути прототип властивостей зазначеного об'єкта.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>Object.getPrototypeOf (object)</h3>}
            text={
              <p>
                Здатний повернути прототип властивостей зазначеного об'єкта.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExampleWithBtn
                titleButtonExample={"Приклад getPrototypeOf"}
                title={
                  <p id="formated-text">
                    <span>
                      Розглянемо приклад: передаємо в об'єкт masha властивість
                      sport та прототип людей.
                    </span>
                    <br />
                    <br />
                    <span id="jsObjectGet"></span>
                  </p>
                }
                text={
                  <pre>
                    <code>{objectGetConst}</code>
                  </pre>
                }
                onClick={objectGet}
              />
            }
          />
        </>
      ),
    },
  ];

  const filteredProto = tableProto.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredProto.length > 0 && (
        <Table id="js_proto">
          <TableBody>
            {" "}
            <TableOneCol text={<h2>Прототип об'єкта.</h2>} />
            {filteredProto.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
