import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Arrow from "@core/Arrow";
import MenuCss from "./MenuScss.tsx";
import "./scss.scss";
import ImportRU from "./ImportRU.tsx";
import MediaRU from "./MediaRU.tsx";
import ExtendRU from "./ExtendRU.tsx";
import AtRootRU from "./AtRootRU.tsx";
import OtherDirectiveRU from "./OtherDirectiveRU.tsx";
import ExpressionsRU from "./ExpressionsRU.tsx";
import MixinRU from "./MixinRU.tsx";
import ArgumentRU from "./ArgumentRU.tsx";
import ContentRU from "./ContentRU.tsx";
import AppBar from "@components/AppBar/AppBar.tsx";
import ScssTitleRU from "./ScssTitleRU.tsx";

export default function ScssRU() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term: React.SetStateAction<string>) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages"}
        toUA={"/scss/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages active"}
        toRU={"/scss/ru"}
        titleLangRU={"RU"}
        toHome={"/home/ru"}
        toHtml={"/html/ru"}
        toCss={"/css/ru"}
        toScss={"/scss/ru"}
        toJS={"/js/ru"}
        toDom={"/dom/ru"}
        toBom={"/bom/ru"}
        toHttp={"/http/ru"}
        toReact={"/react/ru"}
        toRedux={"/redux/ru"}
        toTS={"/ts/ru"}
        toNext={"/next/ru"}
        nameHome={"Главная страница"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
        page={"SCSS"}
        onClick={handleMenuInfoOpen}
        buttonRef={buttonRef}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuCss
              sectionFirst={"@import"}
              sectionSecond={"@media"}
              sectionThird={"@extend"}
              sectionFourth={"@at-root"}
              sectionFifth={"@debug"}
              sectionSixth={"@warn"}
              sectionSeventh={"@error"}
              sectionEighth={"@if"}
              sectionNinth={"@for"}
              sectionTenth={"@each"}
              sectionEleventh={"@while"}
              sectionTwelfth={"mixin"}
              sectionThirteenth={"Аргументы"}
              sectionFourteenth={"Блоки контента в миксинах"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}
        <TableContainer>
          <ScssTitleRU searchTerm={searchTerm} />
          <ImportRU searchTerm={searchTerm} />
          <MediaRU searchTerm={searchTerm} />
          <ExtendRU searchTerm={searchTerm} />
          <AtRootRU searchTerm={searchTerm} />
          <OtherDirectiveRU searchTerm={searchTerm} />
          <ExpressionsRU searchTerm={searchTerm} />
          <MixinRU searchTerm={searchTerm} />
          <ArgumentRU searchTerm={searchTerm} />
          <ContentRU searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a target="_blank" href="https://sass-lang.com/documentation/">
            Документація SASS/SCSS
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
