export const useEffectBtn: string = `
import React, { useState, useEffect } from "react";
import "./react.scss";

function UseEffectBtn() {
  const [type, setType] = useState("");
  const [data, setData] = useState([]);

  useEffect(() => {
    fetch(\`https://jsonplaceholder.typicode.com/\${type}\`)
      .then((response) => response.json())
      .then((json) => setData(json));
  }, [type]);

  return (
    <>
      <h1 style={{ textAlign: "left" }}>Resource: {type}</h1>
      <button
        onClick={() => setType("users")}
        style={{ backgroundColor: "#83D350" }}
      >
        Users
      </button>
      <button onClick={() => setType("todos")}>
        Todos
      </button>      
      <button
        onClick={() => setData([]) & setType("")}
        style={{ backgroundColor: "#F60030" }}
      >
        Reset
      </button>
      <pre>{JSON.stringify(data, null, 2)}</pre>
    </>
  );
}

export default UseEffectBtn;
`;

export const useEffectUser: string = `
import React, { useState, useEffect } from "react";

export default function UseEffectUser() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    async function fetchUsers() {
      try {
        const response = await fetch(
          "https://jsonplaceholder.typicode.com/users"
        );
        if (!response.ok) {
          throw new Error("Помилка мережі");
        }
        const data = await response.json();
        setUsers(data);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    }

    fetchUsers();
  }, []);

  if (loading) {
    return <div>Завантаження даних...</div>;
  }

  if (error) {
    return <div>Виникла помилка: {error}</div>;
  }

  return (
    <ol>
      {users.map((user) => (
        <li key={user.id}>{user.name}</li>
      ))}
    </ol>
  );
}
`;

export const users: string = `onClick={() => setType("users")}`;

export const todos: string = `onClick={() => setType("todos")}`;

export const reset: string = `onClick={() => setData([]) & setType("")}`;
