import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function MetaTagUA({ searchTerm }: IMethodsProps) {
  const metaTagData = [
    {
      title: "Метадані документа",
      category: "HTML",
      textForSearch:
        "Метадані документа, <base>, <head>, <link>, <meta>, <style>, <title>.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Метадані містять інформацію про сторінку. Вони включають в себе
                інформацію про стилі, скрипти і дані, щоб допомогти програмному
                забезпеченню (пошукові системи, браузери і т.д.) використовувати
                і відображати сторінку. Метадані для стилів і скрипти можуть
                бути визначені на сторінці або посилання на інший файл, який має
                інформацію.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "<base>",
      category: "HTML",
      textForSearch: "<base>, основна адреса (URL) для відносних адрес.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;base&gt; &lt;/base&gt;</h3>}
          text={
            <p>
              Визначає основну адресу (URL), яка використовується для всіх
              відносних адрес (URLs) у документі. Можливо тільки один
              &lt;base&gt; елемент у одному документі.
            </p>
          }
        />
      ),
    },
    {
      title: "<head>",
      category: "HTML",
      textForSearch: "<head>, метадані документа, заголовок, скрипти, стилі.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;head&gt; &lt;/head&gt;</h3>}
          text={
            <p>
              Містить машиночитану інформацію (metadata) про документ, наприклад
              його заголовок, скрипти і сторінки стилів.
            </p>
          }
        />
      ),
    },
    {
      title: "<link>",
      category: "HTML",
      textForSearch: "<link>, зв'язок з зовнішнім ресурсом, CSS, favicon.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;link /&gt;</h3>}
          text={
            <p>
              Визначає відносини між поточним документом та зовнішнім ресурсом.
              Цей елемент найчастіше використовується для посилання на CSS, а
              також для створення іконок сайту (як для іконок у стилі "favicon",
              так і для іконок домашніх екранів та додатків мобільних пристроїв)
              серед іншого.
            </p>
          }
        />
      ),
    },
    {
      title: "<meta>",
      category: "HTML",
      textForSearch: "<meta>, метатеги, додаткові метадані.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;meta /&gt;</h3>}
          text={
            <p>
              Представляє такі Metadata, які не можуть бути представлені іншими
              HTML-метатегами, такими як &lt;base&gt;, &lt;link&gt;,
              &lt;script&gt;, &lt;style&gt; або &lt;title&gt;
            </p>
          }
        />
      ),
    },
    {
      title: "<style>",
      category: "HTML",
      textForSearch: "<style>, стилі для документа, CSS.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;style&gt; &lt;/style&gt;</h3>}
          text={
            <p>
              Містить стильову інформацію для документа або його частини. За
              замовчуванням стильні інструкції всередині елемента елемента
              написані на CSS.
            </p>
          }
        />
      ),
    },
    {
      title: "<title>",
      category: "HTML",
      textForSearch: "<title>, заголовок документа, вкладка браузера.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;title&gt; &lt;/title&gt;</h3>}
          text={
            <p>
              Визначає заголовок документа, який відображається у заголовку
              вікна Browser або на вкладці сторінки. Він містить лише текст, а
              теги всередині елемента ігноруються.
            </p>
          }
        />
      ),
    },
  ];

  const filteredMetaTagData = metaTagData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredMetaTagData.length > 0 && (
        <Table id="html_metaTag">
          <TableBody>
            <TableOneCol text={<h2>Метадані документа</h2>} />
            {filteredMetaTagData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
