import React from "react";
import { Helmet } from "react-helmet";
import Card from "@core/Card.tsx";
import AppBarHome from "@components/AppBar/AppBarHome";

const html = require("@images/logo/html.png");
const css = require("@images/logo/css.png");
const scss = require("@images/logo/scss.png");
const js = require("@images/logo/js.png");
const http = require("@images/logo/http.png");
const react = require("@images/logo/react.png");
const redux = require("@images/logo/redux.png");
const ts = require("@images/logo/ts.png");
const next = require("@images/logo/next.png");
const dom = require("@images/logo/dom.png");
const bom = require("@images/logo/bom.png");

export default function HomePageUA() {
  return (
    <>
      <Helmet>
        <title>Вивчення Front-End</title>
        <meta
          name="description"
          content="Покроковий посібник для початківців з вивчення Front-End: HTML, CSS, JavaScript, React, Redux, TypeScript, Next.js та багато іншого."
        />
        <meta
          property="og:title"
          content="Вивчення Front-End | Покроковий план навчання"
        />
        <meta
          property="og:description"
          content="Покроковий посібник для початківців з вивчення Front-End: HTML, CSS, JavaScript, React, Redux, TypeScript, Next.js та багато іншого."
        />
        <meta name="viewport" content="width=device-width, initial-scale=1.0" />
      </Helmet>
      <AppBarHome
        classLangUA={"buttonLanguages active"}
        toUA={"/"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages "}
        toRU={"/home/ru"}
        titleLangRU={"RU"}
        toHome={"/"}
      />
      <div id="homePage">
        <h1>Вивчення Front-End</h1>
        <section className="homeBTN">
          <Card src={html} alt={"html"} href={"/html/ua"} titlePage={"HTML5"} />
          <Card src={css} alt={"css"} href={"/css/ua"} titlePage={"CSS"} />
          <Card src={scss} alt={"scss"} href={"/scss/ua"} titlePage={"SCSS"} />
          <Card src={js} alt={"js"} href={"/js/ua"} titlePage={"JavaScript"} />
          <Card src={dom} alt={"dom"} href={"/dom/ua"} titlePage={"DOM"} />
          <Card src={bom} alt={"bom"} href={"/bom/ua"} titlePage={"BOM"} />
          <Card src={http} alt={"http"} href={"/http/ua"} titlePage={"HTTP"} />
          <Card
            src={react}
            alt={"react"}
            href={"/react/ua"}
            titlePage={"React"}
          />
          <Card
            src={redux}
            alt={"redux"}
            href={"/redux/ua"}
            titlePage={"Redux"}
          />
          <Card src={ts} alt={"ts"} href={"/ts/ua"} titlePage={"TypeScript"} />
          <Card
            src={next}
            alt={"next"}
            href={"/next/ua"}
            titlePage={"NextJS"}
          />
        </section>
      </div>
    </>
  );
}
