import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { IMethodsProps } from "@type/interface.ts";
import {
  getRequest,
  getResponse,
  headRequest,
  headResponse,
  postRequest,
  postResponse,
  putRequest,
  putResponse,
  deleteRequest,
  deleteResponse,
} from "./HttpConstPre.tsx";

export default function MethodsRU({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "GET",
      textForSearch:
        "Запрашивает представление ресурса. Такие запросы могут только извлекать данные.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>GET</h3>}
            text={
              <p>
                Запрашивает представление ресурса. Такие запросы могут только
                извлекать данные.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExample
                titleButtonExample={"Пример GET"}
                title={
                  <pre>
                    <code>{getRequest}</code>
                  </pre>
                }
                text={
                  <pre>
                    <code>{getResponse}</code>
                  </pre>
                }
              />
            }
          />
        </>
      ),
    },
    {
      title: "HEAD",
      textForSearch:
        "Запрашивает ресурс, как и GET, но ответ приходит без тела.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>HEAD</h3>}
            text={
              <p>Запрашивает ресурс, как и GET, но ответ приходит без тела.</p>
            }
          />
          <TableOneCol
            text={
              <ButtonExample
                titleButtonExample={"Пример HEAD"}
                title={
                  <pre>
                    <code>{headRequest}</code>
                  </pre>
                }
                text={
                  <pre>
                    <code>{headResponse}</code>
                  </pre>
                }
              />
            }
          />
        </>
      ),
    },
    {
      title: "POST",
      textForSearch:
        "Отправляет сущности к указанному ресурсу. Может вызывать побочные эффекты на сервере и изменение состояния.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>POST</h3>}
            text={
              <p>
                Отправляет сущности к указанному ресурсу. Может вызывать
                побочные эффекты на сервере и изменение состояния.
              </p>
            }
          />
          <TableOneCol
            text={
              <ButtonExample
                titleButtonExample={"Пример POST"}
                title={
                  <pre>
                    <code>{postRequest}</code>
                  </pre>
                }
                text={
                  <pre>
                    <code>{postResponse}</code>
                  </pre>
                }
              />
            }
          />
        </>
      ),
    },
    {
      title: "PUT",
      textForSearch: "Заменяет текущие представления ресурса данными запроса.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>PUT</h3>}
            text={
              <p>Заменяет текущие представления ресурса данными запроса.</p>
            }
          />
          <TableOneCol
            text={
              <ButtonExample
                titleButtonExample={"Пример PUT"}
                title={
                  <pre>
                    <code>{putRequest}</code>
                  </pre>
                }
                text={
                  <pre>
                    <code>{putResponse}</code>
                  </pre>
                }
              />
            }
          />
        </>
      ),
    },
    {
      title: "DELETE",
      textForSearch: "Удаляет указанный ресурс.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>DELETE</h3>}
            text={<p>Удаляет указанный ресурс.</p>}
          />
          <TableOneCol
            text={
              <ButtonExample
                titleButtonExample={"Пример DELETE"}
                title={
                  <pre>
                    <code>{deleteRequest}</code>
                  </pre>
                }
                text={
                  <pre>
                    <code>{deleteResponse}</code>
                  </pre>
                }
              />
            }
          />
        </>
      ),
    },
    {
      title: "CONNECT",
      textForSearch: "Настраивает туннель с сервером, определенным по ресурсу.",
      jsx: (
        <TableTwoCol
          title={<h3>CONNECT</h3>}
          text={<p>Настраивает туннель с сервером, определенным по ресурсу.</p>}
        />
      ),
    },
    {
      title: "OPTIONS",
      textForSearch: "Описывает параметры соединения с ресурсом.",
      jsx: (
        <TableTwoCol
          title={<h3>OPTIONS</h3>}
          text={<p>Описывает параметры соединения с ресурсом.</p>}
        />
      ),
    },
    {
      title: "TRACE",
      textForSearch: "Вызывает возвращаемое текстовое сообщение с ресурса.",
      jsx: (
        <TableTwoCol
          title={<h3>TRACE</h3>}
          text={<p>Вызывает возвращаемое текстовое сообщение с ресурса.</p>}
        />
      ),
    },
    {
      title: "PATCH",
      textForSearch: "Частично изменяет ресурс.",
      jsx: (
        <TableTwoCol
          title={<h3>PATCH</h3>}
          text={<p>Частично изменяет ресурс.</p>}
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="http_method">
          <TableBody>
            <TableOneCol text={<h2>Методы HTTP запроса.</h2>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
