import React from "react";
import "@components/Menu/menu.scss";
import { IMenuInfoProps } from "../../types/interface";

function MenuJs({
  sectionFirst,
  sectionSecond,
  sectionThird,
  sectionFourth,
  sectionFifth,
  sectionSixth,
  sectionSeventh,
  sectionEighth,
  sectionNinth,
  sectionTenth,
  sectionEleventh,
  sectionTwelfth,
  sectionThirteenth,
  sectionFourteenth,
  sectionFifteenth,
  sectionSixteenth,
  sectionSeventeenth,
  sectionEighteenth,
  sectionNineteenth,
  sectionTwentieth,
  onClose,
}: IMenuInfoProps) {
  return (
    <div className="menu-container">
      <a className="dropdown-item" href="#js_visibility" onClick={onClose}>
        {sectionFirst}
      </a>
      <a className="dropdown-item" href="#js_variables" onClick={onClose}>
        {sectionSecond}
      </a>
      <a className="dropdown-item" href="#js_operators" onClick={onClose}>
        {sectionThird}
      </a>
      <a className="dropdown-item" href="#js_cycles" onClick={onClose}>
        {sectionFourth}
      </a>
      <a className="dropdown-item" href="#js_number" onClick={onClose}>
        {sectionFifth}
      </a>
      <a className="dropdown-item" href="#js_string" onClick={onClose}>
        {sectionSixth}
      </a>
      <a className="dropdown-item" href="#js_object" onClick={onClose}>
        {sectionSeventh}
      </a>
      <a className="dropdown-item" href="#js_array" onClick={onClose}>
        {sectionEighth}
      </a>
      <a className="dropdown-item" href="#js_function" onClick={onClose}>
        {sectionNinth}
      </a>
      <a
        className="dropdown-item"
        href="#js_regularExpressions"
        onClick={onClose}
      >
        {sectionTenth}
      </a>
      <a className="dropdown-item" href="#js_symbol" onClick={onClose}>
        {sectionEleventh}
      </a>
      <a className="dropdown-item" href="#js_descriptor" onClick={onClose}>
        {sectionTwelfth}
      </a>
      <a className="dropdown-item" href="#js_proto" onClick={onClose}>
        {sectionThirteenth}
      </a>
      <a className="dropdown-item" href="#js_class" onClick={onClose}>
        {sectionFourteenth}
      </a>
      <a className="dropdown-item" href="#js_map" onClick={onClose}>
        {sectionFifteenth}
      </a>
      <a className="dropdown-item" href="#js_set" onClick={onClose}>
        {sectionSixteenth}
      </a>
      <a className="dropdown-item" href="#js_time" onClick={onClose}>
        {sectionSeventeenth}
      </a>
      <a className="dropdown-item" href="#js_promise" onClick={onClose}>
        {sectionEighteenth}
      </a>
      <a className="dropdown-item" href="#js_await" onClick={onClose}>
        {sectionNineteenth}
      </a>
      <a className="dropdown-item" href="#js_proxy" onClick={onClose}>
        {sectionTwentieth}
      </a>
    </div>
  );
}

export default MenuJs;
