export const renderRU: string = `
import React from 'react';
import ReactDOM from 'react-dom';

const element = <h1>Привет, мир!</h1>;

// Здесь мы рендерим наш элемент в DOM-узел с id="root"
ReactDOM.render(
  element,
  document.getElementById('root')
);
`;

