import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Arrow from "@core/Arrow";
import MenuCss from "./MenuScss.tsx";
import "./scss.scss";
import ImportUA from "./ImportUA.tsx";
import MediaUA from "./MediaUA.tsx";
import ExtendUA from "./ExtendUA.tsx";
import AtRootUA from "./AtRootUA.tsx";
import OtherDirectiveUA from "./OtherDirectiveUA.tsx";
import ExpressionsUA from "./ExpressionsUA.tsx";
import MixinUA from "./MixinUA.tsx";
import ArgumentUA from "./ArgumentUA.tsx";
import ContentUA from "./ContentUA.tsx";
import AppBar from "@components/AppBar/AppBar.tsx";
import ScssTitleUA from "./ScssTitleUA.tsx";

export default function ScssUA() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term: React.SetStateAction<string>) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages active"}
        toUA={"/scss/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages "}
        toRU={"/scss/ru"}
        titleLangRU={"RU"}
        toHome={"/"}
        toHtml={"/html/ua"}
        toCss={"/css/ua"}
        toScss={"/scss/ua"}
        toJS={"/js/ua"}
        toDom={"/dom/ua"}
        toBom={"/bom/ua"}
        toHttp={"/http/ua"}
        toReact={"/react/ua"}
        toRedux={"/redux/ua"}
        toTS={"/ts/ua"}
        toNext={"/next/ua"}
        nameHome={"Головна сторінка"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
        page={"SCSS"}
        onClick={handleMenuInfoOpen}
        buttonRef={buttonRef}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuCss
              sectionFirst={"@import"}
              sectionSecond={"@media"}
              sectionThird={"@extend"}
              sectionFourth={"@at-root"}
              sectionFifth={"@debug"}
              sectionSixth={"@warn"}
              sectionSeventh={"@error"}
              sectionEighth={"@if"}
              sectionNinth={"@for"}
              sectionTenth={"@each"}
              sectionEleventh={"@while"}
              sectionTwelfth={"mixin"}
              sectionThirteenth={"Аргументи"}
              sectionFourteenth={"Блоки контенту в міксинах"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}
        <TableContainer>
          <ScssTitleUA searchTerm={searchTerm} />
          <ImportUA searchTerm={searchTerm} />
          <MediaUA searchTerm={searchTerm} />
          <ExtendUA searchTerm={searchTerm} />
          <AtRootUA searchTerm={searchTerm} />
          <OtherDirectiveUA searchTerm={searchTerm} />
          <ExpressionsUA searchTerm={searchTerm} />
          <MixinUA searchTerm={searchTerm} />
          <ArgumentUA searchTerm={searchTerm} />
          <ContentUA searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a target="_blank" href="https://sass-lang.com/documentation/">
            Документація SASS/SCSS
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
