import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Arrow from "@core/Arrow";
import MenuJs from "./MenuJs.tsx";
import "./js.scss";
import VisibilityUA from "./VisibilityUA.tsx";
import VariablesUA from "./VariablesUA.tsx";
import OperatorsUA from "./OperatorsUA.tsx";
import CyclesUA from "./CyclesUA.tsx";
import NumberUA from "./NumberUA.tsx";
import StringUA from "./StringUA.tsx";
import ObjectUA from "./ObjectUA.tsx";
import ArrayUA from "./ArrayUA.tsx";
import FunctionUA from "./FunctionUA.tsx";
import RegularExpressionsUA from "./RegularExpressionsUA.tsx";
import SymbolUA from "./SymbolUA.tsx";
import DescriptorUA from "./DescriptorUA.tsx";
import ProtoUA from "./ProtoUA.tsx";
import ClassUA from "./ClassUA.tsx";
import MapUA from "./MapUA.tsx";
import SetUA from "./SetUA.tsx";
import TimeUA from "./TimeUA.tsx";
import PromiseUA from "./PromiseUA.tsx";
import AwaitUA from "./AwaitUA.tsx";
import ProxyUA from "./ProxyUA.tsx";
import AppBar from "@components/AppBar/AppBar.tsx";

export default function JsUA() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term: React.SetStateAction<string>) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages active"}
        toUA={"/js/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages"}
        toRU={"/js/ru"}
        titleLangRU={"RU"}
        toHome={"/"}
        toHtml={"/html/ua"}
        toCss={"/css/ua"}
        toScss={"/scss/ua"}
        toJS={"/js/ua"}
        toDom={"/dom/ua"}
        toBom={"/bom/ua"}
        toHttp={"/http/ua"}
        toReact={"/react/ua"}
        toRedux={"/redux/ua"}
        toTS={"/ts/ua"}
        toNext={"/next/ua"}
        nameHome={"Головна сторінка"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
        page={"JavaScript"}
        onClick={handleMenuInfoOpen}
        buttonRef={buttonRef}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuJs
              sectionFirst={"Область видимості"}
              sectionSecond={"Змінні"}
              sectionThird={"Оператори"}
              sectionFourth={"Цикли"}
              sectionFifth={"Числа та Math"}
              sectionSixth={"Рядки"}
              sectionSeventh={"Об'єкти"}
              sectionEighth={"Массиви"}
              sectionNinth={"Функції"}
              sectionTenth={"Регулярні вирази"}
              sectionEleventh={"Symbol"}
              sectionTwelfth={"Дескриптор якості"}
              sectionThirteenth={"Прототип об'єкта"}
              sectionFourteenth={"Класи"}
              sectionFifteenth={"Map"}
              sectionSixteenth={"Set"}
              sectionSeventeenth={"Порядок обробки подій"}
              sectionEighteenth={"Promise"}
              sectionNineteenth={"Async/await"}
              sectionTwentieth={"Proxy"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}
        <TableContainer>
          <VisibilityUA searchTerm={searchTerm} />
          <VariablesUA searchTerm={searchTerm} />
          <OperatorsUA searchTerm={searchTerm} />
          <CyclesUA searchTerm={searchTerm} />
          <NumberUA searchTerm={searchTerm} />
          <StringUA searchTerm={searchTerm} />
          <ObjectUA searchTerm={searchTerm} />
          <ArrayUA searchTerm={searchTerm} />
          <FunctionUA searchTerm={searchTerm} />
          <RegularExpressionsUA searchTerm={searchTerm} />
          <SymbolUA searchTerm={searchTerm} />
          <DescriptorUA searchTerm={searchTerm} />
          <ProtoUA searchTerm={searchTerm} />
          <ClassUA searchTerm={searchTerm} />
          <MapUA searchTerm={searchTerm} />
          <SetUA searchTerm={searchTerm} />
          <TimeUA searchTerm={searchTerm} />
          <PromiseUA searchTerm={searchTerm} />
          <AwaitUA searchTerm={searchTerm} />
          <ProxyUA searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a
            target="_blank"
            href="https://developer.mozilla.org/en-US/docs/Web/JavaScript"
          >
            Документація JS
          </a>
          <a target="_blank" href="https://uk.javascript.info/">
            Toturial JavaScript
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
