import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import { matches } from "./DomConstPre.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function DomFindElementsRU({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: ".getElementById(id)",
      category: "DOM",
      textForSearch: "Поиск элемента по идентификатору.",
      jsx: (
        <TableTwoCol
          title={<h3>.getElementById(id)</h3>}
          text={
            <p>
              Находит элемент по идентификатору элемента, является статическим.
              <br />
              <code>document.getElementById(id)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".getElementsByName(name)",
      category: "DOM",
      textForSearch: "Поиск элементов по имени.",
      jsx: (
        <TableTwoCol
          title={<h3>.getElementsByName(name)</h3>}
          text={
            <p>
              Находит элементы по имени, является динамичным (живым).
              <br />
              <code>document.getElementsByName(name)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".getElementsByTagName(name)",
      category: "DOM",
      textForSearch: "Поиск элементов по имени тега.",
      jsx: (
        <TableTwoCol
          title={<h3>.getElementsByTagName(name)</h3>}
          text={
            <p>
              Находит элементы по имени тегов. Способен искать внутри элементов
              и является динамичным (живым).
              <br />
              <code>document.getElementsByTagName(name)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".getElementsByClassName(name)",
      category: "DOM",
      textForSearch: "Поиск элементов по названию класса.",
      jsx: (
        <TableTwoCol
          title={<h3>.getElementsByClassName(name)</h3>}
          text={
            <p>
              Находит элементы по названию класса. Способен искать внутри
              элементов и является динамичным (живым).
              <br />
              <code>document.getElementsByClassName(name)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".querySelectorAll(selector)",
      category: "DOM",
      textForSearch: "Поиск всех элементов, соответствующих CSS-селектору.",
      jsx: (
        <TableTwoCol
          title={<h3>.querySelectorAll(selector)</h3>}
          text={
            <p>
              Находит элементы соответствующему CSS селектору. Способен искать
              внутри элементов и является статическим.
              <br />
              <code>document.querySelectorAll(selector)</code>
              <br />
              Поиск по тегу первого уровня вложенности:
              <code>document.querySelectorAll(selector &gt; selector)</code>
              <br />
              Поиск по нескольким классам:
              <code>document.querySelectorAll(selector, selector)</code>
              <br />
              Поиск по вложенным классам:
              <code>document.querySelectorAll(selector selector)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".querySelector(selector)",
      category: "DOM",
      textForSearch: "Поиск первого элемента, соответствующего CSS-селектору.",
      jsx: (
        <TableTwoCol
          title={<h3>.querySelector(selector)</h3>}
          text={
            <p>
              Находит первый элемент соответствующему CSS селектору. Способен
              искать внутри элементов и является статическим.
              <br />
              <code>document.querySelector(selector)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".closest",
      category: "DOM",
      textForSearch: "Поиск ближайшего предка.",
      jsx: (
        <TableTwoCol
          title={<h3>.closest</h3>}
          text={
            <p>
              Ищет ближайшего предка, который соответствует CSS селектору.
              <br />
              <code>document.querySelector(selector).closest(selector)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".matches",
      category: "DOM",
      textForSearch: "Проверка соответствия элемента CSS-селектору.",
      jsx: (
        <TableTwoCol
          title={<h3>.matches</h3>}
          text={
            <p>
              Ничего не ищет, а проверяет, удовлетворяет ли элемент CSS
              селектору, возвращает <b>true</b> или <b>false</b>.
              <br />
              <pre>
                <code>{matches}</code>
              </pre>
            </p>
          }
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="dom_findElement">
          <TableBody>
            <TableOneCol text={<h3>Поиск элементов.</h3>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
