import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import TableTwoEqualCol from "@core/TableTwoEqualCol.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function TableRU({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "caption-side",
      category: "CSS",
      textForSearch: "Позиция заголовка таблицы.",
      jsx: (
        <TableTwoCol
          title={<h3>caption-side:</h3>}
          text={
            <p>
              Определяет положение заголовка таблицы, который задается с помощью
              тега <code>&lt;caption&gt;</code>, относительно самой таблицы.
            </p>
          }
        />
      ),
    },
    {
      title: "columns",
      category: "CSS",
      textForSearch: "Количество и ширина столбцов.",
      jsx: (
        <TableTwoCol
          title={<h3>columns:</h3>}
          text={
            <p>
              Устанавливает количество столбцов, а также ширину этих столбцов.
            </p>
          }
        />
      ),
    },
    {
      title: "column-width",
      category: "CSS",
      textForSearch: "Ширина столбца.",
      jsx: (
        <TableTwoCol
          title={<h3>column-width:</h3>}
          text={<p>Устанавливает идеальную ширину столбца.</p>}
        />
      ),
    },
    {
      title: "column-count",
      category: "CSS",
      textForSearch: "Количество столбцов.",
      jsx: (
        <TableTwoCol
          title={<h3>column-count:</h3>}
          text={
            <p>Разбивает содержимое элемента на заданное число столбцов.</p>
          }
        />
      ),
    },
    {
      title: "column-fill",
      category: "CSS",
      textForSearch: "Распределение содержимого в столбцах.",
      jsx: (
        <TableTwoCol
          title={<h3>column-fill:</h3>}
          text={
            <p>
              Применяется к родительскому элементу, разбитому на столбцы и
              указывает как содержимое располагается внутри столбца.
            </p>
          }
        />
      ),
    },
    {
      title: "column-gap",
      category: "CSS",
      textForSearch: "Промежуток между столбцами.",
      jsx: (
        <TableTwoCol
          title={<h3>column-gap</h3>}
          text={<p>Устанавливает промежуток (интервал) между колонками.</p>}
        />
      ),
    },
    {
      title: "column-span",
      category: "CSS",
      textForSearch: "Объединение элементом нескольких столбцов.",
      jsx: (
        <TableTwoCol
          title={<h3>column-span:</h3>}
          text={
            <p>
              Позволяет элементу охватывать все столбцы. Например для заголовка.
            </p>
          }
        />
      ),
    },
    {
      title: "column-rule",
      category: "CSS",
      textForSearch: "Ширина, стиль и цвет линии между столбцами.",
      jsx: (
        <TableTwoCol
          title={<h3>column-rule:</h3>}
          text={<p>Устанавливает ширину, стиль и цвет линии.</p>}
        />
      ),
    },
    {
      title: "column-rule-color",
      category: "CSS",
      textForSearch: "Цвет линии между столбцами.",
      jsx: (
        <TableTwoCol
          title={<h3>column-rule-color:</h3>}
          text={
            <p>
              Устанавливает цвет линии, расположенной между колонками при
              мультиколоночной вёрстке.
            </p>
          }
        />
      ),
    },
    {
      title: "column-rule-style",
      category: "CSS",
      textForSearch: "Стиль линии между столбцами.",
      jsx: (
        <TableTwoCol
          title={<h3>column-rule-style:</h3>}
          text={
            <p>
              Устанавливает стиль линии, расположенной между колонками при
              мультиколоночной вёрстке.
            </p>
          }
        />
      ),
    },
    {
      title: "column-rule-width",
      category: "CSS",
      textForSearch: "Ширина линии между столбцами.",
      jsx: (
        <TableTwoCol
          title={<h3>column-rule-width:</h3>}
          text={<p>Задает ширину линии, нарисованной между столбцами.</p>}
        />
      ),
    },
    {
      title: "empty-cells",
      category: "CSS",
      textForSearch: "Отображение рамок для пустых ячеек таблицы.",
      jsx: (
        <TableTwoCol
          title={<h3>empty-cells:</h3>}
          text={
            <p>
              Определяет, будут ли отображаться границы и фон вокруг
              <code>&lt;table&gt;</code> ячеек, не имеющих видимого содержимого.
            </p>
          }
        />
      ),
    },
    {
      title: "table-layout",
      category: "CSS",
      textForSearch: "Алгоритм разметки таблицы.",
      jsx: (
        <TableTwoCol
          title={<h3>table-layout:</h3>}
          text={
            <p>
              Задает алгоритм, используемый для разметки
              <code>&lt;table&gt;</code> ячеек, строк и столбцов.
            </p>
          }
        />
      ),
    },
  ];

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredData.length > 0 && (
        <Table id="css_table">
          <TableBody>
            <TableOneCol text={<h2>Таблицы.</h2>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
