import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Arrow from "@core/Arrow";
import MenuReact from "./MenuReact.tsx";
import "./react.scss";
import InstallUA from "./InstallUA.tsx";
import AppBar from "@components/AppBar/AppBar.tsx";
import ReactTitleUA from "./ReactTitleUA.tsx";
import JsxUA from "./JsxUA.tsx";
import RenderingUA from "./RenderingUA.tsx";
import ComponentUA from "./ComponentUA.tsx";
import PropsUA from "./PropsUA.tsx";
import StateUA from "./StateUA.tsx";
import LifecycleUA from "./LifecycleUA.tsx";
import ConditionalRenderingUA from "./ConditionalRenderingUA.tsx";
import ListUA from "./ListUA.tsx";
import FormUA from "./Form/FormUA.tsx";
import StateUpUA from "./StateUpUA.tsx";
import HooksTitleUA from "./HooksTitleUA.tsx";
import UseStateUA from "./UseState/UseStateUA.tsx";
import UseEffectUA from "./UseEffect/UseEffectUA.tsx";
import UseContextUA from "./UseContext/UseContextUA.tsx";
import UseReducerUA from "./UseReducer/UseReducerUA.tsx";
import UseCallbackUA from "./UseCallback/UseCallbackUA.tsx";
import UseMemoUA from "./UseMemo/UseMemoUA.tsx";
import UseRefUA from "./UseRef/UseRefUA.tsx";
import RefForwardUA from "./RefForward/RefForwardUA.tsx";
import UseImperativeHandleUA from "./UseImperativeHandle/UseImperativeHandleUA.tsx";
import UseDebugValueUA from "./UseDebugValue/UseDebugValueUA.tsx";
import UseLayoutEffectUA from "./UseLayoutEffect/UseLayoutEffectUA.tsx";
import UseTransitionUA from "./UseTransition/UseTransitionUA.tsx";
import UseDeferredValueUA from "./UseDeferredValue/UseDeferredValueUA.tsx";
import UseIdUA from "./UseId/UseIdUA.tsx";
import ReactRouterUA from "./ReactRouter/ReactRouterUA.tsx";

export default function ReactUA() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term: React.SetStateAction<string>) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages active"}
        toUA={"/react/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages "}
        toRU={"/react/ru"}
        titleLangRU={"RU"}
        toHome={"/"}
        toHtml={"/html/ua"}
        toCss={"/css/ua"}
        toScss={"/scss/ua"}
        toJS={"/js/ua"}
        toDom={"/dom/ua"}
        toBom={"/bom/ua"}
        toHttp={"/http/ua"}
        toReact={"/react/ua"}
        toRedux={"/redux/ua"}
        toTS={"/ts/ua"}
        toNext={"/next/ua"}
        nameHome={"Головна сторінка"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
        page={"React"}
        onClick={handleMenuInfoOpen}
        buttonRef={buttonRef}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuReact
              sectionFirst={"React"}
              sectionSecond={"Знайомство з JSX"}
              sectionThird={"Рендеринг"}
              sectionFourth={"Компоненти"}
              sectionFifth={"Експорт компонентів"}
              sectionSixth={"Імпорт компонентів"}
              sectionSeventh={"Props"}
              sectionEighth={"Стан (State)"}
              sectionNinth={"Життєвий цикл (Lifecycle)"}
              sectionTenth={"Умовний рендеринг"}
              sectionEleventh={"Відображення списків"}
              sectionTwelfth={"Ключі (Keys)"}
              sectionThirteenth={"Форми"}
              sectionFourteenth={"Підйом стану"}
              sectionFifteenth={"Hooks"}
              sectionSixteenth={"useState"}
              sectionSeventeenth={"useEffect"}
              sectionEighteenth={"useContext"}
              sectionNineteenth={"useReducer"}
              sectionTwentieth={"useCallback"}
              sectionTwentyFirst={"useMemo"}
              sectionTwentySecond={"useRef"}
              sectionTwentyThird={"forwardRef"}
              sectionTwentyFourth={"useImperativeHandle"}
              sectionTwentyFifth={"useLayoutEffect"}
              sectionTwentySixth={"useDebugValue"}
              sectionTwentySeventh={"useTransition"}
              sectionTwentyEighth={"useDeferredValue"}
              sectionTwentyNinth={"useId"}
              sectionThirtieth={"React Router"}
              sectionThirtyFirst={"Install"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}
        <TableContainer>
          <ReactTitleUA searchTerm={searchTerm} />
          <JsxUA searchTerm={searchTerm} />
          <RenderingUA searchTerm={searchTerm} />
          <ComponentUA searchTerm={searchTerm} />
          <PropsUA searchTerm={searchTerm} />
          <StateUA searchTerm={searchTerm} />
          <LifecycleUA searchTerm={searchTerm} />
          <ConditionalRenderingUA searchTerm={searchTerm} />
          <ListUA searchTerm={searchTerm} />
          <FormUA searchTerm={searchTerm} />
          <StateUpUA searchTerm={searchTerm} />
          <HooksTitleUA searchTerm={searchTerm} />
          <UseStateUA searchTerm={searchTerm} />
          <UseEffectUA searchTerm={searchTerm} />
          <UseContextUA searchTerm={searchTerm} />
          <UseReducerUA searchTerm={searchTerm} />
          <UseCallbackUA searchTerm={searchTerm} />
          <UseMemoUA searchTerm={searchTerm} />
          <UseRefUA searchTerm={searchTerm} />
          <RefForwardUA searchTerm={searchTerm} />
          <UseImperativeHandleUA searchTerm={searchTerm} />
          <UseLayoutEffectUA searchTerm={searchTerm} />
          <UseDebugValueUA searchTerm={searchTerm} />
          <UseTransitionUA searchTerm={searchTerm} />
          <UseDeferredValueUA searchTerm={searchTerm} />
          <UseIdUA searchTerm={searchTerm} />
          <ReactRouterUA searchTerm={searchTerm} />
          <InstallUA searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a target="_blank" href="https://uk.legacy.reactjs.org/">
            Документація React
          </a>
          <a target="_blank" href="https://uk.react.dev/">
            Документація React
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
