import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableRow from "@mui/material/TableRow";
import TableCell from "@mui/material/TableCell";
import { IMethodsProps } from "@type/interface.ts";

export default function ReactTitleUA({ searchTerm }: IMethodsProps) {
  const reactTitle = [
    {
      title: "React",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                React — це відкрита JavaScript-бібліотека для створення
                користувацьких інтерфейсів (UI). Вона розроблена та
                підтримується компанією Meta (раніше Facebook) і спільнотою
                розробників. React дозволяє створювати складні, інтерактивні
                веб-додатки, розбиваючи їх на невеликі, незалежні частини, які
                називаються компонентами.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "React",
      jsx: (
        <>
          <TableOneCol
            text={
              <div>
                <p>React ідеально підходить для створення:</p>
                <ul>
                  <li>
                    Односторінкових додатків (SPA): Веб-додатки, які
                    завантажують одну HTML-сторінку, а потім динамічно оновлюють
                    її вміст. Приклади: Gmail, Trello.
                  </li>
                  <li>
                    Інтерактивних елементів: Складні форми, динамічні панелі
                    управління, інтерактивні карти.
                  </li>
                  <li>
                    Мобільних додатків: За допомогою React Native можна
                    використовувати знання React для розробки додатків для iOS
                    та Android.
                  </li>
                </ul>
              </div>
            }
          />
        </>
      ),
    },
  ];

  const filteredTitle = reactTitle.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredTitle.length > 0 && (
        <Table id="react_title">
          <TableBody>
            <TableRow>
              <TableCell style={{ border: "none", padding: "5px" }}>
                <h1>Робота з React.</h1>
              </TableCell>
            </TableRow>

            {filteredTitle.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
