export const lifecycleFC: string = `
import React, { useState, useEffect } from "react";

export default function Timer() {
  const [seconds, setSeconds] = useState(0);
  const [isActive, setIsActive] = useState(false);
  
  useEffect(() => {
    let intervalId: number | null = null;
    if (isActive) {
      intervalId = setInterval(() => {
        setSeconds((prevSeconds) => prevSeconds + 1);
      }, 1000);
    }
    return () => {
      if (intervalId !== null) {
        clearInterval(intervalId);
      }
    };
  }, [isActive]);
  
  return (
    <>
      <div>
        Passed {seconds} second
      </div>
      <button        
        onClick={() => setIsActive(true)}
      >
        Start
      </button>
      <button onClick={() => setIsActive(false)}>
        Stop
      </button>
      <button        
        onClick={() => {
          setSeconds(0);
          setIsActive(false);
        }}
      >
        Reset
      </button>
    </>
  );
}
`;

export const lifecycleCC: string = `
import React, { Component } from "react";

export default class TimerCC extends Component {
  constructor(props) {
    super(props);
    this.state = {
      seconds: 0,
      isActive: false,
    };
    this.handleStart = this.handleStart.bind(this);
    this.handleStop = this.handleStop.bind(this);
    this.handleReset = this.handleReset.bind(this);
  }

  componentDidUpdate(prevProps, prevState) {
    if (this.state.isActive !== prevState.isActive) {
      if (this.state.isActive) {
        this.intervalId = setInterval(() => {
          this.setState((prevState) => ({
            seconds: prevState.seconds + 1,
          }));
        }, 1000);
      } else {
        clearInterval(this.intervalId);
      }
    }
  }

  componentWillUnmount() {
    clearInterval(this.intervalId);
  }

  handleStart() {
    this.setState({ isActive: true });
  }

  handleStop() {
    this.setState({ isActive: false });
  }

  handleReset() {
    this.setState({ seconds: 0, isActive: false });
  }

  render() {
    const { seconds, isActive } = this.state;

    return (
      <>
        <div>Passed {seconds} second</div>
        <button onClick={this.handleStart}
        >
          Start
        </button>
        <button onClick={this.handleStop}>
          Stop
        </button>
        <button onClick={this.handleReset}
        >
          Reset
        </button>
      </>
    );
  }
}
`;

export const clockFunction: string = `
import React, { useState, useEffect } from "react";

export default function ClockFunction(props) {
  const [dateNow, setDate] = useState(getTime());

  useEffect(() => {
    setInterval(() => {
      setDate(getTime());
    }, 1000);
    
  }, []);

  function getTime() {
    const date = new Date();

    return { date };
  }

  return (
    <>
      <h4>Time now!</h4>
      <h4>{dateNow.date.toLocaleTimeString()}</h4>
    </>
  );
}
`;

export const clockClass: string = `
import React, { Component } from "react";

export default class ClockClass extends Component {
  constructor(props) {
    super(props);
    this.state = { date: new Date() };
  }

  componentDidMount() {
    this.timerID = setInterval(() => this.tick(), 1000);
  }

  componentWillUnmount() {
    clearInterval(this.timerID);
  }

  tick() {
    this.setState({
      date: new Date(),
    });
  }

  render() {
    return (
      <>
        <h4>Time now!</h4>            
        <h4>{this.state.date.toLocaleTimeString()}.</h4>
      </>
    );
  }
}
`;
