import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function TableRU({ searchTerm }: IMethodsProps) {
  const tableData = [
    {
      title: "Содержание таблиц",
      category: "HTML",
      textForSearch:
        "Содержание таблиц, <table>, <caption>, <col>, <colgroup>, <td>, <th>, <tr>, <thead>, <tbody>, <tfoot>.",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Эти элементы используются для создания и обработки табличных
                данных.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "<caption>",
      category: "HTML",
      textForSearch: "<caption>, заголовок таблицы, table.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;caption&gt; &lt;/caption&gt;</h3>}
          text={
            <p>
              Элемент заголовка таблицы. Если этот элемент используется, он
              всегда должен быть первым вложенным элементом тега &lt;table&gt;.
            </p>
          }
        />
      ),
    },
    {
      title: "<col>",
      category: "HTML",
      textForSearch: "<col>, столбец, колонка, colgroup.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;col /&gt;</h3>}
          text={
            <p>
              Определяет столбец в таблице и используется для определения общей
              семантики на всех ячейках. Обычно он находится в элементе
              &lt;colgroup&gt;.
            </p>
          }
        />
      ),
    },
    {
      title: "<colgroup>",
      category: "HTML",
      textForSearch: "<colgroup>, группа столбцов, table.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;colgroup&gt; &lt;/colgroup&gt;</h3>}
          text={<p>Определяет группу столбцов в таблице.</p>}
        />
      ),
    },
    {
      title: "<table>",
      category: "HTML",
      textForSearch: "<table>, двумерная таблица, строки, столбцы.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;table&gt; &lt;/table&gt;</h3>}
          text={
            <p>
              Информация представлена в двумерной таблице, состоящей из строк и
              столбцов ячеек, содержащих данные.
            </p>
          }
        />
      ),
    },
    {
      title: "<td>",
      category: "HTML",
      textForSearch: "<td>, ячейка таблицы, ячейка с данными, table.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;td&gt; &lt;/td&gt;</h3>}
          text={
            <p>
              Определяет ячейку таблицы, которая содержит данные. Участвует в
              табличной модели.
            </p>
          }
        />
      ),
    },
    {
      title: "<th>",
      category: "HTML",
      textForSearch: "<th>, заголовок ячейки, заголовок группы ячеек.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;th&gt; &lt;/th&gt;</h3>}
          text={<p>Определяет ячейку как заголовок группы ячеек таблицы.</p>}
        />
      ),
    },
    {
      title: "<tr>",
      category: "HTML",
      textForSearch: "<tr>, строка, ряд ячеек, table.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;tr&gt; &lt;/tr&gt;</h3>}
          text={<p>Определяет ряд ячеек в таблице.</p>}
        />
      ),
    },
    {
      title: "<thead>",
      category: "HTML",
      textForSearch: "<thead>, заголовок таблицы, header.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;thead&gt; &lt;/thead&gt;</h3>}
          text={<p>Набор строк, определяющих заголовок столбцов таблицы.</p>}
        />
      ),
    },
    {
      title: "<tbody>",
      category: "HTML",
      textForSearch: "<tbody>, тело таблицы, body.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;tbody&gt; &lt;/tbody&gt;</h3>}
          text={<p>Набор строк таблицы, составляющие тело таблицы.</p>}
        />
      ),
    },
    {
      title: "<tfoot>",
      category: "HTML",
      textForSearch: "<tfoot>, подвал таблицы, footer.",
      jsx: (
        <TableTwoCol
          title={<h3>&lt;tfoot&gt; &lt;/tfoot&gt;</h3>}
          text={
            <p>
              Элемент подвала таблицы, определяющий набор строк, суммирующих
              столбцы таблицы.
            </p>
          }
        />
      ),
    },
  ];

  const filteredTableData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredTableData.length > 0 && (
        <Table id="html_table">
          <TableBody>
            <TableOneCol text={<h2>Содержание таблиц.</h2>} />
            {filteredTableData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
