import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { IMethodsProps } from "@type/interface.ts";
import { formField } from "./UseIdConstPre";
import FormField from "./FormField";

export default function UseIdUA({ searchTerm }: IMethodsProps) {
  const useId = [
    {
      title: "useId",
      jsx: (
        <TableOneCol
          text={
            <>
              <p>
                useId — це хук React, який генерує унікальний ID, стабільний як
                на сервері, так і на клієнті. Він призначений для використання у
                випадках, коли компоненту потрібен унікальний ідентифікатор для
                зв'язку між елементами DOM, наприклад, для атрибутів
                доступності.
              </p>
              <ul>
                useId ідеально підходить для генерації ID, які використовуються
                у таких атрибутах HTML:
                <li>aria-labelledby</li>
                <li>aria-describedby</li>
                <li>htmlFor (для &lt;label&gt;)</li>
              </ul>
            </>
          }
        />
      ),
    },
    {
      title: "useId",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Приклад useId"}
              title={
                <>
                  <FormField />
                  <p>
                    const inputId = useId(); Цей рядок створює унікальний і
                    стабільний ідентифікатор для цього екземпляра компонента.
                    Наприклад, він може згенерувати ID на кшталт _r1:. <br />
                    htmlFor - атрибут htmlFor у &lt;label&gt; вказує, з яким
                    елементом форми пов'язана ця мітка. Ми передаємо йому
                    згенерований ID. <br />
                    id - трибут id в &lt;input&gt; отримує той самий унікальний
                    ID.
                  </p>
                </>
              }
              text={
                <pre>
                  <code>{formField}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredUseId = useId.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredUseId.length > 0 && (
        <Table id="react_useId">
          <TableBody>
            <TableOneCol text={<h3>useId.</h3>} />
            {filteredUseId.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
