import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import { IMethodsProps } from "@type/interface.ts";
import { renderUA } from "./RenderConstPre.ts";

export default function RenderingUA({ searchTerm }: IMethodsProps) {
  const jsVariablesData = [
    {
      title: "Рендеринг елементів React",
      jsx: (
        <>
          <TableOneCol
            text={
              <div>
                <p>
                  Рендеринг елементів React — це процес, при якому React
                  перетворює елементи, описані в JSX, на реальні DOM-узли, які
                  відображаються на веб-сторінці. Це основа того, як React будує
                  та оновлює користувацький інтерфейс.
                </p>
                <pre>
                  <code>{renderUA}</code>
                </pre>
              </div>
            }
          />
        </>
      ),
    },
  ];
  const filteredJsVariablesData = jsVariablesData.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredJsVariablesData.length > 0 && (
        <Table id="react_render">
          <TableBody>
            <TableOneCol text={<h3>Рендеринг.</h3>} />
            {filteredJsVariablesData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
