import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import { IMethodsProps } from "@type/interface.ts";
import ButtonExample from "@core/ButtonExample.tsx";
import TemperatureCalculator from "./Temperature.tsx";
import { temperature } from "./TemperatureConstPre.ts";

export default function StateUpRU({ searchTerm }: IMethodsProps) {
  const reactStateUp = [
    {
      title: "Подъем состояния, Lifting State Up",
      jsx: (
        <>
          <TableOneCol
            text={
              <div>
                <p>
                  Подъем состояния — это паттерн в React, который используется
                  для синхронизации состояния между несколькими дочерними
                  компонентами. Он заключается в том, чтобы перенести состояние
                  из дочерних компонентов в их ближайшего общего предка. Это
                  делает состояние "общим", и родительский компонент может
                  управлять им, передавая данные дочерним компонентам через
                  пропсы.
                </p>
                <ul>
                  Этот паттерн необходим, когда:
                  <li>
                    Несколько компонентов нуждаются в одном и том же состоянии.
                    Например, два компонента, отображающие температуру, должны
                    показывать одинаковое значение.
                  </li>
                  <li>
                    Дочерний компонент должен влиять на другой дочерний
                    компонент. Дочерний компонент A должен как-то изменить
                    компонент B.
                  </li>
                </ul>
                <ul>
                  Преимущества "Подъема состояния"
                  <li>
                    Синхронизация. Позволяет легко поддерживать синхронизацию
                    состояния между компонентами.
                  </li>
                  <li>
                    Централизация. Состояние находится в одном месте, что
                    упрощает его отслеживание, понимание и отладку.
                  </li>
                  <li>
                    Простота. Дочерние компоненты становятся проще, так как им
                    не нужно управлять своим собственным состоянием.
                  </li>
                </ul>
              </div>
            }
          />
        </>
      ),
    },
    {
      title: "Подъем состояния, Lifting State Up",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример"}
              title={
                <>
                  <TemperatureCalculator />
                  <p>
                    toCelsius(fahrenheit) и toFahrenheit(celsius). Эти функции
                    выполняют основную математическую логику преобразования
                    температур. Они находятся вне компонента, что делает код
                    чище.
                    <br />
                    tryConvert(temperature, convert). Эта функция проверяет,
                    является ли входное значение числом. Если нет, возвращает
                    пустую строку. <br />
                    TemperatureInput отображает одно поле ввода. Он получает
                    свои данные (temperature и scale) и функцию для обработки
                    изменений (onTemperatureChange) через пропсы. <br />
                    handleChange вызывает функцию, переданную из родительского
                    компонента (onTemperatureChange), отправляя вверх новое
                    значение из поля ввода.
                    <br />
                    const [state, setState] сохраняет состояние.
                    handleCelsiusChange и handleFahrenheitChange — это функции,
                    которые обновляют состояние state. Когда они вызываются, они
                    сохраняют новое значение температуры и ее шкалу. <br />
                    celsius и fahrenheit вычисляются на основе текущего
                    состояния temperature и scale. Это гарантирует, что значения
                    в обоих полях всегда будут синхронизированы. <br />
                  </p>
                </>
              }
              text={
                <pre>
                  <code>{temperature}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredStateUp = reactStateUp.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredStateUp.length > 0 && (
        <Table id="react_stateUp">
          <TableBody>
            <TableOneCol text={<h3>Подъем состояния.</h3>} />
            {filteredStateUp.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
