import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function HooksTitleUA({ searchTerm }: IMethodsProps) {
  const reactHooks = [
    {
      title: "Hooks",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Хуки (Hooks) — це спеціальні функції в React, які дозволяють
                використовувати стан та інші можливості React у функціональних
                компонентах. До появи хуків, ці можливості були доступні лише в
                класових компонентах. Хуки дозволили писати компоненти простіше,
                уникаючи складності класів, конструкторів, прив'язки this та
                методів життєвого циклу.
              </p>
            }
          />
        </>
      ),
    },
  ];

  const filteredReactHooks = reactHooks.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredReactHooks.length > 0 && (
        <Table id="react_hooks">
          <TableBody>
            <TableOneCol text={<h2>Hooks.</h2>} />
            {filteredReactHooks.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
