import React, { useState } from "react";

const scaleNames = {
  c: "Celsius",
  f: "Fahrenheit",
};

function toCelsius(fahrenheit) {
  return ((fahrenheit - 32) * 5) / 9;
}

function toFahrenheit(celsius) {
  return (celsius * 9) / 5 + 32;
}

function tryConvert(temperature, convert) {
  const input = parseFloat(temperature);
  if (Number.isNaN(input)) {
    return "";
  }
  const output = convert(input);
  const rounded = Math.round(output * 1000) / 1000;
  return rounded.toString();
}

function TemperatureInput({ temperature, scale, onTemperatureChange }) {
  const handleChange = (e) => {
    onTemperatureChange(e.target.value);
  };

  return (
    <fieldset style={{ margin: "10px 0" }}>
      <legend style={{ marginBottom: "5px" }}>
        Temperature in degrees {scaleNames[scale]}:
      </legend>
      <input
        style={{ marginBottom: "5px" }}
        value={temperature}
        onChange={handleChange}
      />
    </fieldset>
  );
}

export default function TemperatureFunction() {
  const [state, setState] = useState({ temperature: "", scale: "c" });
  const { temperature, scale } = state;

  const handleCelsiusChange = (newTemperature) => {
    setState({ scale: "c", temperature: newTemperature });
  };

  const handleFahrenheitChange = (newTemperature) => {
    setState({ scale: "f", temperature: newTemperature });
  };

  const celsius =
    scale === "f" ? tryConvert(temperature, toCelsius) : temperature;
  const fahrenheit =
    scale === "c" ? tryConvert(temperature, toFahrenheit) : temperature;

  return (
    <div>
      <TemperatureInput
        scale="c"
        temperature={celsius}
        onTemperatureChange={handleCelsiusChange}
      />
      <TemperatureInput
        scale="f"
        temperature={fahrenheit}
        onTemperatureChange={handleFahrenheitChange}
      />
    </div>
  );
}
