import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import { IMethodsProps } from "@type/interface.ts";
import { postCode2 } from "./HttpConstPre.tsx";

export default function HttpFetchUA({ searchTerm }: IMethodsProps) {
  const tableFetch = [
    {
      title: "Fetch",
      textForSearch:
        "Fetch - це сучасний метод для виконання HTTP-запитів. Він повертає проміс. Підтримується сучасними браузерами, для старих потрібні поліфіли. let promise = fetch(url, [options])",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Цей метод є найсучаснішим. Він не підтримується старими
                браузерами, але підтримується всіма сучасними. Для підтримки
                старих браузерів можна використовувати поліфіли.
                <br /> `let promise = fetch(url, [options])`
                <br /> **url** – URL для надсилання запиту.
                <br /> **options** – додаткові параметри: метод, заголовки тощо.
              </p>
            }
          />
        </>
      ),
    },
  ];

  const tableResponse = [
    {
      title: "Response",
      textForSearch:
        "Параметри отримання відповідей від сервера. response.status, response.ok, response.headers, response.text(), response.json(), response.formData(), response.blob(), response.arrayBuffer(), response.body().",
      jsx: (
        <>
          <TableOneCol
            text={<p>Це параметри отримання відповідей від сервера.</p>}
          />
        </>
      ),
    },
    {
      title: "response.status",
      textForSearch: "Виводить HTTP-код відповіді.",
      jsx: (
        <TableTwoCol
          title={<h3>response.status</h3>}
          text={<p>Виводить HTTP-код відповіді.</p>}
        />
      ),
    },
    {
      title: "response.ok",
      textForSearch:
        "Бульове значення, яке виводить true, якщо статус відповіді в діапазоні 200-299.",
      jsx: (
        <TableTwoCol
          title={<h3>response.ok</h3>}
          text={
            <p>
              Бульове значення, яке виводить `true`, якщо статус відповіді в
              діапазоні 200-299.
            </p>
          }
        />
      ),
    },
    {
      title: "response.headers",
      textForSearch: "Дуже схожий на Map об'єкт із HTTP-заголовками.",
      jsx: (
        <TableTwoCol
          title={<h3>response.headers</h3>}
          text={<p>Дуже схожий на `Map` об'єкт із HTTP-заголовками.</p>}
        />
      ),
    },
    {
      title: "response.text()",
      textForSearch: "Повертає відповідь як звичайний текст.",
      jsx: (
        <TableTwoCol
          title={<h3>response.text()</h3>}
          text={<p>Повертає відповідь як звичайний текст.</p>}
        />
      ),
    },
    {
      title: "response.json()",
      textForSearch: "Перетворює відповідь на JSON-об'єкт.",
      jsx: (
        <TableTwoCol
          title={<h3>response.json()</h3>}
          text={<p>Перетворює відповідь на JSON-об'єкт.</p>}
        />
      ),
    },
    {
      title: "response.formData()",
      textForSearch: "Повертає відповідь як об'єкт FormData.",
      jsx: (
        <TableTwoCol
          title={<h3>response.formData()</h3>}
          text={<p>Повертає відповідь як об'єкт `FormData`.</p>}
        />
      ),
    },
    {
      title: "response.blob()",
      textForSearch: "Повертає об'єкт як Blob.",
      jsx: (
        <TableTwoCol
          title={<h3>response.blob()</h3>}
          text={<p>Повертає об'єкт як `Blob`.</p>}
        />
      ),
    },
    {
      title: "response.arrayBuffer()",
      textForSearch: "Повертає відповідь як ArrayBuffer.",
      jsx: (
        <TableTwoCol
          title={<h3>response.arrayBuffer()</h3>}
          text={<p>Повертає відповідь як `ArrayBuffer`.</p>}
        />
      ),
    },
    {
      title: "response.body()",
      textForSearch:
        "Це об'єкт ReadableStream, за допомогою якого можна зчитувати тіло запиту частинами.",
      jsx: (
        <TableTwoCol
          title={<h3>response.body()</h3>}
          text={
            <p>
              Це об'єкт `ReadableStream`, за допомогою якого можна зчитувати
              тіло запиту частинами.
            </p>
          }
        />
      ),
    },
  ];

  const tablePostFeach = [
    {
      title: "POST-запити",
      textForSearch:
        "Параметри для POST-запитів за допомогою fetch: method, headers, body. Властивості тіла запиту: JSON, FormData, Blob/BufferSource, URLSearchParams.",
      jsx: (
        <>
          <TableTwoCol
            title={<h3>method</h3>}
            text={<p>HTTP метод, у цьому випадку **POST**.</p>}
          />
          <TableTwoCol
            title={<h3>headers</h3>}
            text={<p>Для встановлення заголовка запиту.</p>}
          />
          <TableTwoCol
            title={<h3>body</h3>}
            text={
              <p>
                Тіло запиту, одне зі списку: <br /> **JSON**. <br /> Об'єкт
                **FormData**. <br /> **Blob/BufferSource** для відправки
                бінарних даних. <br /> **URLSearchParams** для надсилання даних
                у кодуванні `x-www-form-urlencoded`, використовується рідко.
              </p>
            }
          />
          <TableOneCol
            text={
              <p>
                <pre>
                  <code>{postCode2}</code>
                </pre>
              </p>
            }
          />
        </>
      ),
    },
  ];

  const tableFormData = [
    {
      title: "FormData",
      textForSearch:
        "Використовується для відправки різних форм. let formData = new FormData([form]);",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                Використовується для відправки різних форм, при цьому його
                вказують у властивості тіла запиту. <br /> `let formData = new
                FormData([form]);`
              </p>
            }
          />
          <TableOneCol text={<h3>Методи FormData</h3>} />
        </>
      ),
    },
    {
      title: "formData.append(name, value)",
      textForSearch:
        "Додає (створює) нове значення до існуючого ключа. name - Ім'я поля, value - Значення поля.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.append (name, value)</h3>}
          text={
            <p>
              `append()` додає (створює) нове значення до існуючого ключа
              всередині об'єкта **FormData**. <br /> **name** - Ім'я поля.
              <br /> **value** - Значення поля.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.append(name, blob, fileName)",
      textForSearch:
        "Додає Blob або File з вказаним іменем файлу. name - Ім'я поля. Blob, File, USVString, filename.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.append (name, blob, fileName)</h3>}
          text={
            <p>
              **name** - Ім'я поля. <br /> На вибір одне із чотирьох значень:
              <br /> **value** – значення поля. <br /> **Blob** - Незмінні
              необроблені двійкові дані.
              <br /> **File** - Об'єкти, які повертаються в результаті вибору
              користувачем файлів.
              <br /> **USVString** - Набір послідовностей скалярних значень
              Unicode. <br /> **filename** - Ім'я файлу, яке буде відправлено на
              сервер.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.set(name, value)",
      textForSearch: "Діє як append, але дозволяє замінити поле name на нове.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.set (name, value)</h3>}
          text={
            <p>
              Діє як і метод `append`, тільки дозволяє видалити поле `name` і
              написати нове поле.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.set(name, blob, fileName)",
      textForSearch:
        "Діє як append, але дозволяє замінити поле name на нове (для Blob/File).",
      jsx: (
        <TableTwoCol
          title={<h3>formData.set (name, blob, fileName)</h3>}
          text={
            <p>
              Діє як і метод `append`, тільки дозволяє видалити поле `name` і
              написати нове поле.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.delete(name)",
      textForSearch: "Видаляє поле із заданим ім'ям name.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.delete(name)</h3>}
          text={<p>Видаляє поле із заданим ім'ям `name`.</p>}
        />
      ),
    },
    {
      title: "formData.get(name)",
      textForSearch: "Отримує значення поля з ім'ям name.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.get(name)</h3>}
          text={<p>Отримує значення поля з ім'ям `name`.</p>}
        />
      ),
    },
    {
      title: "formData.getAll(name)",
      textForSearch: "Отримує всі значення полів з ім'ям name.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.getAll(name)</h3>}
          text={<p>Отримує всі значення полів з ім'ям `name`.</p>}
        />
      ),
    },
    {
      title: "formData.has(name)",
      textForSearch:
        "Перевіряє наявність поля з ім'ям name. Повертає true або false.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.has(name)</h3>}
          text={
            <p>
              Якщо є поле з ім'ям `name`, то повертає `true`, інакше `false`.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.entries()",
      textForSearch:
        "Повертає ітератор, дозволяючи пройтись по всіх ключах/значеннях. Ключ - USVString, значення - USVString чи Blob.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.entries()</h3>}
          text={
            <p>
              Повертає ітератор, дозволяючи пройтись по всіх ключах/значеннях у
              цьому об'єкті. Ключ кожної пари – це об'єкт **USVString**,
              значення – це **USVString** чи **Blob**.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.keys()",
      textForSearch:
        "Повертає ітератор, дозволяючи пройтись по всіх ключах. Ключі є USVString.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.keys()</h3>}
          text={
            <p>
              Повертає ітератор, дозволяючи пройтись по всіх ключах, що
              містяться в цьому об'єкті. Ключі є **USVString** об'єктами.
            </p>
          }
        />
      ),
    },
    {
      title: "formData.values()",
      textForSearch:
        "Повертає ітератор, дозволяючи пройтись по всіх значеннях. Значення - USVString чи Blob.",
      jsx: (
        <TableTwoCol
          title={<h3>formData.values()</h3>}
          text={
            <p>
              Повертає ітератор, дозволяючи пройтись по всіх значеннях у цьому
              об'єкті. Значення - це **USVString** чи **Blob** об'єкти.
            </p>
          }
        />
      ),
    },
  ];

  const filteredFetch = tableFetch.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredResponse = tableResponse.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredPostFeach = tablePostFeach.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredFormData = tableFormData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredFetch.length > 0 && (
        <Table id="http_fetch">
          <TableBody>
            <TableOneCol text={<h2>Fetch.</h2>} />
            {filteredFetch.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredResponse.length > 0 && (
        <Table id="http_response">
          <TableBody>
            <TableOneCol text={<h3>Response.</h3>} />
            {filteredResponse.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredPostFeach.length > 0 && (
        <Table id="http_postFeach">
          <TableBody>
            <TableOneCol text={<h3>POST-запити</h3>} />
            {filteredPostFeach.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredFormData.length > 0 && (
        <Table id="http_formData">
          <TableBody>
            <TableOneCol text={<h2>FormData</h2>} />
            {filteredFormData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
