import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import ButtonExampleWithBtn from "@core/ButtonExampleWithBtn.tsx";
import { changeAttribute } from "./DomConstPre.tsx";
import { changeAttributeFn } from "./DomFunc.js";
import { IMethodsProps } from "@type/interface.ts";

export default function AttributesClassRU({ searchTerm }: IMethodsProps) {
  const tableAttribute = [
    {
      title: ".hasAttribute",
      category: "DOM",
      textForSearch: "Проверка наличия атрибута.",
      jsx: (
        <TableTwoCol
          title={<h3>.hasAttribute</h3>}
          text={
            <p>
              Проверяет наличие атрибута. <br />
              <code>element.hasAttribute(name)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".getAttribute",
      category: "DOM",
      textForSearch: "Получение значения атрибута.",
      jsx: (
        <TableTwoCol
          title={<h3>.getAttribute</h3>}
          text={
            <p>
              Получает значение атрибута. <br />
              <code>element.getAttribute(name)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".setAttribute",
      category: "DOM",
      textForSearch: "Установка значения атрибута.",
      jsx: (
        <TableTwoCol
          title={<h3>.setAttribute</h3>}
          text={
            <p>
              Устанавливает атрибут. <br />
              <code>element.setAttribute(имя, значение)</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".removeAttribute",
      category: "DOM",
      textForSearch: "Удаление атрибута.",
      jsx: (
        <TableTwoCol
          title={<h3>.removeAttribute</h3>}
          text={
            <p>
              Удаляет атрибут.
              <br />
              <code>element.removeAttribute(name)</code>
            </p>
          }
        />
      ),
    },
    {
      title: "Пример использования атрибутов",
      category: "DOM",
      textForSearch: "Пример использования DOM атрибутов в JavaScript.",
      jsx: (
        <TableOneCol
          text={
            <ButtonExampleWithBtn
              titleButtonExample={"Пример использования"}
              title={
                <p id="formated-text">
                  Есть тег &lt;p id="attribute-text"&gt;&lt;/p&gt;
                  <br />
                  Проверим есть ли в теги id, выведим id и добавим class="text"
                  <br />
                  <br />
                  <span id="attribute-text">Начальный текст.</span>
                </p>
              }
              text={
                <pre>
                  <code>{changeAttribute}</code>
                </pre>
              }
              onClick={changeAttributeFn}
            />
          }
        />
      ),
    },
  ];

  const tableData = [
    {
      title: ".className",
      category: "DOM",
      textForSearch: "Получение/установка значения атрибута class.",
      jsx: (
        <TableTwoCol
          title={<h3>.className</h3>}
          text={
            <p>
              Отвечает за значение атрибута <b>class</b> элемента.
              <br />
              <code>element.className</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".classList",
      category: "DOM",
      textForSearch: "Псевдомассив со всеми классами элемента.",
      jsx: (
        <TableTwoCol
          title={<h3>.classList</h3>}
          text={
            <p>
              Возвращает псевдомассив DOMTokenList, содержащий все классы
              элемента. <br />
              <code>element.classList</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".classList.contains",
      category: "DOM",
      textForSearch: "Проверка наличия класса.",
      jsx: (
        <TableTwoCol
          title={<h3>.classList.contains</h3>}
          text={
            <p>
              Возвращает <b>true/false</b>, в зависимости от того, есть ли у
              элемента класс. <br />
              <code>element.classList.contains("class")</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".classList.add",
      category: "DOM",
      textForSearch: "Добавление класса.",
      jsx: (
        <TableTwoCol
          title={<h3>.classList.add</h3>}
          text={
            <p>
              Добавляет класс. <br />
              <code>element.classList.add("class")</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".classList.remove",
      category: "DOM",
      textForSearch: "Удаление класса.",
      jsx: (
        <TableTwoCol
          title={<h3>.classList.remove</h3>}
          text={
            <p>
              Удаляет класс. <br />
              <code>element.classList.remove("class")</code>
            </p>
          }
        />
      ),
    },
    {
      title: ".classList.toggle",
      category: "DOM",
      textForSearch: "Добавление/удаление класса по условию.",
      jsx: (
        <TableTwoCol
          title={<h3>.classList.toggle</h3>}
          text={
            <p>
              Если класса нет, добавляет его, если есть – удаляет.
              <br />
              <code>element.classList.toggle("class")</code>
            </p>
          }
        />
      ),
    },
  ];

  const filteredAttribute = tableAttribute.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredData = tableData.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.textForSearch.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredAttribute.length > 0 && (
        <Table id="dom_attribute">
          <TableBody>
            <TableOneCol text={<h3>Атрибуты.</h3>} />
            <TableOneCol
              text={
                <p>
                  С помощью нестандартных атрибутов можно привязать к элементу
                  данные, доступные в JavaScript. Это делается с помощью
                  атрибутов с названиями, которые начинаются на <b>data-</b>
                </p>
              }
            />
            {filteredAttribute.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}

      {filteredData.length > 0 && (
        <Table id="dom_classes">
          <TableBody>
            <TableOneCol text={<h3>Классы.</h3>} />
            {filteredData.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
