export const list: string = `
const numbers = [1, 2, 3, 4, 5];

function NumberList() {
  const listItems = numbers.map((number) =>
    <li>{number}</li>
  );
  return <ul>{listItems}</ul>;
}
//  -----------   -----------   -----------
function NumberListSecond() {
  return (
    <ul>
      {numbers.map((number) => (
        <li>{number}</li>
      ))}
    </ul>
  );
}
`;

export const listKey: string = `
const users = [
  { id: 1, name: 'Leo' },
  { id: 2, name: 'Chris' },
  { id: 3, name: 'Mike' }
];

function UserList() {
  const userItems = users.map((user) =>
    <li key={user.id}>
      {user.name}
    </li>
  );
  return <ul>{userItems}</ul>;
}}
//  -----------   -----------   -----------
function UserListSecond() {
  return (
    <ul>
      {users.map((user, index) =>
        <li key={index}>
          {user.name}
        </li>
      )}
    </ul>
  );
}
`;
