import React, { forwardRef } from "react";

const MyInput = forwardRef((props, ref) => {
  return (
    <input
      style={{
        height: "30px",
        borderRadius: "8px",
        marginRight: "5px",
        paddingLeft: "7px",
      }}
      type="text"
      ref={ref}
      {...props}
    />
  );
});

export default MyInput;
