import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableRow from "@mui/material/TableRow";
import TableCell from "@mui/material/TableCell";
import TableOneCol from "@core/TableOneCol.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function ReactTitleRU({ searchTerm }: IMethodsProps) {
  const reactTitle = [
    {
      title: "React",
      jsx: (
        <>
          <TableOneCol
            text={
              <p>
                React — это открытая JavaScript-библиотека для создания
                пользовательских интерфейсов (UI). Она разработана и
                поддерживается компанией Meta (ранее Facebook) и сообществом
                разработчиков. React позволяет создавать сложные, интерактивные
                веб-приложения, разбивая их на небольшие, независимые части,
                которые называются компонентами.
              </p>
            }
          />
        </>
      ),
    },
    {
      title: "React",
      jsx: (
        <>
          <TableOneCol
            text={
              <div>
                <p>React идеально подходит для создания:</p>
                <ul>
                  <li>
                    Одностраничных приложений (SPA): Веб-приложения, которые
                    загружают одну HTML-страницу, а затем динамически обновляют
                    ее содержимое. Примеры: Gmail, Trello.
                  </li>
                  <li>
                    Интерактивных элементов: Сложные формы, динамические панели
                    управления, интерактивные карты.
                  </li>
                  <li>
                    Мобильных приложений: С помощью React Native можно
                    использовать знания React для разработки приложений для iOS
                    и Android.
                  </li>
                </ul>
              </div>
            }
          />
        </>
      ),
    },
  ];

  const filteredTitle = reactTitle.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredTitle.length > 0 && (
        <Table id="react_title">
          <TableBody>
            <TableRow>
              <TableCell style={{ border: "none", padding: "5px" }}>
                <h1>Работа с React.</h1>
              </TableCell>
            </TableRow>
            {filteredTitle.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
