import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Arrow from "@core/Arrow";
import MenuHtml from "./MenuHtml.tsx";
import MetaTagUA from "./MetaTagUA.tsx";
import SectioningUA from "./SectioningUA.tsx";
import TextUA from "./TextUA.tsx";
import TextSemanticsUA from "./TextSemanticsUA.tsx";
import MultimediaUA from "./MultimediaUA.tsx";
import EmbeddedContentUA from "./EmbeddedContentUA.tsx";
import ScriptingUA from "./ScriptingUA.tsx";
import EditsUA from "./EditsUA.tsx";
import TableUA from "./TableUA.tsx";
import FormUA from "./FormUA.tsx";
import InteractiveUA from "./InteractiveUA.tsx";
import "./html.scss";
import AppBar from "@components/AppBar/AppBar.tsx";
import HtmlTitleUA from "./HtmlTitleUA.tsx";

export default function HtmlUA() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term: React.SetStateAction<string>) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages active"}
        toUA={"/html/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages"}
        toRU={"/html/ru"}
        titleLangRU={"RU"}
        toHome={"/"}
        toHtml={"/html/ua"}
        toCss={"/css/ua"}
        toScss={"/scss/ua"}
        toJS={"/js/ua"}
        toDom={"/dom/ua"}
        toBom={"/bom/ua"}
        toHttp={"/http/ua"}
        toReact={"/react/ua"}
        toRedux={"/redux/ua"}
        toTS={"/ts/ua"}
        toNext={"/next/ua"}
        nameHome={"Головна сторінка"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
        page={"HTML5"}
        onClick={handleMenuInfoOpen}
        buttonRef={buttonRef}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuHtml
              sectionFirst={"Метадані документа"}
              sectionSecond={"Секціонування змісту"}
              sectionThird={"Текстовий зміст"}
              sectionFourth={"Вбудовані текстові семантики"}
              sectionFifth={"Зображення та мультимедіа"}
              sectionSixth={"Вбудований зміст"}
              sectionSeventh={"Скріптінг"}
              sectionEighth={"Розмежувальні виправлення"}
              sectionNinth={"Зміст таблиць"}
              sectionTenth={"Форми"}
              sectionEleventh={"Інтерактивні елементи"}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}
        <TableContainer>
          <HtmlTitleUA searchTerm={searchTerm} />
          <MetaTagUA searchTerm={searchTerm} />
          <SectioningUA searchTerm={searchTerm} />
          <TextUA searchTerm={searchTerm} />
          <TextSemanticsUA searchTerm={searchTerm} />
          <MultimediaUA searchTerm={searchTerm} />
          <EmbeddedContentUA searchTerm={searchTerm} />
          <ScriptingUA searchTerm={searchTerm} />
          <EditsUA searchTerm={searchTerm} />
          <TableUA searchTerm={searchTerm} />
          <FormUA searchTerm={searchTerm} />
          <InteractiveUA searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a
            target="_blank"
            href="https://developer.mozilla.org/en-US/docs/Web/HTML"
          >
            Документація HTML5
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
