import React, { useState, useEffect, useRef } from "react";
import MenuHomePage from "@components/Menu/MenuHomePage.tsx";
import { IAppBarProps } from "@type/interface.ts";
import "./appBar.scss";

export default function AppBarHome({ ...props }: IAppBarProps) {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuOpen = () => {
    setIsMenuOpen((prevIsMenuOpen) => !prevIsMenuOpen);
  };

  const handleMenuClose = () => {
    setIsMenuOpen(false);
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        isMenuOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isMenuOpen]);

  return (
    <div className="header-container-wrapper">
      <header className="header">
        <div className="header-homePage">
          <div className="menu">
            <button
              className="menu-btn"
              aria-label="open drawer"
              onClick={handleMenuOpen}
              ref={buttonRef}
            ></button>
          </div>
        </div>
      </header>

      {isMenuOpen && (
        <MenuHomePage ref={menuRef} {...props} onClose={handleMenuClose} />
      )}
    </div>
  );
}
