export const typeEnumJs = `var Level;
(function (Level) {
    Level[Level["Beginner"] = 0] = "Beginner";
    Level[Level["Intermediate"] = 1] = "Intermediate";
    Level[Level["Advanced"] = 2] = "Advanced";
})(Level || (Level = {}));

let myLevel = Level.Intermediate;
let myLevel2 = Level[0];
console.log(myLevel); // 1
console.log(myLevel2); // Beginner

var Color;
(function (Color) {
    Color[Color["Red"] = 1] = "Red";
    Color[Color["Green"] = 2] = "Green";
    Color[Color["Blue"] = 4] = "Blue";
    Color[Color["Black"] = 5] = "Black";
})(Color || (Color = {}));

let green = Color.Green;
let color = Color[0];
let blue = Color[4];
let black = Color[5];

console.log(green); // 2
console.log(color); // undefined 
console.log(blue); // Blue
console.log(black); // Black "Black" 
`;

export const typeEnumTs = `enum Level {
    Beginner,
    Intermediate,
    Advanced,
}
              
let myLevel = Level.Intermediate;
let myLevel2 = Level[0];
              
console.log(myLevel); // 1
console.log(myLevel2); // Beginner

enum Color {
    Red = 1,
    Green = 2,
    Blue = 4,
    Black,
}

let green = Color.Green;
let color = Color[0];
let blue = Color[4];
let black = Color[5];

console.log(green); // 2
console.log(color); // undefined
console.log(blue); // Blue
console.log(black); // Black "Black" 
`;

