export const typeInterfaceJs = `const user = {
    name: 'John',
    age: 30,
    sayHello() {
        console.log(\`Hello, my name is \${this.name}.\`);
    }
};

user.sayHello(); // "Hello, my name is John."
`;

export const typeInterfaceTs = `  interface User {
    name: string;
    age: number;
    sayHello(): void;
  }
  
  const user: User = {
    name: 'John',
    age: 30,
    sayHello() {
      console.log(\`Hello, my name is \${this.name}.\`);
    }
  };
  
  user.sayHello(); // "Hello, my name is John."
`;

