import React, { forwardRef } from "react";
import ButtonLanguages from "@core/ButtonLanguages.tsx";
import "./menu.scss";
import { IMenuProps } from "@type/interface.ts";

const MenuHomePage = forwardRef<HTMLDivElement, IMenuProps>(
  ({ onClose, ...props }, ref) => {
    return (
      <div ref={ref} className="container-custom">
        <div className="menu-nav-homePage">
          <div className="menu-nav-lang">
            <ButtonLanguages
              className={props.classLangUA}
              to={props.toUA}
              titleLanguage={props.titleLangUA}
            />
            <ButtonLanguages
              className={props.classLangRU}
              to={props.toRU}
              titleLanguage={props.titleLangRU}
            />
          </div>{" "}
        </div>
      </div>
    );
  }
);

export default MenuHomePage;
