import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Arrow from "@core/Arrow";
import MenuTs from "./MenuTs.tsx";
import "./ts.scss";
import AppBar from "@components/AppBar/AppBar.tsx";
import ComponentsUA from "./ComponentsUA.tsx";
import TypesUA from "./TypesUA.tsx";
import ClassesUA from "./ClassesUA.tsx";
import AccessModifiersUA from "./AccessModifiersUA.tsx";
import OperatorsUA from "./OperatorsUA.tsx";
import DecoratorUA from "./DecoratorUA.tsx";
import GenericsUA from "./GenericsUA.tsx";
import TypeAssertionUA from "./TypeAssertionUA.tsx";
import TypeGuardsUA from "./TypeGuardsUA.tsx";
import MappedTypesUA from "./MappedTypesUA.tsx";
import UtilityTypesUA from "./UtilityTypesUA.tsx";
import SolidUA from "./SolidUA.tsx";
import TSTitleUA from "./TSTitleUA.tsx";

export default function TsUA() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term: React.SetStateAction<string>) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages active"}
        toUA={"/ts/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages "}
        toRU={"/ts/ru"}
        titleLangRU={"RU"}
        toHome={"/"}
        toHtml={"/html/ua"}
        toCss={"/css/ua"}
        toScss={"/scss/ua"}
        toJS={"/js/ua"}
        toDom={"/dom/ua"}
        toBom={"/bom/ua"}
        toHttp={"/http/ua"}
        toReact={"/react/ua"}
        toRedux={"/redux/ua"}
        toTS={"/ts/ua"}
        toNext={"/next/ua"}
        nameHome={"Головна сторінка"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
        page={"TypeScript"}
        onClick={handleMenuInfoOpen}
        buttonRef={buttonRef}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuTs
              sectionFirst={"Компоненти - Components"}
              sectionSecond={"Типи даних - Types"}
              sectionThird={"Класи - Classes"}
              sectionFourth={"Модифікатори доступу - Access Modifiers"}
              sectionFifth={"Оператори - Operators"}
              sectionSixth={"Декоратори - Decorators"}
              sectionSeventh={"Дженерики - Generics"}
              sectionEighth={"Затвердження типів - Type Assertion"}
              sectionNinth={"Захистники типу - Type Guards"}
              sectionTenth={"Відображувані типи - Mapped Types"}
              sectionEleventh={"Утилітарні типи - Utility Types"}
              sectionTwelfth={"SOLID"}
              sectionThirteenth={""}
              sectionFourteenth={""}
              sectionFifteenth={""}
              sectionSixteenth={""}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}

        <TableContainer>
          <TSTitleUA searchTerm={searchTerm} />
          <ComponentsUA searchTerm={searchTerm} />
          <TypesUA searchTerm={searchTerm} />
          <ClassesUA searchTerm={searchTerm} />
          <AccessModifiersUA searchTerm={searchTerm} />
          <OperatorsUA searchTerm={searchTerm} />
          <DecoratorUA searchTerm={searchTerm} />
          <GenericsUA searchTerm={searchTerm} />
          <TypeAssertionUA searchTerm={searchTerm} />
          <TypeGuardsUA searchTerm={searchTerm} />
          <MappedTypesUA searchTerm={searchTerm} />
          <UtilityTypesUA searchTerm={searchTerm} />
          <SolidUA searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a target="_blank" href="https://www.typescriptlang.org/">
            Документація TypeScript
          </a>
          <a target="_blank" href="https://www.tutorialsteacher.com/typescript">
            Toturial TypeScript
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}

