import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import TableTwoCol from "@core/TableTwoCol.tsx";
import { IMethodsProps } from "@type/interface.ts";
import TimerFC from "./TimerFC.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import {
  clockClass,
  clockFunction,
  lifecycleCC,
  lifecycleFC,
} from "./LifecycleConstPre.ts";
import TimerCC from "./TimerCC.jsx";
import ClockFunction from "./ClockFunction.jsx";

export default function LifecycleRU({ searchTerm }: IMethodsProps) {
  const reactLifecyc = [
    {
      title: "Жизненный цикл, Lifecycle",
      jsx: (
        <>
          <TableOneCol
            text={
              <div>
                <p>
                  Жизненный цикл компонента — это последовательность событий,
                  которые происходят от момента его создания до удаления. В
                  React есть три основные фазы:
                </p>
                <ul>
                  <li>
                    Монтаж (Mounting): Компонент создается и впервые добавляется
                    в DOM.
                  </li>
                  <li>
                    Обновление (Updating): Компонент обновляется из-за изменений
                    состояния или пропсов.
                  </li>
                  <li>Демонтаж (Unmounting): Компонент удаляется из DOM.</li>
                </ul>
              </div>
            }
          />
        </>
      ),
    },
    {
      title: "Жизненный цикл, Lifecycle function",
      jsx: (
        <TableOneCol
          text={
            <p>
              Функциональные компоненты. Используют хук useEffect для работы с
              побочными эффектами и жизненным циклом.
            </p>
          }
        />
      ),
    },
    {
      title: "Жизненный цикл, Lifecycle function",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример Lifecycle function"}
              title={
                <>
                  <ul>
                    <li>
                      const [seconds, setSeconds] = useState(0); <br />
                      Сохраняет текущее количество секунд. Начальное значение —
                      0.
                    </li>
                    <li>
                      const [isActive, setIsActive] = useState(false); <br />
                      Логическая переменная, которая определяет, работает ли
                      таймер сейчас. Начальное значение — false.
                    </li>
                    <li>
                      useEffect срабатывает только тогда, когда изменяется
                      значение isActive.
                    </li>
                    <li>
                      isActive становится true, создается интервал
                      (setInterval), который обновляет состояние seconds каждую
                      секунду.
                    </li>
                    <li>
                      return () возвращается из useEffect и срабатывает при
                      очистке. Она гарантирует, что интервал будет остановлен
                      (clearInterval), когда компонент будет демонтирован или
                      когда isActive снова изменится (например, при нажатии
                      кнопки "Stop"). Это предотвращает утечки памяти.
                    </li>
                  </ul>
                  <br />
                  <TimerFC time="Прошло" second="секунд" />
                </>
              }
              text={
                <pre>
                  <code>{lifecycleFC}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
    {
      title: "Жизненный цикл, Lifecycle function",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример Lifecycle function"}
              title={
                <>
                  <ul>
                    <li>
                      const [dateNow, setDate] = useState(getTime()); <br />
                      dateNow. Переменная состояния, которая хранит объект с
                      датой и временем.
                      <br />
                      setDate. Функция для обновления dateNow.
                    </li>
                    <li>
                      setInterval: Эта функция запускает таймер, который
                      вызывает колбек-функцию каждые 1000 миллисекунд (1
                      секунду).
                    </li>
                    <li>
                      setDate(getTime()): Колбек обновляет состояние dateNow
                      новым значением текущего времени, что вызывает повторный
                      рендеринг компонента.
                    </li>
                    <li>
                      Функция getTime() создает новый объект Date и возвращает
                      его в объекте date. Это хорошая практика, хотя можно было
                      бы вернуть объект Date напрямую.
                    </li>
                  </ul>
                  <br />
                  <ClockFunction />
                </>
              }
              text={
                <pre>
                  <code>{clockFunction}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
    {
      title: "Жизненный цикл, Lifecycle class component",
      jsx: (
        <TableOneCol
          text={
            <p>
              Классовые компоненты. Используют специальные методы жизненного
              цикла, такие как:
            </p>
          }
        />
      ),
    },
    {
      title: "componentDidMount",
      jsx: (
        <TableTwoCol
          title={<h3>componentDidMount</h3>}
          text={
            <p>
              Метод вызывается один раз, сразу после того, как компонент был
              отрендерен и вставлен в DOM.
            </p>
          }
        />
      ),
    },
    {
      title: "componentDidUpdate",
      jsx: (
        <TableTwoCol
          title={<h3>componentDidUpdate</h3>}
          text={
            <p>
              Метод вызывается сразу после того, как компонент был обновлен
              (т.е. когда изменились его пропсы или состояние).
            </p>
          }
        />
      ),
    },
    {
      title: "componentWillUnmount",
      jsx: (
        <TableTwoCol
          title={<h3>componentWillUnmount</h3>}
          text={
            <p>
              Метод вызывается непосредственно перед тем, как компонент будет
              удален из DOM.
            </p>
          }
        />
      ),
    },
    {
      title: "Жизненный цикл, Lifecycle class component",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример Lifecycle class component"}
              title={
                <>
                  <ul>
                    <li>
                      Инициализация состояния. В классовых компонентах состояние
                      инициализируется в конструкторе (constructor) как объект
                      this.state.
                    </li>
                    <li>
                      componentDidMount() отсутствует, потому что вся логика
                      запуска и остановки таймера была перенесена в метод
                      componentDidUpdate().
                      <pre>
                        <code>{`componentDidMount() {
  this.setState({ isActive: true });
}`}</code>
                      </pre>
                    </li>
                    <li>
                      componentDidUpdate: Этот метод используется для
                      реагирования на изменения состояния. Мы проверяем,
                      изменилось ли значение isActive, и если да, то запускаем
                      или останавливаем интервал.
                    </li>
                    <li>
                      componentWillUnmount: Это критически важный метод для
                      очистки ресурсов. Здесь мы останавливаем интервал, чтобы
                      он не работал после удаления компонента из DOM,
                      предотвращая утечку памяти.
                    </li>
                    <li>
                      Вместо setSeconds и setIsActive для обновления состояния
                      используется метод this.setState().
                    </li>
                    <li>
                      Методы компонента (например, handleStart) необходимо
                      привязать к this в конструкторе, чтобы они имели доступ к
                      состоянию компонента. Это делается с помощью
                      this.handleStart = this.handleStart.bind(this);
                    </li>
                  </ul>
                  <br />
                  <TimerCC time="Прошло" second="секунд" />
                </>
              }
              text={
                <pre>
                  <code>{lifecycleCC}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
    {
      title: "Жизненный цикл, Lifecycle class component",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример Lifecycle class component"}
              title={
                <>
                  <ul>
                    <li>
                      constructor(props): Метод-конструктор, который вызывается
                      при создании экземпляра компонента.
                    </li>
                    <li>
                      super(props): Всегда вызывается, чтобы передать пропсы в
                      родительский класс React.Component.
                    </li>
                    <li>
                      this.state: Состояние компонента инициализируется как
                      объект, который содержит текущую дату.
                    </li>
                    <li>
                      componentDidMount(): Этот метод срабатывает сразу после
                      того, как компонент был отрендерен в DOM. Он идеально
                      подходит для запуска интервалов или загрузки данных. Здесь
                      создается таймер, который вызывает метод tick() каждую
                      секунду. timerID сохраняется в поле класса, чтобы его
                      можно было очистить позже.
                    </li>
                    <li>
                      componentWillUnmount(): Этот метод срабатывает
                      непосредственно перед тем, как компонент будет удален из
                      DOM.
                    </li>
                    <li>
                      clearInterval(this.timerID): Критически важная часть. Она
                      останавливает таймер, созданный в componentDidMount, чтобы
                      предотвратить утечки памяти. Это аналог функции очистки в
                      useEffect.
                    </li>
                    <li>
                      tick(): Это метод, который обновляет состояние компонента.
                      Каждый раз, когда вызывается tick(), создается новый
                      объект Date и устанавливается как новое состояние, что
                      приводит к повторному рендерингу компонента.
                    </li>
                  </ul>
                  <br />
                  <ClockFunction />
                </>
              }
              text={
                <pre>
                  <code>{clockClass}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredReactLifecyc = reactLifecyc.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredReactLifecyc.length > 0 && (
        <Table id="react_lifecycle">
          <TableBody>
            <TableOneCol text={<h3>Жизненный цикл (Lifecycle).</h3>} />
            {filteredReactLifecyc.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
