import React, { useState, useEffect, useRef } from "react";
import { Box, Button, Typography, Grid } from "@mui/material";
import { Link } from "react-router-dom";
import MenuComponent from "@components/Menu/Menu.tsx";
import Search from "./Search.tsx";
import { IMenuAppBarProps } from "@type/interface.ts";
import "./appBar.scss";

export default function SearchAppBar({
  onSearch,
  onClick,
  page,
  buttonRef,
  ...props
}: IMenuAppBarProps & { onSearch: (searchTerm: string) => void }) {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const navRef = useRef<HTMLDivElement>(null);
  const navBtnRef = useRef<HTMLButtonElement>(null);

  const handleMenuOpen = () => {
    setIsMenuOpen((prevIsMenuOpen) => !prevIsMenuOpen);
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        isMenuOpen &&
        navRef.current &&
        !navRef.current.contains(event.target as Node) &&
        navBtnRef.current &&
        !navBtnRef.current.contains(event.target as Node)
      ) {
        setIsMenuOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isMenuOpen]);

  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value;
    setSearchTerm(value);
    onSearch(value);
  };

  const handleClearSearch = () => {
    setSearchTerm("");
    onSearch("");
  };

  return (
    <div className="header-container-wrapper">
      <header className="header">
        <Grid container className="header-allPage">
          <Grid item xs={12} sm={6}>
            <div className="menu">
              <button
                className="menu-btn"
                aria-label="open drawer"
                onClick={handleMenuOpen}
                ref={navBtnRef}
              ></button>

              <Box className="menu-logo">
                <Button
                  id="menu-btnInfo"
                  aria-label="open drawer"
                  onClick={onClick}
                  ref={buttonRef}
                >
                  {page}
                </Button>
              </Box>

              {/* <Box className="menu-logo">
                <Typography
                  variant="h6"
                  noWrap
                  sx={{
                    color: "silver",
                  }}
                >
                  Front-End
                </Typography>
                <Link className="menu-logo-logoLink" to={props.toHome}></Link>
              </Box> */}
            </div>
          </Grid>

          <Grid item xs={12} sm={3}>
            <Search
              onChange={handleSearchChange}
              onClear={handleClearSearch}
              searchTerm={searchTerm}
            />
          </Grid>
        </Grid>
      </header>

      {isMenuOpen && (
        <MenuComponent ref={navRef} {...props} onClose={handleMenuOpen} />
      )}
    </div>
  );
}
