import React, { useState } from "react";
import Button from "@mui/material/IconButton";
import "./buttonExample.scss";
import { IButtonExampleOneColProps } from "@type/interface";

export default function ButtonExampleOneCol({
  titleButtonExample,
  title,
}: IButtonExampleOneColProps) {
  const [isExampleOpen, setIsExampleOpen] = useState(false);

  const handleMenuInfoOpen = () => {
    setIsExampleOpen(!isExampleOpen);
  };

  // const handleMenuInfoClose = () => {
  //   setIsExampleOpen(false);
  // };

  const tableRowStyle = {
    width: "100%",
    display: "flex",
  };
  return (
    <div id="menu-example">
      <Button className="menu-example-btn" onClick={handleMenuInfoOpen}>
        {titleButtonExample}
      </Button>
      {isExampleOpen && (
        <div style={tableRowStyle} className="table-example">
          <div id={"td"} style={{ border: "none" }} className="colThree">
            {title}
          </div>
        </div>
      )}
    </div>
  );
}
