export const firstProps: string = `
import React, { useState } from "react";

export default function FirstProps({ 
  enterName,
  names,
  titleOne,
  hello,
  titleTwo,
  btn, }) {
    const [name, setName] = useState("");

    const handleName = () => {
      setName(prompt({ enterName }));
    };

    return (
        <>
            <span>{titleOne}</span> <br />
            <span">
                {hello}, {names}
            </span>            
            <hr />
            <span>{titleTwo} </span> <br />
            <span">
                {hello}, {name}
            </span>
            <br />
            <button onClick={handleName}>
                {btn}
            </button>
        </>
    );
}
`;

