export const secondProps: string = `
// Дочірній компонент Card, 
// який приймає пропси title і description

function Card(props) {
  return (
    <div className="card">
      <h2>{props.title}</h2>
      <p>{props.description}</p>
    </div>
  );
}

// Батьківський компонент, який використовує Card
function App() {
  return (
    <div>
      <Card
        title="Мій перший компонент"
        description="Текст props."
      />
      <Card
        title="Другий компонент"
        description="Текст props."
      />
    </div>
  );
}
`;

