import React, { useState, useEffect, useRef } from "react";
import Container from "@mui/material/Container";
import TableContainer from "@mui/material/TableContainer";
import Arrow from "@core/Arrow";
import MenuTs from "./MenuTs.tsx";
import "./ts.scss";
import AppBar from "@components/AppBar/AppBar.tsx";
import ComponentsRU from "./ComponentsRU.tsx";
import TypesRU from "./TypesRU.tsx";
import ClassesRU from "./ClassesRU.tsx";
import AccessModifiersRU from "./AccessModifiersRU.tsx";
import OperatorsRU from "./OperatorsRU.tsx";
import DecoratorRU from "./DecoratorRU.tsx";
import GenericsRU from "./GenericsRU.tsx";
import TypeAssertionRU from "./TypeAssertionRU.tsx";
import TypeGuardsRU from "./TypeGuardsRU.tsx";
import MappedTypesRU from "./MappedTypesRU.tsx";
import UtilityTypesRU from "./UtilityTypesRU.tsx";
import SolidRU from "./SolidRU.tsx";
import TSTitleRU from "./TSTitleRU.tsx";

export default function TsRU() {
  const [isMenuInfoOpen, setIsMenuInfoOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const handleMenuInfoOpen = () => {
    setIsMenuInfoOpen(!isMenuInfoOpen);
  };

  const handleMenuInfoClose = () => {
    setIsMenuInfoOpen(false);
  };

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (
        isMenuInfoOpen &&
        menuRef.current &&
        !menuRef.current.contains(event.target as Node) &&
        buttonRef.current &&
        !buttonRef.current.contains(event.target as Node)
      ) {
        setIsMenuInfoOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);

    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [isMenuInfoOpen]);

  const handleSearch = (term: React.SetStateAction<string>) => {
    setSearchTerm(term);
  };

  return (
    <>
      <AppBar
        onSearch={handleSearch}
        classLangUA={"buttonLanguages"}
        toUA={"/ts/ua"}
        titleLangUA={"UA"}
        classLangRU={"buttonLanguages active"}
        toRU={"/ts/ru"}
        titleLangRU={"RU"}
        toHome={"/home/ru"}
        toHtml={"/html/ru"}
        toCss={"/css/ru"}
        toScss={"/scss/ru"}
        toJS={"/js/ru"}
        toDom={"/dom/ru"}
        toBom={"/bom/ru"}
        toHttp={"/http/ru"}
        toReact={"/react/ru"}
        toRedux={"/redux/ru"}
        toTS={"/ts/ru"}
        toNext={"/next/ru"}
        nameHome={"Главная страница"}
        nameHtml={"HTML5"}
        nameCss={"CSS"}
        nameScss={"SCSS"}
        nameJS={"JavaScript"}
        nameDom={"DOM"}
        nameBom={"BOM"}
        nameHttp={"HTTP"}
        nameReact={"React"}
        nameRedux={"Redux"}
        nameTS={"TypeScript"}
        nameNext={"NextJS"}
        page={"TypeScript"}
        onClick={handleMenuInfoOpen}
        buttonRef={buttonRef}
      />
      <Container style={{ width: "100%", maxWidth: "none" }}>
        {isMenuInfoOpen && (
          <div ref={menuRef}>
            <MenuTs
              sectionFirst={"Компоненты - Components"}
              sectionSecond={"Типы данных - Types"}
              sectionThird={"Классы - Classes"}
              sectionFourth={"Модификаторы доступа - Access Modifiers"}
              sectionFifth={"Операторы - Operators"}
              sectionSixth={"Декораторы - Decorators"}
              sectionSeventh={"Дженерики - Generics"}
              sectionEighth={"Утверждение типов - Type Assertion"}
              sectionNinth={"Защитники типа - Type Guards"}
              sectionTenth={"Отображаемые типы - Mapped Types"}
              sectionEleventh={"Утилитарные типы - Utility Types"}
              sectionTwelfth={"SOLID"}
              sectionThirteenth={""}
              sectionFourteenth={""}
              sectionFifteenth={""}
              sectionSixteenth={""}
              onClose={handleMenuInfoClose}
            />
          </div>
        )}

        <TableContainer>
          <TSTitleRU searchTerm={searchTerm} />
          <ComponentsRU searchTerm={searchTerm} />
          <TypesRU searchTerm={searchTerm} />
          <ClassesRU searchTerm={searchTerm} />
          <AccessModifiersRU searchTerm={searchTerm} />
          <OperatorsRU searchTerm={searchTerm} />
          <DecoratorRU searchTerm={searchTerm} />
          <GenericsRU searchTerm={searchTerm} />
          <TypeAssertionRU searchTerm={searchTerm} />
          <TypeGuardsRU searchTerm={searchTerm} />
          <MappedTypesRU searchTerm={searchTerm} />
          <UtilityTypesRU searchTerm={searchTerm} />
          <SolidRU searchTerm={searchTerm} />
        </TableContainer>
        <footer className="footer">
          <a target="_blank" href="https://www.typescriptlang.org/">
            Документация TypeScript
          </a>
          <a target="_blank" href="https://www.tutorialsteacher.com/typescript">
            Toturial TypeScript
          </a>
        </footer>
      </Container>
      <Arrow />
    </>
  );
}
