import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import { IMethodsProps } from "@type/interface.ts";

export default function StateRU({ searchTerm }: IMethodsProps) {
  const reactState = [
    {
      title: "Состояние (State)",
      jsx: (
        <>
          <TableOneCol
            text={
              <div>
                <p>
                  Состояние — это объект JavaScript, который содержит данные,
                  принадлежащие компоненту. Эти данные могут изменяться со
                  временем, и когда это происходит, React автоматически
                  обновляет компонент, чтобы отобразить новые данные. Основные
                  правила работы с состоянием:
                </p>
                <ul>
                  <li>
                    Инициализация: Состояние нужно инициализировать. В
                    функциональных компонентах это делается с помощью хука
                    useState.
                  </li>
                  <li>
                    Обновление: Никогда не изменяйте состояние напрямую! Всегда
                    используйте специальные функции, предоставленные React
                    (например, setCount в useState или this.setState в классовых
                    компонентах). Это гарантирует, что React правильно
                    отслеживает изменения и обновляет интерфейс.
                  </li>
                  <li>
                    Не мутируйте состояние: Состояние нужно рассматривать как
                    неизменное (immutable). Вместо того, чтобы изменять
                    существующий объект, создавайте новый с обновленными
                    данными.
                  </li>
                </ul>
              </div>
            }
          />
        </>
      ),
    },
    {
      title: "Состояние (State)",
      jsx: (
        <>
          <TableOneCol
            text={
              <pre>
                <code>{`  import React, { useState } from 'react';
  function LikeButton() {
    const [likes, setLikes] = useState(0);
    return (
      <button onClick={() => setLikes(likes + 1)}>
        {likes} Лайков
      </button>
    );
  }
    
  Здесь likes — это состояние, а setLikes — функция для его обновления.
  `}</code>
              </pre>
            }
          />
        </>
      ),
    },
  ];

  const filteredReactState = reactState.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );
  return (
    <>
      {filteredReactState.length > 0 && (
        <Table id="react_state">
          <TableBody>
            <TableOneCol text={<h3>Состояние (State).</h3>} />
            {filteredReactState.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
