import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { IMethodsProps } from "@type/interface.ts";
import FriendsList from "./FriendsList";
import { friendsList } from "./UseDebugValueConstPre";

export default function UseDebugValueRU({ searchTerm }: IMethodsProps) {
  const useDebugValue = [
    {
      title: "useDebugValue",
      jsx: (
        <TableOneCol
          text={
            <>
              <p>
                useDebugValue — это специальный хук, предназначенный для
                использования внутри ваших собственных (custom) хуков. Его
                единственная цель — отображать значения в DevTools React. Это
                помогает вам отлаживать собственные хуки, позволяя видеть, какое
                значение они возвращают, без необходимости добавлять
                console.log.
                <ul>
                  useDebugValue принимает два аргумента:
                  <li>
                    value - значение, которое вы хотите отобразить в DevTools.
                  </li>
                  <li>
                    format (необязательный) - функция форматирования, которая
                    принимает value и возвращает отформатированную строку.
                  </li>
                </ul>
              </p>
            </>
          }
        />
      ),
    },
    {
      title: "useDebugValue",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Пример useDebugValue"}
              title={
                <>
                  <FriendsList />
                  <ul>
                    useFriendStatus:
                    <li>
                      isOnline инициализируется как null, что означает, что
                      статус еще неизвестен.
                    </li>
                    <li>
                      useEffect - имитирует запрос к сети с помощью setTimeout.
                      Через секунду он обновляет состояние, устанавливая
                      isOnline в true для друзей с четным ID и в false для
                      нечетных.
                    </li>
                    <li>
                      useDebugValue - этот хук является основным здесь. Он
                      позволяет вам просматривать значение isOnline
                      непосредственно в DevTools React. Если друг онлайн, в
                      DevTools вы увидите метку Online, а если офлайн — Offline.
                    </li>
                  </ul>
                  <ul>
                    FriendListItem
                    <li>Он принимает friendID как пропс.</li>
                    <li>
                      Вызывает useFriendStatus(friendID), чтобы получить статус
                      друга.
                    </li>
                    <li>
                      В зависимости от значения isOnline, меняет цвет текста на
                      зеленый (Online) или красный (Offline) и отображает
                      соответствующий текст.
                    </li>
                  </ul>
                  <p>
                    FriendListItem рендерит простой список &lt;ul&gt; с двумя
                    элементами &lt;li&gt;, используя FriendListItem для каждого
                    друга с ID 1 и 2.
                  </p>
                </>
              }
              text={
                <pre>
                  <code>{friendsList}</code>
                </pre>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredUseDebugValue = useDebugValue.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredUseDebugValue.length > 0 && (
        <Table id="react_useDebugValue">
          <TableBody>
            <TableOneCol text={<h3>useDebugValue.</h3>} />
            {filteredUseDebugValue.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
