import React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableOneCol from "@core/TableOneCol.tsx";
import ButtonExample from "@core/ButtonExample.tsx";
import { funcComponent, classComponent } from "./ComponentsConstPre.ts";
import { IMethodsProps } from "@type/interface.ts";

export default function ComponentsUA({ searchTerm }: IMethodsProps) {
  const tsComponents = [
    {
      title: "Components",
      jsx: (
        <TableOneCol
          text={
            <p>
              У TypeScript, коли ви створюєте компоненти React, ви додаєте типи
              до їхніх пропсів, стану та інших змінних. Це дозволяє компілятору
              TypeScript перевіряти ваш код на помилки, пов'язані з типами, ще
              до його виконання. Найкращий спосіб типізувати компонент — це
              створити інтерфейс або тип для його пропсів. Це робить ваш код
              самодокументованим і запобігає передачі невірних даних.
            </p>
          }
        />
      ),
    },
    {
      title: "Components",
      jsx: (
        <TableOneCol
          text={
            <ButtonExample
              titleButtonExample={"Приклад"}
              title={
                <>
                  <h3>Function component</h3>
                  <pre>
                    <code>{funcComponent}</code>
                  </pre>
                </>
              }
              text={
                <>
                  <h3> Class component</h3>
                  <pre>
                    <code>{classComponent}</code>
                  </pre>
                </>
              }
            />
          }
        />
      ),
    },
  ];

  const filteredComponents = tsComponents.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      {filteredComponents.length > 0 && (
        <Table id="ts_components">
          <TableBody>
            <TableOneCol text={<h2>Components - Компоненти.</h2>} />
            {filteredComponents.map((item, index) => (
              <React.Fragment key={index}>{item.jsx}</React.Fragment>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
}
